// ══════════════════════════════════════════════════════════════════
//  SES (Web Audio API) — hiç ses dosyası yok, hepsi sentezleniyor.
//  AudioContext yalnızca ilk kullanıcı etkileşiminde açılır; tarayıcı
//  otomatik oynatmayı engellediği için sessizce başarısız olur.
// ══════════════════════════════════════════════════════════════════
const SFX_KEY="fc_sfx";
const sfxSettings={on:true,vol:0.5};
try{
  const raw=localStorage.getItem(SFX_KEY);
  if(raw){const d=JSON.parse(raw);if(typeof d.on==="boolean")sfxSettings.on=d.on;
    if(typeof d.vol==="number")sfxSettings.vol=Math.max(0,Math.min(1,d.vol));}
}catch(e){}
const saveSfxSettings=()=>{try{localStorage.setItem(SFX_KEY,JSON.stringify(sfxSettings));}catch(e){}};

let _ac=null;
function audioCtx(){
  if(_ac)return _ac;
  try{
    const AC=window.AudioContext||window.webkitAudioContext;
    if(!AC)return null;
    _ac=new AC();
  }catch(e){return null;}
  return _ac;
}
// Tek bir ton. gain değerleri kullanıcı ses seviyesiyle çarpılır.
function sfxTone(ctx,{freq=440,type="sine",dur=0.15,gain=0.2,delay=0,slideTo=null,attack=0.01}){
  const t0=ctx.currentTime+delay;
  const v=Math.max(0.0001,gain*sfxSettings.vol);
  const osc=ctx.createOscillator();
  const g=ctx.createGain();
  osc.type=type;
  osc.frequency.setValueAtTime(freq,t0);
  if(slideTo) osc.frequency.exponentialRampToValueAtTime(Math.max(1,slideTo),t0+dur);
  g.gain.setValueAtTime(0.0001,t0);
  g.gain.exponentialRampToValueAtTime(v,t0+attack);
  g.gain.exponentialRampToValueAtTime(0.0001,t0+dur);
  osc.connect(g).connect(ctx.destination);
  osc.start(t0); osc.stop(t0+dur+0.02);
}
// Gürültü (tribün uğultusu, taraftar coşkusu)
function sfxNoise(ctx,{dur=0.6,gain=0.12,delay=0,band=900,q=0.7}){
  const t0=ctx.currentTime+delay;
  const v=Math.max(0.0001,gain*sfxSettings.vol);
  const len=Math.max(1,Math.floor(ctx.sampleRate*dur));
  const buf=ctx.createBuffer(1,len,ctx.sampleRate);
  const data=buf.getChannelData(0);
  for(let i=0;i<len;i++) data[i]=(Math.random()*2-1)*(1-i/len);
  const src=ctx.createBufferSource(); src.buffer=buf;
  const flt=ctx.createBiquadFilter(); flt.type="bandpass"; flt.frequency.value=band; flt.Q.value=q;
  const g=ctx.createGain();
  g.gain.setValueAtTime(0.0001,t0);
  g.gain.exponentialRampToValueAtTime(v,t0+dur*0.25);
  g.gain.exponentialRampToValueAtTime(0.0001,t0+dur);
  src.connect(flt).connect(g).connect(ctx.destination);
  src.start(t0); src.stop(t0+dur);
}

const SFX={
  click:  ctx=>sfxTone(ctx,{freq:520,type:"triangle",dur:0.06,gain:0.10}),
  tab:    ctx=>sfxTone(ctx,{freq:380,type:"sine",dur:0.09,gain:0.09,slideTo:560}),
  whistle:ctx=>{sfxTone(ctx,{freq:2100,type:"square",dur:0.16,gain:0.07,slideTo:2500});
                sfxTone(ctx,{freq:2400,type:"square",dur:0.13,gain:0.05,delay:0.18,slideTo:2000});},
  goal:   ctx=>{[523,659,784,1047].forEach((f,i)=>sfxTone(ctx,{freq:f,type:"sawtooth",dur:0.30,gain:0.13,delay:i*0.075}));
                sfxNoise(ctx,{dur:1.5,gain:0.13,band:700,q:0.5,delay:0.10});},
  cheer:  ctx=>sfxNoise(ctx,{dur:1.1,gain:0.10,band:800,q:0.5}),
  win:    ctx=>[523,659,784,1047,1319].forEach((f,i)=>sfxTone(ctx,{freq:f,type:"triangle",dur:0.35,gain:0.12,delay:i*0.09})),
  lose:   ctx=>[392,349,294,247].forEach((f,i)=>sfxTone(ctx,{freq:f,type:"sine",dur:0.35,gain:0.10,delay:i*0.11})),
  levelup:ctx=>[659,880,1319].forEach((f,i)=>sfxTone(ctx,{freq:f,type:"square",dur:0.22,gain:0.10,delay:i*0.07})),
  coin:   ctx=>{sfxTone(ctx,{freq:988,type:"square",dur:0.07,gain:0.09});
                sfxTone(ctx,{freq:1319,type:"square",dur:0.14,gain:0.09,delay:0.07});},
  error:  ctx=>sfxTone(ctx,{freq:180,type:"sawtooth",dur:0.22,gain:0.11,slideTo:90}),
  card:   ctx=>sfxTone(ctx,{freq:300,type:"square",dur:0.18,gain:0.09,slideTo:220}),
};
function playSfx(name){
  if(!sfxSettings.on||sfxSettings.vol<=0)return;
  const ctx=audioCtx();
  if(!ctx)return;
  if(ctx.state==="suspended"){ ctx.resume().catch(()=>{}); }
  const fn=SFX[name];
  if(!fn)return;
  try{ fn(ctx); }catch(e){}
}

