let _uidSeq=0;
const uid=()=>`${Date.now().toString(36)}-${(++_uidSeq).toString(36)}`;
// Türkçe büyük harf: JS toUpperCase() "i" harfini "I" yapar, "İ" olmalı.
const trU=str=>String(str).replace(/i/g,"\u0130").toUpperCase();
// Kulüp prestiji ve oyuncu kalitesine göre gerçekçi haftalık maaş (bin € cinsinden)
function wageFor(prestige,ovr){
  const base=Math.pow(Math.max(1,prestige),1.6)*1.8;
  const quality=Math.pow(Math.max(0,ovr-60),1.5)*0.25;
  return Math.max(4,Math.round(base+quality));
}
