// Haber akışı GERÇEK oyun durumundan üretilir.
// Eskiden her hafta uydurma transferler yazılıyordu ("takımlar takımlara transfer oluyor");
// artık öncelik gerçek puan durumu, senin sonucun, rakibin ve haftanın fikstürü.
function generateNewsItem({clubs,player,rival,standings,club,week,season,lastResult,leagueScorers,fixtures}){
  const lg=getLg(club.leagueId);
  const table=sortTable(standings||[]);
  const myPos=table.findIndex(t=>t.isMe)+1;
  const leader=table[0];
  const bottom=table[table.length-1];
  const leagueClubs=(clubs||CLUBS).filter(c=>c.leagueId===club.leagueId&&c.name!==club.name);
  const a=pick(leagueClubs)?.name||"Rakip FC";
  const b=pick(leagueClubs.filter(c=>c.name!==a))?.name||"Rakip FC";
  const pn=pick(NPC_PLAYER_NAMES);

  // ── GERÇEK DURUM HABERLERİ (öncelikli) ──
  const real=[];
  if(leader&&!leader.isMe) real.push({cat:"league",
    msg:`📊 ${lg.name}: ${leader.name} ${leader.pts} puanla lider, ${club.name} ${myPos}. sırada.`});
  if(leader&&leader.isMe) real.push({cat:"league",
    msg:`👑 ${club.name} ${leader.pts} puanla ${lg.name}'in lideri!`});
  if(myPos&&myPos<=3) real.push({cat:"league",
    msg:`🔥 ${club.name} zirve yarışında! ${myPos}. sırada, averaj ${table[myPos-1].gd>0?"+":""}${table[myPos-1].gd}.`});
  if(myPos&&myPos>=table.length-2&&table.length>4) real.push({cat:"league",
    msg:`⚠️ ${club.name} küme hattında — ${myPos}. sıra. Taraftar endişeli.`});
  if(bottom&&bottom.p>4) real.push({cat:"league",
    msg:`📉 ${bottom.name} ${bottom.pts} puanla son sırada, teknik direktör koltuğu sallantıda.`});
  if(lastResult){
    const {teamScore,oppScore,won,draw,goals,assists,oppName}=lastResult;
    if(goals>=3) real.push({cat:"award",msg:`🎩 HAT-TRICK! ${player.name} ${oppName} karşısında ${goals} gol attı.`,important:true});
    else if(goals===2) real.push({cat:"award",msg:`⚡ ${player.name} çifte gol attı — ${club.name} ${teamScore}-${oppScore} ${oppName}.`});
    else if(goals===1) real.push({cat:"match",msg:`⚽ ${player.name} ${oppName} maçında ağları sarstı. Skor ${teamScore}-${oppScore}.`});
    if(assists>=2) real.push({cat:"award",msg:`🎯 ${player.name} tek maçta ${assists} asist yaptı!`});
    if(won&&teamScore-oppScore>=3) real.push({cat:"match",msg:`💥 Farklı galibiyet: ${club.name} ${teamScore}-${oppScore} ${oppName}.`});
    if(!won&&!draw&&oppScore-teamScore>=3) real.push({cat:"match",msg:`😬 Ağır mağlubiyet: ${oppName} ${oppScore}-${teamScore} ${club.name}.`});
  }
  // Haftanın gerçek fikstürü
  if(fixtures&&week){
    const wk=fixtures[(week-1)%fixtures.length]||[];
    const m=pick(wk.filter(x=>x.home!==club.name&&x.away!==club.name));
    if(m) real.push({cat:"match",msg:`📅 Bu hafta ${lg.name}'de dikkat çeken eşleşme: ${m.home} – ${m.away}.`});
  }
  // Gol krallığı yarışı
  if(leagueScorers&&leagueScorers.length){
    const board=[...leagueScorers,{name:player.name,goals:player.sg||0,isMe:true}].sort((x,y)=>y.goals-x.goals);
    const top=board[0];
    if(top&&top.goals>0){
      real.push({cat:"award",msg:top.isMe
        ? `👟 ${player.name} ${top.goals} golle krallık yarışının zirvesinde!`
        : `👟 Gol krallığında ${top.name} ${top.goals} golle önde — ${player.name} ${player.sg||0} golde.`});
    }
  }
  // Rakip
  if(rival&&(rival.seasonGoals||0)>0){
    real.push({cat:"rumor",msg:(rival.seasonGoals>(player.sg||0))
      ? `⚔️ ${rival.name} ${rival.seasonGoals} golle ${player.name}'i geçmiş durumda.`
      : `⚔️ ${player.name} ${player.sg||0} golle ${rival.name}'in (${rival.seasonGoals}) önünde.`});
  }
  // Oyuncunun durumu
  if(player.injuryWeeks>0) real.push({cat:"injury",msg:`🚑 ${player.name} sakatlığı sürüyor — ${player.injuryWeeks} hafta yok.`});
  if(player.banWeeks>0) real.push({cat:"drama",msg:`🟥 ${player.name} cezalı: ${player.banReason}. ${player.banWeeks} maç forma giyemeyecek.`});
  if((player.fame||0)>=75) real.push({cat:"award",msg:`🌟 ${player.name} artık ${lg.name}'in en tanınan isimlerinden biri.`});

  // %75 gerçek durumdan, %25 renk katan şablon haber
  if(real.length&&Math.random()<0.75){
    const r=pick(real);
    return{id:uid(),cat:r.cat,catLabel:NEWS_CATEGORIES[r.cat]||NEWS_CATEGORIES.league,
      msg:r.msg,week,season,ts:Date.now(),important:!!r.important};
  }

  // ── ŞABLON HABERLER (transfer dedikodusu hariç: sezon dışı spam yapmasın) ──
  let cats=Object.keys(NEWS_TEMPLATES);
  if(!isTransferWindow(week,(fixtures&&fixtures.length)||34)) cats=cats.filter(c=>c!=="transfer");
  const cat=pick(cats)||"league";
  const tpl=pick(NEWS_TEMPLATES[cat]);
  let msg;
  try{msg=tpl({a,b,fee:rand(5,120),w:rand(1,6),g:rand(1,4),s:`${rand(1,4)}-${rand(0,2)}`,lg:lg.name,pn,n:rival?.name||"Rakip"});}
  catch(e){msg=`📰 ${lg.name}'de bu hafta ilginç gelişmeler yaşandı.`;}
  return{id:uid(),cat,catLabel:NEWS_CATEGORIES[cat],msg,week,season,ts:Date.now(),
    important:["award","drama"].includes(cat)&&Math.random()<0.3};
}

