const rand=(a,b)=>Math.floor(Math.random()*(b-a+1))+a;
const pick=arr=>arr[Math.floor(Math.random()*arr.length)];
const getLg=id=>LEAGUES.find(l=>l.id===id)||LEAGUES[0];
const getClub=name=>CLUBS.find(c=>c.name===name);
const getPhase=ovr=>CAREER_PHASES.slice().reverse().find(p=>ovr>=p.minOvr)||CAREER_PHASES[0];

function posWeight(pos,s){
  const w={ST:{shooting:2,pace:1.5,dribbling:1.2,physical:0.8,passing:0.5,defending:0.1},CAM:{shooting:1.5,pace:1,dribbling:1.8,passing:1.5,physical:0.7,defending:0.2},CM:{passing:1.8,dribbling:1.2,physical:1.2,defending:1,shooting:0.8,pace:0.8},CDM:{defending:2,physical:1.5,passing:1.2,pace:0.8,dribbling:0.7,shooting:0.5},LW:{pace:2,dribbling:1.8,shooting:1.2,passing:0.8,physical:0.6,defending:0.2},RW:{pace:2,dribbling:1.8,shooting:1.2,passing:0.8,physical:0.6,defending:0.2},CB:{defending:2.5,physical:1.8,pace:0.8,passing:0.8,dribbling:0.3,shooting:0.2},LB:{defending:1.5,pace:1.5,passing:1,physical:1,dribbling:0.8,shooting:0.3},RB:{defending:1.5,pace:1.5,passing:1,physical:1,dribbling:0.8,shooting:0.3},GK:{defending:3,physical:1.5,pace:0.5,passing:0.5,dribbling:0.2,shooting:0.1}};
  const wt=w[pos]||w.CM;let tot=0,mx=0;
  for(const[k,v]of Object.entries(wt)){tot+=s[k]*v;mx+=99*v;}
  return Math.round((tot/mx)*99);
}

