function ageGrow(age,diff){
  const b=age<=19?1:age<=23?.65:age<=27?.3:age<=31?.12:age<=34?.04:0;
  return b*(diff?.growMod||1);
}

// "Hemen Oyna": rastgele 17-19 yaş oyuncu, Süper Lig'de orta ölçekli (prestij 3-5) kulüp.
const QUICK_FIRST=["Arda","Kerem","Emir","Yusuf","Mert","Kaan","Efe","Barış","Can","Deniz","Ozan","Berk","Eren","Umut","Batuhan"];
const QUICK_LAST=["Yılmaz","Kaya","Demir","Şahin","Çelik","Aydın","Öztürk","Arslan","Doğan","Koç","Kurt","Özdemir","Aksoy","Erdem","Polat"];
function mkQuickStart(){
  const pos=pick(["ST","ST","CAM","CM","LW","RW","CB","CDM","LB","RB"]);
  const age=rand(17,19);
  const pool=CLUBS.filter(c=>c.leagueId==="superlig"&&c.prestige>=3&&c.prestige<=5);
  const club=pool.length?pick(pool):pick(CLUBS.filter(c=>c.leagueId==="superlig"));
  const player=mkPlayer({name:`${pick(QUICK_FIRST)} ${pick(QUICK_LAST)}`,age,nat:NATS[0],pos,foot:pick(["Sağ","Sağ","Sol"])});
  player.avatar={skin:rand(0,AV_SKIN.length-1),hair:rand(0,AV_HAIR.length-1),
    hairStyle:rand(0,AV_HAIR_STYLE.length-1),expr:1,beard:0,tattoo:0};
  return {player,club};
}

function getInterestedClubs(age,lgId,academy){
  // Altyapıya girmek profesyonel kadroya girmekten kolaydır:
  // büyük kulüplerin akademileri de genç oyuncuya kapı açar.
  const maxP=academy?8:age<=17?3:age<=19?4:age<=21?5:6;
  const minP=academy?3:1;
  const pool=CLUBS.filter(c=>c.leagueId===lgId&&c.prestige<=maxP&&c.prestige>=minP);
  return (pool.length?pool:CLUBS.filter(c=>c.leagueId===lgId)).sort(()=>Math.random()-.5).slice(0,3);
}

function mkPlayer(o={}){
  const age=o.age||18;
  const base={name:o.name||"Oyuncu",age,nat:o.nat||pick(NATS),pos:o.pos||"ST",foot:o.foot||"Sağ",
    pace:rand(46,66),shooting:rand(42,64),passing:rand(40,62),dribbling:rand(44,66),defending:rand(24,54),physical:rand(42,64),
    traits:[pick(TRAITS_POOL),pick(TRAITS_POOL)].filter((v,i,a)=>a.indexOf(v)===i),
    goals:0,assists:0,matches:0,sg:0,sa:0,sm:0,morale:75,fitness:100,xp:0,level:1,
    fame:5,bank:rand(500,2000),salary:rand(3,8),contractYears:3,caps:0,capGoals:0,injuryWeeks:0,injuryType:"",
    titles:0,clTitles:0,wcWon:false,achievements:[],items:[],formHistory:[],seasonHistory:[],careerLog:[],
    // Yetenek puanı ve rozetler
    perks:[],spentPoints:0,
    // Kart ve ceza
    yellowCards:0,redCards:0,sYellow:0,sRed:0,banWeeks:0,banReason:"",
    // Kaleci istatistikleri
    saves:0,conceded:0,cleanSheets:0,sSaves:0,sConceded:0,sCleanSheets:0,motmCount:0,
    _mg:0,_mr:0,_abroad:false,_bigClub:false,_sponsor:false,_streak:0,_penScored:false,_rivalBeaten:false,
    _hasFamily:false,_loanDone:false,retired:false,weeklyIncome:0,pressCount:0,loanClub:null,
    avatar:o.avatar||null,faceId:o.faceId??null,
    managerTrust:70,fanLove:60,
    // ── FAZ 3 ──
    mental:100,          // zihinsel enerji (0-100) — fitness bacakları, bu kafayı ölçer
    // Gizli özellik: her oyuncunun sakatlanma yatkınlığı farklı (0-20).
    // Biri cam gibi, biri demir — kariyerler böylece birbirine benzemiyor.
    injuryProneness:rand(2,18),
    mentalResist:0,      // meditasyon kampıyla kalıcı artan zihinsel dayanıklılık
    mediaSkill:30,       // basın toplantısı becerisi
    setPiece:30,         // duran top ustalığı
    shirtNo:o.shirtNo||null,
    captaincy:"none",
    seasonsAtClub:0,
    trophyCabinet:[],    // [{id,season,club,detail}]
    academy:!!o.academy, // altyapıdan başlandıysa true
    academyPts:0,
    u19Matches:0,u19Goals:0,u19Assists:0,
    bonusEarned:0,       // sözleşme primlerinden toplam kazanç
    injuryHistory:[],    // [{name,weeks,season,surgery}]
    teamForm:70,        // Takım Formu (40-99)
    teamMorale:70,      // Takım Morali (40-99)
    // Kariyer Hedefleri
    seasonGoalTarget: 15,     // Bu sezon gol hedefi
    seasonAssistTarget: 8,    // Bu sezon asist hedefi
    careerGoalTarget: 100,    // Kariyer gol hedefi
    careerAssistTarget: 60,   // Kariyer asist hedefi
  };
  base.overall=posWeight(base.pos,base);
  // Gizli yetenek: her oyuncunun farklı bir tavanı var.
  // Genç başlarsan tavanın yüksek olur — eskiden tavan başlangıç OVR'ına kilitliydi
  // ve 18 yaşında başlayan bir oyuncu asla 75'i geçemiyordu.
  const talent=o.talent??(Math.random()<0.07?rand(38,48)        // wonderkid (%7)
                        :Math.random()<0.28?rand(30,38)         // üst düzey yetenek
                        :Math.random()<0.65?rand(22,30)         // iyi yetenek
                        :rand(14,22));                          // sıradan
  const ageCut=age<=17?0:age<=19?2:age<=21?5:age<=23?9:age<=26?15:age<=29?21:26;
  base.talent=talent;
  base.potential=Math.max(base.overall+3,Math.min(99,base.overall+talent-ageCut));
  base.value=parseFloat((base.overall*.05).toFixed(1));
  // Altyapıdan başlayan oyuncu daha ham ama tavanı daha yüksek olur.
  if(o.academy){
    ["pace","shooting","passing","dribbling","defending","physical"].forEach(k=>{
      base[k]=Math.max(20,base[k]-rand(7,12));
    });
    base.overall=posWeight(base.pos,base);
    base.potential=Math.max(base.overall+14,Math.min(99,base.overall+talent+rand(14,20)));
    base.bank=rand(60,220);
    base.salary=1;
    base.fame=1;
    base.managerTrust=45;
    base.value=parseFloat((base.overall*.03).toFixed(1));
  }
  base.trainPlan=defaultPlan(base.pos);
  return base;
}

// ══════════ FİKSTÜR MOTORU ══════════
// Round-robin algoritması: n takım, (n-1) hafta, her hafta n/2 maç
// Oyuncu her hafta listedeki sıradaki rakiple oynuyor
function mkFixtures(myClub){
  const teams=CLUBS.filter(c=>c.leagueId===myClub.leagueId).map(t=>t.name);
  const n=teams.length;
  // Her sezon farklı bir sıra — fikstür ezberlenmesin
  const shuffled=[...teams].sort(()=>Math.random()-0.5);
  const list=n%2===0?shuffled:[...shuffled,"BYE"];
  const total=list.length;
  const rounds=total-1;

  // 1) Dairesel round-robin ile EŞLEŞMELERİ üret (ev/deplasman henüz belirsiz)
  const pairRounds=[];
  for(let r=0;r<rounds;r++){
    const wk=[];
    for(let m=0;m<total/2;m++){
      const x=list[m], y=list[total-1-m];
      if(x!=="BYE"&&y!=="BYE") wk.push([x,y]);
    }
    pairRounds.push(wk);
    list.splice(1,0,list.pop());
  }

  // 2) EV/DEPLASMAN dağıtımı — açgözlü dengeleyici.
  //    Elle parite hesabı (r%2 gibi) bu tabloda işe yaramıyor: sabit takım
  //    ilk devrenin tamamını evinde oynuyordu (17 maç üst üste) ve ev
  //    avantajı (±2.5) lig tablosunu çarpıtıyordu. Burada her maçta evi,
  //    o ana kadar daha az ev maçı oynamış ve üst üste ev serisi kısa olan
  //    takıma veriyoruz.
  const homeCount={}, lastVenue={}, streak={};
  teams.forEach(t=>{homeCount[t]=0;lastVenue[t]="";streak[t]=0;});
  const cost=(t,venue)=>{
    let c=venue==="E"?homeCount[t]:-homeCount[t];         // dengeyi koru
    if(lastVenue[t]===venue) c+=streak[t]>=2?6:2;          // seriyi uzatma
    return c;
  };
  const firstHalf=pairRounds.map(wk=>wk.map(([x,y])=>{
    // x ev / y ev seçeneklerinden toplam maliyeti düşük olanı seç
    const a=cost(x,"E")+cost(y,"D");
    const b=cost(y,"E")+cost(x,"D");
    const [h,aw]=(a<=b)?[x,y]:[y,x];
    homeCount[h]++;
    [[h,"E"],[aw,"D"]].forEach(([t,v])=>{ streak[t]=lastVenue[t]===v?streak[t]+1:1; lastVenue[t]=v; });
    return {home:h,away:aw};
  }));
  // İkinci devre birebir ters — sezon sonunda ev/deplasman sayısı eşitlenir
  const secondHalf=firstHalf.map(wk=>wk.map(m=>({home:m.away,away:m.home})));
  return [...firstHalf,...secondHalf];
}

function simNPCMatch(homeTeam,awayTeam){
  const hc=CLUBS.find(c=>c.name===homeTeam);
  const ac=CLUBS.find(c=>c.name===awayTeam);
  const edge=(clubStrength(hc)+2.5)-clubStrength(ac)+gauss(13);
  const homeWon=edge>5.5;
  const draw=!homeWon&&edge>-5.5;
  let hg,ag;
  if(homeWon){
    hg=rand(1,2)+(edge>18?rand(0,2):edge>10?rand(0,1):0);
    ag=rand(0,Math.max(0,hg-1));
  }else if(draw){
    hg=Math.random()<0.30?0:Math.random()<0.75?1:2;
    ag=hg;
  }else{
    ag=rand(1,2)+(edge<-18?rand(0,2):edge<-10?rand(0,1):0);
    hg=rand(0,Math.max(0,ag-1));
  }
  return{homeGoals:hg,awayGoals:ag,homeWon,draw};
}

// Standings sıfır başlat
function mkStandings(myClub){
  return CLUBS.filter(c=>c.leagueId===myClub.leagueId)
    .map(t=>({name:t.name,p:0,w:0,d:0,l:0,gf:0,ga:0,gd:0,pts:0,isMe:t.name===myClub.name}));
}

// Fikstürü oyuncunun takımı için haftalık rakip olarak döndür
function getWeekOpponent(fixtures,myClub,week){
  const wk=fixtures[(week-1)%fixtures.length]||[];
  const match=wk.find(m=>m.home===myClub.name||m.away===myClub.name);
  if(!match)return{name:"Rakip",isHome:true};
  return{name:match.home===myClub.name?match.away:match.home,isHome:match.home===myClub.name};
}

