function pickLifeEvent(){
  const tot=LIFE_EVENTS.reduce((a,e)=>a+e.w,0);
  let r=Math.random()*tot;
  for(const e of LIFE_EVENTS){ r-=e.w; if(r<=0) return e; }
  return LIFE_EVENTS[0];
}

