const TRAIN_DAYS=["Pazartesi","Çarşamba","Cuma"];
function defaultPlan(pos){
  if(pos==="GK") return {days:["gk","recovery","gk"],intensity:"normal"};
  const g=POS_GROWTH[pos]||POS_GROWTH.CM;
  const map={pace:"sprint",shooting:"finish",passing:"passing",dribbling:"tech",defending:"defend",physical:"gym"};
  const top=[...g].sort((a,b)=>b[1]-a[1]).slice(0,2).map(x=>map[x[0]]||"passing");
  return {days:[top[0],"recovery",top[1]||top[0]],intensity:"normal"};
}
// Planın haftalık toplam bedelini önceden gösterir — sürpriz olmasın.
function planCost(plan,player){
  const inT=intensity(plan.intensity);
  let fit=0,mental=0,inj=0,xp=0;
  (plan.days||[]).forEach(id=>{
    const d=drill(id);
    fit+=d.fit>0?d.fit*(2-inT.fit):d.fit*inT.fit;
    mental+=d.mental>0?d.mental*(2-inT.mental):d.mental*inT.mental;
    inj+=d.inj*inT.inj;
    xp+=d.xp*inT.gain;
  });
  if(hasPerk(player,"engine")) fit*=fit<0?0.7:1;
  if(hasPerk(player,"ironman")) inj*=0.6;
  return {fit:Math.round(fit),mental:Math.round(mental),inj:Math.min(0.55,inj),xp:Math.round(xp)};
}
// Haftalık planı uygular. Saf fonksiyon: girdi oyuncu, çıktı {player,lines,injury}
function runTrainPlan(player,plan,diffGrow=1){
  const inT=intensity(plan.intensity);
  const p={...player};
  const lines=[];
  const room=Math.max(0,(p.potential||p.overall)-p.overall);
  const roomMul=room<=0?0.2:room>=15?1:room>=8?0.78:0.48;
  const ageMul=p.age<=21?1.25:p.age<=25?1:p.age<=29?0.72:0.4;
  const gains={};
  let fitD=0,menD=0,injRisk=0,xpGain=0;
  (plan.days||[]).forEach((id,i)=>{
    const d=drill(id);
    // Kişisel antrenör satın alındıysa o alanda kazanç artar
    const coached=d.attrs.some(([a])=>p.items?.includes(`coach_${a}`));
    const sci=p.items?.includes("sport_science");
    d.attrs.forEach(([attr,w])=>{
      const base=w*inT.gain*roomMul*ageMul*diffGrow*(coached?1.7:1)*(sci?1.25:1);
      gains[attr]=(gains[attr]||0)+base;
    });
    fitD+=d.fit>0?d.fit*(2-inT.fit):d.fit*inT.fit;
    menD+=d.mental>0?d.mental*(2-inT.mental):d.mental*inT.mental;
    injRisk+=d.inj*inT.inj;
    xpGain+=d.xp*inT.gain;
    if(d.id==="tactic") p.managerTrust=Math.min(100,(p.managerTrust??70)+2);
    if(d.id==="media")  {p.fame=Math.min(100,(p.fame||5)+1); p.mediaSkill=Math.min(100,(p.mediaSkill||30)+4);}
    if(d.id==="recovery")p._recovered=(p._recovered||0)+1;
    if(d.id==="setpiece")p.setPiece=Math.min(100,(p.setPiece||30)+3);
    lines.push(`${TRAIN_DAYS[i]||"Ek"}: ${d.icon} ${d.name}`);
  });
  if(hasPerk(p,"engine")) fitD=fitD<0?fitD*0.7:fitD;
  if(hasPerk(p,"ironman")) injRisk*=0.6;
  { const pron=p.injuryProneness??10;
    injRisk*=Math.max(0.45,Math.min(1.75,0.45+Math.sqrt(pron/10)*0.72)); }
  if(p._recovered) injRisk*=Math.max(0.3,1-0.28*p._recovered);
  // Zihinsel enerji düşükken kazanç erir — tükenmiş oyuncu gelişemez
  const men=p.mental??100;
  const mentalMul=men>=70?1:men>=45?0.8:men>=25?0.55:0.3;
  const applied=[];
  Object.entries(gains).forEach(([attr,raw])=>{
    const g=raw*mentalMul;
    const whole=Math.floor(g)+(Math.random()<(g%1)?1:0);
    if(whole>0){ p[attr]=Math.min(99,(p[attr]||40)+whole); applied.push(`${attr} +${whole}`); }
  });
  // Tam sayı tut: ekranda yuvarlanan ama kayıtta ondalık duran değer kafa karıştırıyordu
  p.fitness=Math.round(Math.max(5,Math.min(100,(p.fitness??100)+fitD)));
  p.mental=Math.round(Math.max(0,Math.min(100,men+menD)));
  p.xp=(p.xp||0)+Math.round(xpGain*mentalMul);
  delete p._recovered;
  // Fitness ne kadar düşükse sakatlanma o kadar olası
  const fatigue=p.fitness<35?1.9:p.fitness<55?1.35:1;
  const mentalRisk=p.mental<25?1.4:p.mental<45?1.15:1;
  let injury=null;
  if(Math.random()<injRisk*fatigue*mentalRisk){
    // INJURY_TYPES.weeks bir [min,max] aralığıdır — tek sayı gibi kullanılırsa NaN olur
    const t=pick(INJURY_TYPES);
    const w=Math.max(1,Math.round(rand(t.weeks[0],t.weeks[1])*(plan.intensity==="hard"?1.3:1)));
    p.injuryWeeks=(p.injuryWeeks||0)+w; p.injuryType=t.name;
    injury={name:t.name,weeks:w};
  }
  p.overall=Math.min(p.potential||99,posWeight(p.pos,p));
  p.value=parseFloat((p.overall*.09*(1+(p.sg||0)*.04)).toFixed(1));
  return {player:p,lines,applied,injury,fitD:Math.round(fitD),menD:Math.round(menD)};
}

