function takenNumbers(teammates){ return new Set((teammates||[]).map(t=>t.shirtNo).filter(Boolean)); }
function assignTeammateNumbers(teammates){
  const used=new Set(); let n=2;
  return (teammates||[]).map(t=>{
    if(t.shirtNo) {used.add(t.shirtNo); return t;}
    let no=t.pos==="GK"?1:n;
    while(used.has(no)||no>40){ no=(no%40)+1; }
    used.add(no); n=no+1;
    return {...t,shirtNo:no};
  });
}
