// Kaptanlığı hoca verir: güven + yaş + liderlik + takımdaki kıdem
function captaincyScore(player,teammates,seasonsAtClub){
  const trust=player.managerTrust??70;
  const lead=(player.traits||[]).includes("Kaptanlık")?14:(player.traits||[]).includes("Lider")?9:0;
  const perk=hasPerk(player,"leader")?8:0;
  const ageBonus=player.age>=28?10:player.age>=25?6:player.age>=22?2:-6;
  const seniority=Math.min(12,(seasonsAtClub||0)*4);
  const quality=Math.max(-10,Math.min(14,(player.overall-72)*0.9));
  return Math.round(trust*0.45+lead+perk+ageBonus+seniority+quality);
}
// Puan → pazuband. Eşikler ölçüldü: genç yıldız vice olur, tecrübeli lider kaptan.
function captaincyFor(score){
  return score>=78?"cap":score>=62?"vice":"none";
}

