// Maaş tek başına yetmiyordu; artık primler gerçekten ödeniyor.
function mkClauses(prestige,ovr,salary,age){
  const big=prestige>=8,mid=prestige>=5;
  return {
    signBonus:  Math.round(salary*WAGE_UNIT*(big?14:mid?9:5)/1000)*1000,   // imza bonusu (€)
    goalBonus:  Math.round(salary*WAGE_UNIT*(big?0.35:0.22)/100)*100,      // gol başına
    assistBonus:Math.round(salary*WAGE_UNIT*(big?0.18:0.11)/100)*100,
    appearance: Math.round(salary*WAGE_UNIT*(big?0.30:0.20)/100)*100,      // maç başı
    motmBonus:  Math.round(salary*WAGE_UNIT*(big?0.55:0.35)/100)*100,
    // M€ — ölçek: 62 OVR küçük kulüp ≈ €13M, 90 OVR dev kulüp ≈ €150M
    release:    Math.round(Math.max(6,Math.pow(Math.max(1,ovr-45),2.1)*(big?0.050:mid?0.040:0.033)*(age<24?1.35:1))),
    loyalty:    Math.round(salary*WAGE_UNIT*6/1000)*1000,                  // sözleşme sonuna kadar kalırsan
    titleBonus: Math.round(salary*WAGE_UNIT*(big?18:11)/1000)*1000,
  };
}
