// Kupalar sezon geçmişinden derlenir; kayıtla birlikte gelir
function buildTrophyCase(cabinet){
  const out={};
  (cabinet||[]).forEach(t=>{
    const k=t.id;
    if(!out[k]) out[k]={...trophyDef(k),count:0,entries:[]};
    out[k].count++; out[k].entries.push(t);
  });
  return Object.values(out).sort((a,b)=>b.count-a.count);
}

