function pickPressTopics(player,rival,n=2){
  const form=(player.formHistory||[]).slice(0,4);
  const avg=form.length?form.reduce((a,b)=>a+b,0)/form.length:6.5;
  const mood=avg>=7.2?"good":avg<=6.0?"bad":"any";
  const pool=PRESS_TOPICS.filter(t=>t.when==="any"||t.when===mood);
  const out=[];const used=new Set();
  while(out.length<n&&used.size<pool.length){
    const t=pick(pool); if(used.has(t.id))continue; used.add(t.id);
    out.push({...t,q:t.q.replace("{rival}",rival?.name||"Rakibin")});
  }
  return out;
}

// ── ALTYAPI / U19 ─────────────────────────────────────────────────
// "Altyapıdan başla" seçeneği: 16 yaşında, düşük OVR, yüksek tavan.
// A takıma çıkmak için akademi puanı toplaman gerekir.
const ACADEMY_TARGET=100;         // bu puana ulaşınca A takım kapısı açılır
const U19_OPPONENTS=["U19 Akademi","Gençlik Spor U19","Bölge Karması","Yıldızlar U19","Futbol Okulu U19","Altyapı Ligi Lideri"];
function simU19Match(player){
  const base=player.overall+(player.fitness-70)*0.12+((player.mental??100)-60)*0.05;
  const opp=rand(44,60);
  const edge=base-opp+gauss(10);
  const won=edge>3, draw=!won&&edge>-4;
  const att=["ST","CAM","LW","RW","CM"].includes(player.pos);
  // Önce skor, sonra oyuncunun payı: gol + asist hiçbir zaman takım golünü aşamaz
  const ts=won?rand(2,5):draw?rand(1,3):rand(0,2);
  const os=won?rand(0,ts-1):draw?ts:rand(ts+1,ts+3);
  let goals=att?Math.max(0,Math.round((edge/14)+gauss(0.9))):Math.random()<0.14?1:0;
  goals=Math.min(goals,ts);
  let assists=Math.random()<(att?0.34:0.18)?rand(1,2):0;
  assists=Math.min(assists,ts-goals);
  const rating=Math.max(4.5,Math.min(10,6.2+goals*1.0+assists*0.6+(won?0.5:draw?0:-0.4)+gauss(0.45)));
  const scoutPts=Math.round(goals*11+assists*7+(rating-6)*9+(won?5:draw?2:0));
  return {won,draw,goals,assists,rating:Math.round(rating*10)/10,teamScore:ts,oppScore:os,
    oppName:pick(U19_OPPONENTS),scoutPts:Math.max(1,scoutPts)};
}
const academyRank=pts=>pts>=ACADEMY_TARGET?"A Takım Hazır":pts>=70?"İlk 11 Adayı":pts>=40?"Dikkat Çekiyor":pts>=15?"Takipte":"Yeni Başladı";

// ══════════ HEDEFLER (FIFA tarzı) ══════════
// Yönetim sezon başında kulüp prestijine göre hedef koyar; tutturmanın
// ve tutturamamanın gerçek sonucu vardır. Eskiden seasonGoalTarget
// herkes için sabit 15'ti ve hiçbir şeye yol açmıyordu.
function mkSeasonObjectives(club,player,leagueSize,seasonWeeks){
  const pr=club.prestige||5;
  const obj=[];
  // 1) Lig sırası hedefi
  const target=pr>=9?1:pr>=8?3:pr>=7?5:pr>=5?Math.round(leagueSize*0.45):Math.max(1,leagueSize-4);
  obj.push({id:"league",icon:"📊",
    label:pr>=5?`Ligi ilk ${target} içinde bitir`:`Küme düşme (son ${Math.min(3,leagueSize-target)}) dışında kal`,
    type:"league_pos",target,reward:{bank:pr*9000,trust:12,fame:6}});
  // 2) Mevkiye göre katkı hedefi
  const out=POS_OUTPUT[player.pos]||POS_OUTPUT.CM;
  const gTarget=Math.max(2,Math.round(out.goal*seasonWeeks*0.85*(0.7+pr/20)));
  const aTarget=Math.max(2,Math.round(out.assist*seasonWeeks*0.75*(0.7+pr/20)));
  if(player.pos==="GK"){
    obj.push({id:"clean",icon:"🛡️",label:`${Math.round(seasonWeeks*0.3)} maçta gol yeme`,
      type:"clean_sheets",target:Math.round(seasonWeeks*0.3),reward:{bank:pr*7000,trust:10,fame:4}});
  }else{
    obj.push({id:"goals",icon:"⚽",label:`${gTarget} gol at`,type:"goals",target:gTarget,
      reward:{bank:pr*7000,trust:10,fame:6}});
    obj.push({id:"assists",icon:"🎯",label:`${aTarget} asist yap`,type:"assists",target:aTarget,
      reward:{bank:pr*4000,trust:7,fame:4}});
  }
  // 3) Süreklilik
  const apps=Math.round(seasonWeeks*0.6);
  obj.push({id:"apps",icon:"🎮",label:`${apps} maça çık`,type:"apps",target:apps,
    reward:{bank:pr*4000,trust:8,fame:3}});
  return obj.map(o=>({...o,done:false}));
}
function objectiveProgress(o,player,leaguePos){
  switch(o.type){
    case "league_pos":   return {cur:leaguePos||99,ok:(leaguePos||99)<=o.target,display:`${leaguePos||"–"}. sıra`};
    case "goals":        return {cur:player.sg||0,ok:(player.sg||0)>=o.target,display:`${player.sg||0}/${o.target}`};
    case "assists":      return {cur:player.sa||0,ok:(player.sa||0)>=o.target,display:`${player.sa||0}/${o.target}`};
    case "apps":         return {cur:player.sm||0,ok:(player.sm||0)>=o.target,display:`${player.sm||0}/${o.target}`};
    case "clean_sheets": return {cur:player.sCleanSheets||0,ok:(player.sCleanSheets||0)>=o.target,display:`${player.sCleanSheets||0}/${o.target}`};
    default: return {cur:0,ok:false,display:"–"};
  }
}

