const LEGACY_TIERS=[
  {min:0,   title:"Sıradan Kariyer",   icon:"⚽", c:"#6b7280", desc:"Formayı giydin, sahaya çıktın. Herkes bunu başaramaz."},
  {min:120, title:"Saygın Profesyonel",icon:"👟", c:"#4ade80", desc:"Uzun ve düzgün bir kariyer. Takım arkadaşların seni hatırlayacak."},
  {min:260, title:"Kulüp Efsanesi",    icon:"⭐", c:"#f97316", desc:"Taraftar tribünde adını haykırdı. Kulüp tarihine geçtin."},
  {min:430, title:"Ülke Yıldızı",      icon:"🌟", c:"#c084fc", desc:"Bir neslin oyuncusu oldun. Çocuklar formanı giydi."},
  {min:640, title:"Dünya Starı",       icon:"🔥", c:"#38bdf8", desc:"Adın Avrupa'nın her stadında biliniyor."},
  {min:900, title:"Ölümsüz Efsane",    icon:"👑", c:"#facc15", desc:"Futbol tarihinin en büyüklerinden biri olarak anılacaksın."},
];
function computeLegacy(p,seasonHistory,careerRecords){
  const champs=(seasonHistory||[]).filter(h=>h.champ).length;
  const boots =(seasonHistory||[]).filter(h=>h.goldenBoot).length;
  const score=Math.round(
    (p.goals||0)*2.2 + (p.assists||0)*1.4 + (p.matches||0)*0.35 +
    (p.titles||0)*45 + (p.clTitles||0)*80 + (p.wcWon?150:0) +
    (p.caps||0)*1.2 + (p.capGoals||0)*2.5 +
    champs*20 + boots*35 +
    Math.max(0,(p.overall||60)-70)*6 +
    Object.keys(careerRecords||{}).length*25 +
    (p.achievements?.length||0)*6
  );
  const tier=[...LEGACY_TIERS].reverse().find(t=>score>=t.min)||LEGACY_TIERS[0];
  return {score,tier,champs,boots};
}

// Transfer dönemleri: sezon başı (ilk 3 hafta) ve devre arası (sezonun ortasında 3 hafta)
function isTransferWindow(week,seasonWeeks){
  const mid=Math.round(seasonWeeks/2);
  return week<=3||(week>=mid&&week<=mid+2);
}
function transferWindowLabel(week,seasonWeeks){
  const mid=Math.round(seasonWeeks/2);
  if(week<=3)return "Yaz transfer dönemi açık";
  if(week>=mid&&week<=mid+2)return "Devre arası transfer dönemi açık";
  const next=week<mid?mid:seasonWeeks+1;
  return `Transfer dönemi kapalı — ${Math.max(0,next-week)} hafta sonra açılıyor`;
}

