const TEAMMATE_FIRST_NAMES=["Ahmet","Carlos","Marco","Luca","João","Kai","Ivan","Diego","James","Tom","Yuki","Omar","Mateus","Pierre","Aleksei","Emre","Sofiane","Nabil","Tomas","Lucas","Florian","Gabriel","Felipe","Ricardo","Sami","Patrick","Kevin","Robin","Eren","Mert","Burak","Oğuzhan","Cengiz","Hasan","Serdar","Ferdi","Dorukhan"];
const TEAMMATE_LAST_NAMES=["Silva","Rossi","Müller","García","Anderson","Tanaka","Petrov","López","Wilson","Santos","Ferrari","Diallo","Costa","Dubois","Ivanov","Yılmaz","Benali","Ziyech","Novak","Hernandez","Thiago","Ribeiro","Neves","Alves","Keïta","Berg","De Bruyne","Olsen","Demir","Şahin","Turan","Şener","Ünder","Çalhanoğlu","Karaman","Kadioglu","Doruk"];
const TEAMMATE_TRAITS_POOL=["Lider","Kaptan Ruhu","Soyunma Odası Şakacısı","Sessiz Usta","Genç Yetenek","Deneyimli","Motivasyon Uzmanı","Agresif","Teknik Direktör Gözü Gibi","Formda","Moral Yükseltici","Takım Oyuncusu","Asist Makinesi","Defans Duvarı","Gol Avcısı","İkinci Yarı Yıldızı"];

const LINEUP_SLOTS=[
  {pos:"GK",x:50,y:88},{pos:"RB",x:18,y:70},{pos:"CB",x:37,y:70},{pos:"CB",x:63,y:70},{pos:"LB",x:82,y:70},
  {pos:"CDM",x:50,y:54},{pos:"CM",x:28,y:40},{pos:"CM",x:72,y:40},
  {pos:"LW",x:14,y:18},{pos:"ST",x:50,y:10},{pos:"RW",x:86,y:18},
];

// Oyuncunun mevkisi diziliste yoksa (ör. CAM) en yakın slot ona dönüştürülür,
// yoksa oyuncu kendi kadrosunda hiç görünmüyordu.
const SLOT_SWAP={CAM:"CM",ST:"ST",LW:"LW",RW:"RW",CM:"CM",CDM:"CDM",CB:"CB",LB:"LB",RB:"RB",GK:"GK"};
function buildSlots(playerPos){
  const slots=LINEUP_SLOTS.map(s=>({...s}));
  if(slots.some(s=>s.pos===playerPos))return slots;
  const target=SLOT_SWAP[playerPos]||"CM";
  const idx=slots.findIndex(s=>s.pos===target);
  if(idx>=0) slots[idx]={...slots[idx],pos:playerPos};
  return slots;
}

function mkTeammates(playerPos,clubPrestige){
  const used=new Set();
  const mkName=()=>{
    let n,tries=0;
    do{n=`${pick(TEAMMATE_FIRST_NAMES)} ${pick(TEAMMATE_LAST_NAMES)}`;tries++;}while(used.has(n)&&tries<20);
    used.add(n);return n;
  };
  const baseOvr=Math.max(50,40+clubPrestige*5);
  const list=buildSlots(playerPos).map((slot,i)=>{
    const isMyPos=slot.pos===playerPos&&!used.has("__mypos__")&&(used.add("__mypos__"),true);
    const age=rand(18,35);
    const ovr=isMyPos?Math.max(50,baseOvr+rand(-8,3)):baseOvr+rand(-6,8);
    const chemistry=rand(60,100);
    const mood=pick(["😊","😐","🔥","😤","😴"]);
    const trait=pick(TEAMMATE_TRAITS_POOL);
    const goals=rand(0,12);
    const assists=rand(0,10);
    return{
      id:i,name:mkName(),pos:slot.pos,nat:pick(NATS).split(" ")[0],
      age,ovr:Math.min(99,ovr),chemistry,mood,trait,goals,assists,
      isMyPos,x:slot.x,y:slot.y,
      relationship:pick(["Arkadaş","Nötr","Rakip","Mentor","Çırak"]),
    };
  });
  return assignTeammateNumbers(list);
}

