// ══════════════════════════════════════════════════════════════════
//  KULÜP ARMALARI
//  Eskiden her kulüp aynı forma silüetiydi, aralarındaki tek fark bir
//  hex koduydu — rakibi tanımak imkânsızdı. Artık her kulüp adından
//  DETERMİNİSTİK olarak üretilen kendi arması var: kalkan biçimi,
//  desen, yıldız sayısı (prestij) ve baş harfler.
// ══════════════════════════════════════════════════════════════════
const CREST_SHAPES=[
  "M50 3 95 17v40c0 27-20 42-45 52C25 99 5 84 5 57V17z",            // klasik kalkan
  "M7 7h86v50c0 25-21 37-43 52C28 94 7 82 7 57z",                    // kare omuz
  "M50 2 95 25v37L50 109 5 62V25z",                                  // altıgen
  "M50 3a47 47 0 1 0 0 94 47 47 0 0 0 0-94z",                        // daire
  "M10 8h80l-7 52c-2 19-16 32-33 49-17-17-31-30-33-49z",             // konik
  "M50 2c26 0 45 10 45 10v34c0 30-23 47-45 63C28 93 5 76 5 46V12S24 2 50 2z", // yumuşak
];
const crestHash=(s)=>{let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return Math.abs(h);};
const crestInitials=(name)=>{
  const words=String(name).replace(/[^\p{L}\p{N}\s]/gu," ").trim().split(/\s+/).filter(Boolean);
  if(words.length>=2) return words.slice(0,3).map(w=>w[0]).join("").toUpperCase();
  const w=words[0]||"?";
  return (w.length>=3?w.slice(0,3):w).toUpperCase();
};
function ClubCrest({club,color,name,size=40,prestige,style={}}){
  const nm=name||club?.name||"?";
  const col=color||club?.color||"#4a5a6a";
  const ks=club?getKitStyle(club):null;
  const col2=ks?.secondColor||"#ffffff";
  const pres=prestige??club?.prestige??0;
  const h=crestHash(nm);
  const shape=CREST_SHAPES[h%CREST_SHAPES.length];
  const pattern=Math.floor(h/7)%5;           // 0 düz 1 dikey 2 yatay bant 3 çapraz 4 chevron
  const stars=pres>=9?3:pres>=7?2:pres>=5?1:0;
  const ini=crestInitials(nm);
  const small=size<34;                       // 34px altında detay yerine okunurluk
  const uid=`cr${h%100000}`;
  return(<svg viewBox="0 0 100 112" width={size} height={size*1.12}
    style={{display:"block",flexShrink:0,...style}} aria-hidden>
    <defs>
      <clipPath id={`${uid}c`}><path d={shape}/></clipPath>
      <linearGradient id={`${uid}g`} x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stopColor="#ffffff" stopOpacity=".28"/>
        <stop offset=".45" stopColor="#ffffff" stopOpacity=".04"/>
        <stop offset="1" stopColor="#000000" stopOpacity=".3"/>
      </linearGradient>
    </defs>
    {/* gövde */}
    <path d={shape} fill={col}/>
    {/* desen */}
    <g clipPath={`url(#${uid}c)`}>
      {pattern===1&&<><rect x="34" y="0" width="12" height="112" fill={col2} opacity=".85"/>
                      <rect x="54" y="0" width="12" height="112" fill={col2} opacity=".85"/></>}
      {pattern===2&&<rect x="0" y="40" width="100" height="20" fill={col2} opacity=".85"/>}
      {pattern===3&&<path d="M-20 92 92-20l26 26L6 118z" fill={col2} opacity=".8"/>}
      {pattern===4&&<path d="M0 26 50 56l50-30v20L50 76 0 46z" fill={col2} opacity=".8"/>}
      <path d={shape} fill={`url(#${uid}g)`}/>
    </g>
    {/* kenar */}
    <path d={shape} fill="none" stroke="#0b1118" strokeWidth={small?3:4} opacity=".55"/>
    <path d={shape} fill="none" stroke="#ffffff" strokeWidth={small?2.2:1.6} opacity={small?.45:.35}/>
    {/* yıldızlar */}
    {stars>0&&!small&&<g fill="#ffd75e" stroke="#0b1118" strokeWidth=".8">
      {Array.from({length:stars}).map((_,i)=>{
        const cx=50+(i-(stars-1)/2)*16, cy=17;
        return(<path key={i} transform={`translate(${cx} ${cy}) scale(.62)`}
          d="M0-9l2.6 5.4 5.9.9-4.3 4.1 1 5.9L0 3.5l-5.2 2.8 1-5.9-4.3-4.1 5.9-.9z"/>);})}
    </g>}
    {/* baş harfler — küçük armada kontur inceltilir, punto büyütülür */}
    <text x="50" y={stars>0&&!small?"68":"64"} textAnchor="middle"
      fontFamily="'Saira Condensed',sans-serif" fontWeight="700" fontStyle="italic"
      fontSize={small?(ini.length>2?40:48):(ini.length>2?32:38)}
      fill="#ffffff" stroke="#0b1118" strokeWidth={small?1.2:2.4}
      paintOrder="stroke" letterSpacing={small?0:1}>{ini}</text>
  </svg>);
}

// ══════════════════════════════════════════════════════════════════
//  MALZEME — paneller düz 1px kenarlıklı kutulardı ("kripto uygulaması"
//  görünümünün asıl kaynağı). Artık film greni + üst ışık + katmanlı
//  gölge var.
// ══════════════════════════════════════════════════════════════════
const GRAIN="data:image/svg+xml;utf8,"+encodeURIComponent(
  `<svg xmlns='http://www.w3.org/2000/svg' width='140' height='140'>
     <filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3'/>
       <feColorMatrix type='saturate' values='0'/></filter>
     <rect width='140' height='140' filter='url(#n)' opacity='.55'/></svg>`);

// Sayılar anında değişiyordu; artık sayarak geliyor (algılanan kalite).
function useCountUp(value,ms=650){
  const [v,setV]=useState(value);
  const from=useRef(value), t0=useRef(0), raf=useRef(0);
  useEffect(()=>{
    if(typeof value!=="number"||!isFinite(value)){setV(value);return;}
    from.current=typeof v==="number"?v:value; t0.current=0;
    const step=(t)=>{
      if(!t0.current) t0.current=t;
      const k=Math.min(1,(t-t0.current)/ms);
      const e=1-Math.pow(1-k,3);
      setV(from.current+(value-from.current)*e);
      if(k<1) raf.current=requestAnimationFrame(step);
    };
    raf.current=requestAnimationFrame(step);
    return ()=>cancelAnimationFrame(raf.current);
  },[value]);// eslint-disable-line react-hooks/exhaustive-deps
  return v;
}
const Num=({v,d=0,style={}})=>{
  const a=useCountUp(typeof v==="number"?v:0);
  if(typeof v!=="number") return <span style={style}>{v}</span>;
  return <span style={style}>{d?a.toFixed(d):Math.round(a).toLocaleString("tr")}</span>;
};

// ══════════ CLUB KIT (Forma/Arma Görseli) ══════════
const ClubKit=({color,size=44,secondColor,stripes=false,hoops=false})=>{
  const c1=color||"#444";
  const c2=secondColor||(color?"#ffffff":C.card2);
  const s=size;
  const sw=Math.round(s*0.58);
  const sh=Math.round(s*0.62);
  const sx=(s-sw)/2;
  const sy=Math.round(s*0.20);
  // Yaka
  const collarW=Math.round(sw*0.30);
  const collarH=Math.round(sh*0.14);
  const collarX=sx+Math.round((sw-collarW)/2);
  // Kol genişliği
  const sleeveW=Math.round(s*0.16);
  const sleeveH=Math.round(sh*0.36);
  // Arma (shield)
  const shieldW=Math.round(sw*0.28);
  const shieldH=Math.round(sh*0.28);
  const shieldX=sx+Math.round((sw-shieldW)/2);
  const shieldY=sy+Math.round(sh*0.22);

  // Şerit pattern
  const stripePattern=stripes?(
    <defs>
      <pattern id={`stripe_${c1.replace("#","")}`} width="8" height="1" patternUnits="userSpaceOnUse">
        <rect width="4" height="1" fill={c1}/>
        <rect x="4" width="4" height="1" fill={c2}/>
      </pattern>
    </defs>
  ):null;
  const hooopPattern=hoops?(
    <defs>
      <pattern id={`hoop_${c1.replace("#","")}`} width="1" height="8" patternUnits="userSpaceOnUse">
        <rect width="1" height="4" fill={c1}/>
        <rect y="4" width="1" height="4" fill={c2}/>
      </pattern>
    </defs>
  ):null;
  const kitFill=stripes?`url(#stripe_${c1.replace("#","")})`:(hoops?`url(#hoop_${c1.replace("#","")})`:c1);

  return(
    <svg width={s} height={s} viewBox={`0 0 ${s} ${s}`} style={{flexShrink:0,display:"block"}}>
      {stripePattern||hooopPattern}
      {/* Sol kol */}
      <rect x={sx-sleeveW+2} y={sy+2} width={sleeveW} height={sleeveH} rx="3" fill={kitFill} opacity="0.85"/>
      {/* Sağ kol */}
      <rect x={sx+sw-2} y={sy+2} width={sleeveW} height={sleeveH} rx="3" fill={kitFill} opacity="0.85"/>
      {/* Gövde */}
      <rect x={sx} y={sy} width={sw} height={sh} rx="5" fill={kitFill}/>
      {/* Yaka */}
      <rect x={collarX} y={sy-2} width={collarW} height={collarH} rx="4" fill={c2} opacity="0.9"/>
      {/* Yaka çizgisi */}
      <rect x={collarX+1} y={sy-1} width={collarW-2} height={collarH-2} rx="3" fill="none" stroke={c1} strokeWidth="1" opacity="0.4"/>
      {/* Arma (shield) */}
      <path
        d={`M${shieldX+shieldW/2},${shieldY} L${shieldX+shieldW},${shieldY+shieldH*0.35} L${shieldX+shieldW},${shieldY+shieldH*0.7} Q${shieldX+shieldW/2},${shieldY+shieldH} ${shieldX},${shieldY+shieldH*0.7} L${shieldX},${shieldY+shieldH*0.35} Z`}
        fill={c2} opacity="0.92" stroke={c1} strokeWidth="0.8"
      />
      {/* Arma yıldız */}
      <text x={shieldX+shieldW/2} y={shieldY+shieldH*0.68} textAnchor="middle" fontSize={shieldH*0.45} fill={c1} opacity="0.9">★</text>
    </svg>
  );
};

// Forma şerit tipini kulüp rengine göre belirle (ikinci renk + şerit/hoop bilgisi)
const getKitStyle=(club)=>{
  const n=club.name.toLowerCase();
  const stripeClubs=["inter milan","ac milan","juventus","atletico madrid","borussia dortmund","crystal palace","fc barcelona","barcelona","river plate"];
  const hoopClubs=["celtic","queens park","qpr","athletic bilbao"];
  const secondColors={
    "galatasaray":"#c8a200","fenerbahçe":"#f5d000","beşiktaş":"#000000",
    "trabzonspor":"#c8a200","real madrid":"#ffd700","barcelona":"#a50044",
    "inter milan":"#000000","juventus":"#000000","ac milan":"#000000",
    "borussia dortmund":"#000000","atletico madrid":"#ffffff","ajax":"#ffffff",
    "psv eindhoven":"#ffffff","manchester city":"#ffffff","chelsea":"#ffffff",
    "arsenal":"#ffffff","liverpool":"#c8b400","tottenham":"#132257",
    "psg":"#da291c","monaco":"#ffffff",
    "bayer leverkusen":"#000000","rb leipzig":"#ffffff",
    "villarreal":"#000099","las palmas":"#003399",
  };
  const stripes=stripeClubs.some(s=>n.includes(s.split(" ")[0]));
  const hoops=hoopClubs.some(s=>n.includes(s.split(" ")[0]));
  const second=secondColors[club.name.toLowerCase()]||"#ffffff";
  return{stripes,hoops,secondColor:second};
};

const PlayerCard=({player,club})=>{
  const pc={ST:C.red,LW:C.orange,RW:C.orange,CAM:C.orange,CM:C.green,CDM:C.accent,CB:C.accent,LB:C.accent,RB:C.accent,GK:C.gold}[player.pos]||C.accent;
  const fa=player.formHistory?.length?(player.formHistory.slice(-5).reduce((a,b)=>a+b,0)/Math.min(5,player.formHistory.length)).toFixed(1):"–";
  const phase=getPhase(player.overall);
  return(<div style={{background:`linear-gradient(145deg,${C.card2},${C.card})`,border:`1px solid ${pc}44`,borderRadius:16,padding:14,position:"relative",overflow:"hidden"}}>
    <div style={{position:"absolute",top:-20,right:-20,width:120,height:120,background:`radial-gradient(circle,${pc}22,transparent 70%)`,pointerEvents:"none"}}/>
    <div style={{display:"flex",gap:11,alignItems:"center"}}>
      <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:4}}>
        {(()=>{const ks=getKitStyle(club);return(<ClubKit color={club.color} secondColor={ks.secondColor} stripes={ks.stripes} hoops={ks.hoops} size={56}/>);})()}
        <OVR value={player.overall} size={44}/>
        <Bdg c={pc}>{player.pos}</Bdg>
        <div style={{fontSize:9,color:C.muted,textAlign:"center"}}>Form:<span style={{color:Number(fa)>=7?C.green:Number(fa)>=5.5?C.gold:C.red,fontWeight:700}}> {fa}</span></div>
      </div>
      <div style={{flex:1,minWidth:0}}>
        <div style={{fontFamily:"'Baloo 2',sans-serif",fontSize:14,fontWeight:900,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{player.name}</div>
        <div style={{fontSize:10,color:C.muted,marginTop:2}}>{player.nat} · {player.age} yaş · {player.foot}</div>
        <div style={{display:"flex",gap:4,marginTop:5,flexWrap:"wrap"}}>
          <LgBdg leagueId={club.leagueId}/>
          <Bdg c={C.gold}>POT {player.potential}</Bdg>
        </div>
        <div style={{marginTop:5,display:"flex",gap:4,flexWrap:"wrap"}}>
          <Bdg c={pc}>{phase.icon} {phase.name}</Bdg>
          {player.traits.map(t=><Bdg key={t} c={C.muted}>{t}</Bdg>)}
        </div>
      </div>
    </div>
    <div style={{display:"grid",gridTemplateColumns:"repeat(6,1fr)",gap:5,marginTop:11}}>
      {[["HIZ",player.pace],["ŞUT",player.shooting],["PAS",player.passing],["DRB",player.dribbling],["DEF",player.defending],["FİZ",player.physical]].map(([l,v])=>{
        const sc=v>=80?C.green:v>=65?C.accent:v>=50?C.gold:C.red;
        return <div key={l} style={{background:C.bg,borderRadius:7,padding:"5px 0",textAlign:"center"}}><div style={{fontSize:15,fontWeight:900,fontFamily:"'Baloo 2',sans-serif",color:sc}}>{v}</div><div style={{fontSize:8,color:C.muted}}>{l}</div></div>;
      })}
    </div>
  </div>);
};

// ══════════ PENALTY MINI GAME ══════════
function PenaltyGame({player,onDone}){
  const [barPos,setBarPos]=useState(50);
  const [shot,setShot]=useState(null);
  const [scored,setScored]=useState(false);
  const [outcome,setOutcome]=useState("goal");
  const iv=useRef(null);
  const CORNERS=["↖️ Sol Üst","↗️ Sağ Üst","⬅️ Sol","➡️ Sağ","↙️ Sol Alt","↘️ Sağ Alt"];
  useEffect(()=>{
    if(shot)return;
    let pos=50,dir=1,spd=2.8-(player.shooting/99)*1.5;
    iv.current=setInterval(()=>{pos+=dir*spd;if(pos>=100||pos<=0)dir*=-1;setBarPos(pos);},28);
    return()=>clearInterval(iv.current);
  },[shot]);
  // Köşe zorluğu: üst köşeler riskli ama kaleci için ulaşılmaz,
  // yan direk dipleri güvenli. Seçim artık gerçekten sonucu değiştiriyor.
  const CORNER_RISK={0:{miss:.14,save:.05},1:{miss:.14,save:.05},
                     2:{miss:.04,save:.17},3:{miss:.04,save:.17},
                     4:{miss:.07,save:.11},5:{miss:.07,save:.11}};
  function shoot(c,idx){
    clearInterval(iv.current);
    const acc=Math.abs(barPos-50)/50;              // 0 = tam isabet
    const risk=CORNER_RISK[idx]||CORNER_RISK[2];
    const composure=(player.traits?.includes("Penaltı Uzmanı")?0.06:0)
                   +(player.traits?.includes("Soğukkanlı")?0.03:0);
    const missed=Math.random()<Math.max(0,risk.miss+acc*0.22-composure);
    const saved=!missed&&Math.random()<Math.max(0,risk.save+acc*0.18-composure);
    const ok=!missed&&!saved;
    setShot(c);setScored(ok);setOutcome(missed?"miss":saved?"save":"goal");
    setTimeout(()=>onDone(ok),1800);
  }
  return(<div style={{position:"fixed",inset:0,background:"#000000e0",zIndex:500,display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
    <Card glow gc={C.gold} style={{maxWidth:330,width:"100%",textAlign:"center"}}>
      <div style={{fontFamily:"'Baloo 2',sans-serif",fontSize:15,color:C.gold,marginBottom:4}}>⚽ PENALTİ!</div>
      {!shot&&(<>
        <div style={{fontSize:11,color:C.muted,marginBottom:10}}>Çubuğu izle, köşe seç!</div>
        <div style={{position:"relative",height:16,background:C.card2,borderRadius:8,marginBottom:13,overflow:"hidden"}}>
          <div style={{position:"absolute",left:"35%",right:"35%",top:0,bottom:0,background:`${C.green}33`,borderRadius:8}}/>
          <div style={{position:"absolute",top:0,bottom:0,width:13,background:C.gold,borderRadius:7,left:`${barPos}%`,transform:"translateX(-50%)",transition:"left .028s"}}/>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:6,marginBottom:6}}>
          {CORNERS.slice(0,3).map((c,i)=>(<Btn key={c} v="ghost" onClick={()=>shoot(c,i)} style={{fontSize:10,padding:"7px 3px"}}>{c}</Btn>))}
        </div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:6}}>
          {CORNERS.slice(3).map((c,i)=>(<Btn key={c} v="ghost" onClick={()=>shoot(c,i+3)} style={{fontSize:10,padding:"7px 3px"}}>{c}</Btn>))}
        </div>
      </>)}
      {shot&&(<div className="pop">
        <div style={{fontSize:42,marginBottom:6}}>{outcome==="goal"?"⚽":outcome==="save"?"🧤":"😱"}</div>
        <div style={{fontFamily:F.disp,fontSize:16,color:scored?C.green:C.red}}>
          {outcome==="goal"?"GOL!":outcome==="save"?"KALECİ KURTARDI!":"DIŞARI!"}</div>
        <div style={{fontSize:11,color:C.muted,marginTop:4}}>{shot}</div>
      </div>)}
    </Card>
  </div>);
}

// ══════════ FRİKİK MİNİ OYUNU ══════════
function FreekickGame({player,onDone}){
  // Aşamalar: "aim" → "power" → "curve" → "result"
  const [phase,setPhase]=useState("aim");
  // AIM: yatay hedef çubuğu (0-100, 50=merkez)
  const [aimPos,setAimPos]=useState(50);
  const [aimDir,setAimDir]=useState(1);
  // POWER: güç çubuğu (0-100)
  const [powerPos,setPowerPos]=useState(0);
  const [powerDir,setPowerDir]=useState(1);
  // CURVE: top eğrisi (0-100, 50=düz)
  const [curvePos,setCurvePos]=useState(50);
  const [curveDir,setCurveDir]=useState(1);
  // Kilitli değerler
  const [lockedAim,setLockedAim]=useState(null);
  const [lockedPower,setLockedPower]=useState(null);
  const [result,setResult]=useState(null);
  const iv=useRef(null);

  const shooting=player.shooting;
  const AIM_SPD=3.2-(shooting/99)*1.4;
  const POW_SPD=2.8-(shooting/99)*1.0;
  const CURVE_SPD=3.5-(shooting/99)*1.6;

  // Hedef aşaması hareketi
  useEffect(()=>{
    if(phase!=="aim")return;
    iv.current=setInterval(()=>{
      setAimPos(p=>{let n=p+aimDir*AIM_SPD;if(n>=100){setAimDir(-1);n=100;}if(n<=0){setAimDir(1);n=0;}return n;});
    },28);
    return()=>clearInterval(iv.current);
  },[phase,aimDir]);

  // Güç aşaması hareketi
  useEffect(()=>{
    if(phase!=="power")return;
    iv.current=setInterval(()=>{
      setPowerPos(p=>{let n=p+powerDir*POW_SPD;if(n>=100){setPowerDir(-1);n=100;}if(n<=0){setPowerDir(1);n=0;}return n;});
    },28);
    return()=>clearInterval(iv.current);
  },[phase,powerDir]);

  // Eğri aşaması hareketi
  useEffect(()=>{
    if(phase!=="curve")return;
    iv.current=setInterval(()=>{
      setCurvePos(p=>{let n=p+curveDir*CURVE_SPD;if(n>=100){setCurveDir(-1);n=100;}if(n<=0){setCurveDir(1);n=0;}return n;});
    },28);
    return()=>clearInterval(iv.current);
  },[phase,curveDir]);

  function lockAim(){
    clearInterval(iv.current);
    setLockedAim(aimPos);
    setPhase("power");
  }
  function lockPower(){
    clearInterval(iv.current);
    setLockedPower(powerPos);
    setPhase("curve");
  }
  function lockCurve(){
    clearInterval(iv.current);
    const locked={aim:lockedAim,power:lockedPower,curve:curvePos};
    // Hesaplama: merkeze yakınlık + güç + eğri kombinasyonu
    const aimAcc=1-Math.abs(locked.aim-50)/50;        // 0-1, 1=mükemmel merkez
    // Güçte ideal bant ~%78: tam güç topu barın üstünden aşırır.
    const powAcc=Math.max(0,1-Math.abs(locked.power-78)/78);
    const curveAcc=1-Math.abs(locked.curve-50)/50;    // 0-1, 1=düz
    // Gerçek frikik dönüşümü ~%7. Mükemmel uygulama ödüllendirilir ama
    // tavan %92 değil: iyi bir vuruşta ~%35-40 bandında kalır.
    const baseChance=0.03+(shooting/99)*0.12;
    const skill=(player.traits?.includes("Serbest Vuruş")?0.08:0)
               +((player.setPiece||30)/100)*0.10;
    const bonus=aimAcc*0.16+powAcc*0.10+curveAcc*0.08;
    const scored=Math.random()<Math.min(0.45,baseChance+skill+bonus);
    // Kale içi top konumu (görsel): hedef + eğri etkisi
    const ballX=locked.aim+(locked.curve-50)*0.3; // eğri sola/sağa kaydırır
    const ballY=100-locked.power*0.7;              // güç yukarı-aşağı etkiler
    const blocked=!scored&&Math.random()<0.55;     // kurtarış mı yoksa dışarı mı?
    setResult({scored,ballX:Math.max(5,Math.min(95,ballX)),ballY:Math.max(10,Math.min(90,ballY)),blocked,locked});
    setPhase("result");
    setTimeout(()=>onDone(scored),2200);
  }

  // Top yolu görselleştirmesi — sonuç ekranı için
  const GoalMouth=({ballX,ballY,scored,blocked})=>(
    <div style={{position:"relative",width:"100%",height:110,marginBottom:10}}>
      {/* Arka zemin */}
      <div style={{position:"absolute",inset:0,background:"linear-gradient(180deg,#001a00,#003300)",borderRadius:10,overflow:"hidden"}}>
        <div style={{position:"absolute",bottom:0,left:0,right:0,height:18,background:"linear-gradient(180deg,#005500,#003300)"}}/>
      </div>
      {/* Kale */}
      <div style={{position:"absolute",left:"15%",right:"15%",top:"10%",height:"72%",border:`3px solid ${scored?C.green:blocked?C.gold:"#ffffff66"}`,borderBottom:"none",borderRadius:"3px 3px 0 0",transition:"border-color .5s"}}>
        {/* Kale ağı çizgileri */}
        {[25,50,75].map(x=>(<div key={x} style={{position:"absolute",left:`${x}%`,top:0,bottom:0,width:1,background:"#ffffff11"}}/>))}
        {[33,66].map(y=>(<div key={y} style={{position:"absolute",top:`${y}%`,left:0,right:0,height:1,background:"#ffffff11"}}/>))}
        {/* Top */}
        {phase==="result"&&(<div className="pop" style={{
          position:"absolute",
          left:`${ballX}%`,top:`${ballY}%`,
          transform:"translate(-50%,-50%)",
          fontSize:22,filter:`drop-shadow(0 0 8px ${scored?C.green:C.red}88)`,
          zIndex:2,
        }}>⚽</div>)}
        {/* Kaleci */}
        <div style={{
          position:"absolute",bottom:0,
          left:phase==="result"?`${scored?rand(10,40):Math.max(10,Math.min(80,ballX-10))}%`:"40%",
          fontSize:20,transition:"left .4s ease",
        }}>🧤</div>
      </div>
      {/* Bariyer */}
      <div style={{position:"absolute",bottom:"28%",left:"30%",display:"flex",gap:2}}>
        {[0,1,2,3].map(i=>(<div key={i} style={{fontSize:14,opacity:.85}}>🧍</div>))}
      </div>
      {/* Sonuç etiketi */}
      {phase==="result"&&(<div className="pop" style={{
        position:"absolute",top:"8%",left:"50%",transform:"translateX(-50%)",
        fontFamily:"'Baloo 2',sans-serif",fontSize:15,fontWeight:900,
        color:scored?C.green:blocked?C.gold:C.red,
        textShadow:`0 0 16px ${scored?C.green:blocked?C.gold:C.red}`,
        whiteSpace:"nowrap",
      }}>{scored?"GOL! 🔥":blocked?"KALECİ KURTARDI!":"AÇIK GITTI!"}</div>)}
    </div>
  );

  const phaseLabels={aim:"🎯 HEDEF",power:"💥 GÜÇ",curve:"🌀 EĞRİ"};
  const phaseHints={aim:"Çubuğu izle — tam ortada durdur!",power:"Gücü ayarla — çok fazla veya çok az olmasın!",curve:"Eğriyi belirle — düz mü, köşe mi?"};

  return(<div style={{position:"fixed",inset:0,background:"#000000ee",zIndex:500,display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
    <Card glow gc={C.orange} style={{maxWidth:340,width:"100%"}}>
      <div style={{textAlign:"center",marginBottom:10}}>
        <div style={{fontFamily:"'Baloo 2',sans-serif",fontSize:15,color:C.orange}}>🌀 FRİKİK!</div>
        {phase!=="result"&&<div style={{fontSize:10,color:C.muted,marginTop:2}}>{phaseHints[phase]}</div>}
      </div>

      {/* Aşama indikatörleri */}
      {phase!=="result"&&(<div style={{display:"flex",gap:4,justifyContent:"center",marginBottom:12}}>
        {["aim","power","curve"].map(p=>(
          <div key={p} style={{display:"flex",alignItems:"center",gap:4}}>
            <div style={{padding:"3px 8px",borderRadius:6,fontSize:9,fontFamily:"'Fredoka',sans-serif",fontWeight:700,
              background:phase===p?`${C.orange}33`:p==="aim"&&(phase==="power"||phase==="curve")||p==="power"&&phase==="curve"?`${C.green}22`:`${C.border}`,
              color:phase===p?C.orange:p==="aim"&&(phase==="power"||phase==="curve")||p==="power"&&phase==="curve"?C.green:C.muted,
              border:`1px solid ${phase===p?C.orange:C.border}`,
            }}>{phaseLabels[p]}</div>
            {p!=="curve"&&<div style={{width:12,height:1,background:C.border}}/>}
          </div>
        ))}
      </div>)}

      {/* Kale görselleştirmesi */}
      <GoalMouth
        ballX={result?.ballX??50} ballY={result?.ballY??50}
        scored={result?.scored} blocked={result?.blocked}
      />

      {/* Kontrol çubukları */}
      {phase==="aim"&&(<>
        <div style={{marginBottom:6}}>
          <div style={{display:"flex",justifyContent:"space-between",fontSize:9,color:C.muted,marginBottom:3}}>
            <span>◀ Sol köşe</span><span style={{color:C.orange,fontWeight:700}}>{phaseLabels.aim}</span><span>Sağ köşe ▶</span>
          </div>
          <div style={{position:"relative",height:18,background:C.card2,borderRadius:9,overflow:"hidden",marginBottom:10}}>
            {/* Yeşil "iyi bölge" — ortada */}
            <div style={{position:"absolute",left:"30%",right:"30%",top:0,bottom:0,background:`${C.green}22`,borderRadius:9}}/>
            {/* Turuncu çubuk */}
            <div style={{position:"absolute",top:1,bottom:1,width:14,background:C.orange,borderRadius:7,left:`${aimPos}%`,transform:"translateX(-50%)",boxShadow:`0 0 6px ${C.orange}99`,transition:"left .028s"}}/>
            {/* Merkez çizgisi */}
            <div style={{position:"absolute",top:0,bottom:0,left:"50%",width:1,background:"#ffffff22"}}/>
          </div>
        </div>
        <Btn v="orange" onClick={lockAim} style={{width:"100%",fontSize:13,letterSpacing:0}}>🎯 HEDEF KİLİTLE!</Btn>
      </>)}

      {phase==="power"&&(<>
        <div style={{marginBottom:6}}>
          <div style={{display:"flex",justifyContent:"space-between",fontSize:9,color:C.muted,marginBottom:3}}>
            <span>Hafif</span><span style={{color:C.accent,fontWeight:700}}>{phaseLabels.power}</span><span>Maksimum</span>
          </div>
          <div style={{position:"relative",height:18,background:C.card2,borderRadius:9,overflow:"hidden",marginBottom:4}}>
            {/* Tatlı nokta: %55-80 arası */}
            <div style={{position:"absolute",left:"55%",right:"20%",top:0,bottom:0,background:`${C.green}22`,borderRadius:9}}/>
            <div style={{position:"absolute",top:1,bottom:1,width:14,background:C.accent,borderRadius:7,left:`${powerPos}%`,transform:"translateX(-50%)",boxShadow:`0 0 6px ${C.accent}99`,transition:"left .028s"}}/>
          </div>
          <div style={{textAlign:"center",fontSize:10,color:C.accent,fontFamily:"'Baloo 2',sans-serif",marginBottom:6}}>{Math.round(powerPos)}%</div>
        </div>
        <Btn v="pri" onClick={lockPower} style={{width:"100%",fontSize:13,letterSpacing:0}}>💥 GÜÇ KİLİTLE!</Btn>
      </>)}

      {phase==="curve"&&(<>
        <div style={{marginBottom:6}}>
          <div style={{display:"flex",justifyContent:"space-between",fontSize:9,color:C.muted,marginBottom:3}}>
            <span>◀ Sola eğri</span><span style={{color:C.purple,fontWeight:700}}>{phaseLabels.curve}</span><span>Sağa eğri ▶</span>
          </div>
          <div style={{position:"relative",height:18,background:C.card2,borderRadius:9,overflow:"hidden",marginBottom:4}}>
            {/* Düz bölge: ortada */}
            <div style={{position:"absolute",left:"42%",right:"42%",top:0,bottom:0,background:`${C.accent}22`,borderRadius:9}}/>
            <div style={{position:"absolute",top:1,bottom:1,width:14,background:C.purple,borderRadius:7,left:`${curvePos}%`,transform:"translateX(-50%)",boxShadow:`0 0 6px ${C.purple}99`,transition:"left .028s"}}/>
            <div style={{position:"absolute",top:0,bottom:0,left:"50%",width:1,background:"#ffffff22"}}/>
          </div>
          <div style={{display:"flex",justifyContent:"space-between",fontSize:8,color:C.muted,marginBottom:6,paddingLeft:4,paddingRight:4}}>
            <span>{curvePos<42?"← Eğri":curvePos>58?"→ Eğri":"⊙ Düz"}</span>
            <span style={{color:C.purple}}>{Math.round(Math.abs(curvePos-50)*2)}° eğri</span>
          </div>
        </div>
        <Btn v="purple" onClick={lockCurve} style={{width:"100%",fontSize:13,letterSpacing:0}}>🌀 VURUŞ!</Btn>
      </>)}

      {phase==="result"&&result&&(<div className="pop" style={{textAlign:"center",marginTop:4}}>
        <div style={{display:"flex",justifyContent:"center",gap:14,fontSize:10,color:C.muted}}>
          <span>🎯 Hedef: <b style={{color:C.orange}}>{Math.round(100-Math.abs(result.locked.aim-50)*2)}%</b></span>
          <span>💥 Güç: <b style={{color:C.accent}}>{Math.round(result.locked.power)}%</b></span>
          <span>🌀 Eğri: <b style={{color:C.purple}}>{Math.round(Math.abs(result.locked.curve-50)*2)}°</b></span>
        </div>
      </div>)}
    </Card>
  </div>);
}


// ══════════ 3D GOL ANİMASYONU ══════════
const GOAL_TYPES = [
  {id:"low_left",   label:"Sol Alt Köşe",   ballX:18, ballY:78, shotAngle:"sert sol köşe"},
  {id:"low_right",  label:"Sağ Alt Köşe",   ballX:82, ballY:78, shotAngle:"sert sağ köşe"},
  {id:"top_left",   label:"Sol Üst Köşe",   ballX:20, ballY:18, shotAngle:"üst köşe"},
  {id:"top_right",  label:"Sağ Üst Köşe",   ballX:80, ballY:18, shotAngle:"üst köşe"},
  {id:"center_low", label:"Orta Alt",        ballX:50, ballY:82, shotAngle:"düz orta"},
  {id:"top_center", label:"Üst Orta",        ballX:50, ballY:14, shotAngle:"üst orta"},
  {id:"chip",       label:"Çip",             ballX:50, ballY:45, shotAngle:"çip"},
];

function GoalAnimation({goals, playerName, onClose}) {
  const [phase, setPhase] = useState("celebrate"); // celebrate | replay | done
  const [goalIndex, setGoalIndex] = useState(0);
  const [showBall, setShowBall] = useState(false);
  const [netShake, setNetShake] = useState(false);
  const [playerAnim, setPlayerAnim] = useState("run"); // run | shoot | celebrate
  const [showButton, setShowButton] = useState(false); // netShake'ten BAĞIMSIZ - bug fix

  const goalType = GOAL_TYPES[Math.floor(Math.random() * GOAL_TYPES.length)];

  useEffect(() => {
    // Sequence: player runs → shoots → ball flies → net shakes → celebrate
    const t1 = setTimeout(() => setPlayerAnim("shoot"), 400);
    const t2 = setTimeout(() => setShowBall(true), 700);
    const t3 = setTimeout(() => setNetShake(true), 1100);
    const t4 = setTimeout(() => setPlayerAnim("celebrate"), 1200);
    const t5 = setTimeout(() => { setNetShake(false); }, 1800);
    const t6 = setTimeout(() => { setShowButton(true); }, 1500); // buton netShake bitmeden önce gelir, kalır
    return () => [t1,t2,t3,t4,t5,t6].forEach(clearTimeout);
  }, [goalIndex]);

  // 3D Footballer SVG (gerçekçi vücut oranları)
  function FootballerSVG({ anim, shirtColor = C.accent }) {
    // Animasyon fazına göre poz
    const isShoot = anim === "shoot";
    const isCelebrate = anim === "celebrate";

    // Gövde koordinatları
    const cx = 60; // merkez x

    // Baş
    const headX = cx, headY = isShoot ? 30 : isCelebrate ? 24 : 30;
    const headR = 13;
    // Boyun
    const neckY = headY + headR;
    // Gövde
    const torsoY1 = neckY + 2;
    const torsoY2 = torsoY1 + 38;
    const torsoW = 22;
    // Bacaklar
    const hipY = torsoY2;
    // Sol bacak (vuruş bacağı)
    const lKneeX = isShoot ? cx - 18 : cx - 10;
    const lKneeY = isShoot ? hipY + 20 : hipY + 26;
    const lFootX = isShoot ? cx - 26 : cx - 12;
    const lFootY = isShoot ? hipY + 10 : hipY + 46;
    // Sağ bacak (destek bacağı)
    const rKneeX = isCelebrate ? cx + 15 : cx + 10;
    const rKneeY = isCelebrate ? hipY + 20 : hipY + 26;
    const rFootX = isCelebrate ? cx + 22 : cx + 12;
    const rFootY = isCelebrate ? hipY + 8 : hipY + 46;
    // Kollar
    const lShoulderX = cx - torsoW/2;
    const rShoulderX = cx + torsoW/2;
    const shoulderY = torsoY1 + 6;
    const lElbowX = isShoot ? cx - 36 : isCelebrate ? cx - 32 : cx - 28;
    const lElbowY = isShoot ? shoulderY + 18 : isCelebrate ? shoulderY - 8 : shoulderY + 18;
    const lHandX = isShoot ? cx - 28 : isCelebrate ? cx - 40 : cx - 22;
    const lHandY = isShoot ? shoulderY + 30 : isCelebrate ? shoulderY - 20 : shoulderY + 32;
    const rElbowX = isShoot ? cx + 34 : isCelebrate ? cx + 32 : cx + 28;
    const rElbowY = isShoot ? shoulderY + 10 : isCelebrate ? shoulderY - 8 : shoulderY + 18;
    const rHandX = isShoot ? cx + 44 : isCelebrate ? cx + 42 : cx + 22;
    const rHandY = isShoot ? shoulderY - 2 : isCelebrate ? shoulderY - 20 : shoulderY + 32;

    const bodyStyle = { transition: "all 0.25s ease" };

    return (
      <svg viewBox="0 0 120 170" width="90" height="130" style={{ overflow:"visible", filter:`drop-shadow(0 4px 16px ${shirtColor}66)` }}>
        {/* Gölge */}
        <ellipse cx={cx} cy={162} rx={isShoot?24:20} ry={4} fill="#000000" opacity="0.35"/>

        {/* Bacaklar - arkada kalanlar önce */}
        {/* Sol bacak uyluk */}
        <line x1={cx-6} y1={hipY} x2={lKneeX} y2={lKneeY} stroke="#1a5f1a" strokeWidth="10" strokeLinecap="round" style={bodyStyle}/>
        <line x1={lKneeX} y1={lKneeY} x2={lFootX} y2={lFootY} stroke="#1a5f1a" strokeWidth="9" strokeLinecap="round" style={bodyStyle}/>
        {/* Sağ bacak */}
        <line x1={cx+6} y1={hipY} x2={rKneeX} y2={rKneeY} stroke="#1a6f1a" strokeWidth="10" strokeLinecap="round" style={bodyStyle}/>
        <line x1={rKneeX} y1={rKneeY} x2={rFootX} y2={rFootY} stroke="#1a6f1a" strokeWidth="9" strokeLinecap="round" style={bodyStyle}/>

        {/* Kramponlar */}
        <ellipse cx={lFootX} cy={lFootY+4} rx="7" ry="4" fill="#222" style={bodyStyle}/>
        <ellipse cx={rFootX} cy={rFootY+4} rx="7" ry="4" fill="#333" style={bodyStyle}/>

        {/* Çoraplar */}
        <line x1={lKneeX+(lFootX-lKneeX)*0.3} y1={lKneeY+(lFootY-lKneeY)*0.3} x2={lFootX} y2={lFootY} stroke="#ffffff33" strokeWidth="7" strokeLinecap="round" style={bodyStyle}/>
        <line x1={rKneeX+(rFootX-rKneeX)*0.3} y1={rKneeY+(rFootY-rKneeY)*0.3} x2={rFootX} y2={rFootY} stroke="#ffffff33" strokeWidth="7" strokeLinecap="round" style={bodyStyle}/>

        {/* Şort */}
        <path d={`M${cx-torsoW/2+2},${hipY} Q${cx},${hipY+8} ${cx+torsoW/2-2},${hipY} L${cx+torsoW/2-4},${hipY+16} Q${cx},${hipY+20} ${cx-torsoW/2+4},${hipY+16} Z`}
          fill="#111122" stroke="#ffffff22" strokeWidth="0.5" style={bodyStyle}/>

        {/* Formanın alt şeridi */}
        <rect x={cx-torsoW/2} y={torsoY2-8} width={torsoW} height={8} rx="2" fill={`${shirtColor}dd`} style={bodyStyle}/>

        {/* Forma gövdesi */}
        <path d={`M${cx-torsoW/2},${torsoY1+12} L${cx-torsoW/2},${torsoY2} Q${cx},${torsoY2+4} ${cx+torsoW/2},${torsoY2} L${cx+torsoW/2},${torsoY1+12} Z`}
          fill={shirtColor} style={bodyStyle}/>

        {/* Omuzlar / kollar */}
        <path d={`M${cx-torsoW/2},${torsoY1+12} L${cx-torsoW/2-8},${torsoY1+4} L${lShoulderX},${shoulderY} Z`}
          fill={shirtColor} style={bodyStyle}/>
        <path d={`M${cx+torsoW/2},${torsoY1+12} L${cx+torsoW/2+8},${torsoY1+4} L${rShoulderX},${shoulderY} Z`}
          fill={shirtColor} style={bodyStyle}/>

        {/* Sol kol */}
        <line x1={lShoulderX} y1={shoulderY} x2={lElbowX} y2={lElbowY} stroke={shirtColor} strokeWidth="9" strokeLinecap="round" style={bodyStyle}/>
        <line x1={lElbowX} y1={lElbowY} x2={lHandX} y2={lHandY} stroke="#d4956a" strokeWidth="7" strokeLinecap="round" style={bodyStyle}/>
        {/* Sağ kol */}
        <line x1={rShoulderX} y1={shoulderY} x2={rElbowX} y2={rElbowY} stroke={shirtColor} strokeWidth="9" strokeLinecap="round" style={bodyStyle}/>
        <line x1={rElbowX} y1={rElbowY} x2={rHandX} y2={rHandY} stroke="#d4956a" strokeWidth="7" strokeLinecap="round" style={bodyStyle}/>

        {/* El */}
        <circle cx={lHandX} cy={lHandY} r="5" fill="#d4956a" style={bodyStyle}/>
        <circle cx={rHandX} cy={rHandY} r="5" fill="#d4956a" style={bodyStyle}/>

        {/* Forma çizgisi */}
        <line x1={cx} y1={torsoY1+12} x2={cx} y2={torsoY2-4} stroke="#ffffff22" strokeWidth="1.5" style={bodyStyle}/>

        {/* Boyun */}
        <rect x={cx-5} y={neckY} width={10} height={8} rx="4" fill="#d4956a" style={bodyStyle}/>

        {/* Yaka */}
        <path d={`M${cx-12},${torsoY1+12} Q${cx},${torsoY1-2} ${cx+12},${torsoY1+12}`} fill="none" stroke="#ffffff44" strokeWidth="2" style={bodyStyle}/>
        <path d={`M${cx-8},${torsoY1+14} Q${cx},${torsoY1+2} ${cx+8},${torsoY1+14}`} fill="none" stroke={shirtColor} strokeWidth="1.5" style={bodyStyle}/>

        {/* Baş */}
        <circle cx={headX} cy={headY} r={headR} fill="#d4956a" style={bodyStyle}/>
        {/* Saç */}
        <path d={`M${headX-headR*0.8},${headY-headR*0.5} Q${headX},${headY-headR*1.5} ${headX+headR*0.8},${headY-headR*0.5}`}
          fill="#2a1a0a" strokeWidth="0" style={bodyStyle}/>
        {/* Yüz */}
        <circle cx={headX-4} cy={headY-2} r="2" fill="#8B4513" opacity="0.8"/>
        <circle cx={headX+4} cy={headY-2} r="2" fill="#8B4513" opacity="0.8"/>
        <path d={isCelebrate ?
          `M${headX-5},${headY+4} Q${headX},${headY+9} ${headX+5},${headY+4}` :
          `M${headX-4},${headY+5} Q${headX},${headY+7} ${headX+4},${headY+5}`}
          fill="none" stroke="#8B4513" strokeWidth="1.5" strokeLinecap="round" style={bodyStyle}/>

        {/* Kutlama efekti */}
        {isCelebrate && <>
          <text x={cx+20} y={headY-15} fontSize="14" style={{animation:"none"}}>🎉</text>
          <text x={cx-36} y={headY-8} fontSize="11">⭐</text>
        </>}

        {/* Numara */}
        <text x={cx} y={torsoY1+28} textAnchor="middle" fontSize="9" fill="#ffffff99"
          fontFamily="'Fredoka',sans-serif" fontWeight="700">10</text>
      </svg>
    );
  }

  // Kale SVG — 3D perspektif
  function GoalNet3D({ shake, ballX, ballY, showBall: sb }) {
    const netColor = "#ffffff";
    // Ön kale direği koordinatları (trapez perspektif)
    const leftPostX = 30, rightPostX = 170, postTopY = 20, crossBarY = 80, groundY = 140;
    const leftPostGroundX = 42, rightPostGroundX = 158;
    // Arka kale (perspektif daralması)
    const bLeftX = 62, bRightX = 138, bTopY = 34, bGroundY = 110;
    // Ağ titreme offseti
    const shakeOff = shake ? `translate(${(Math.random()-0.5)*3},${Math.random()*2})` : "";

    // Top pozisyonu kale içinde — ballX/ballY 0-100
    const tbx = leftPostX + (ballX / 100) * (rightPostX - leftPostX);
    const tby = postTopY + (ballY / 100) * (crossBarY - postTopY + 10);

    return (
      <svg viewBox="0 0 200 160" width="200" height="140"
        style={{ filter: shake ? `drop-shadow(0 0 18px ${C.green}bb)` : "none", transition:"filter 0.2s" }}>

        {/* Zemin çizgisi */}
        <rect x="30" y="136" width="140" height="8" rx="2" fill="#2a5a1a" opacity="0.6"/>

        {/* Ağ — arka */}
        <g transform={shakeOff}>
          <line x1={bLeftX} y1={bTopY} x2={bRightX} y2={bTopY} stroke={netColor} strokeWidth="1" opacity="0.3"/>
          {[0,0.25,0.5,0.75,1].map(t=>(
            <line key={t} x1={bLeftX+(bRightX-bLeftX)*t} y1={bTopY}
              x2={bLeftX+(bGroundY-bTopY)*0.05+(bRightX-bLeftX)*t} y2={bGroundY}
              stroke={netColor} strokeWidth="0.8" opacity="0.25"/>
          ))}
          {[0,0.33,0.67,1].map(t=>(
            <line key={t} x1={bLeftX} y1={bTopY+(bGroundY-bTopY)*t}
              x2={bRightX} y2={bTopY+(bGroundY-bTopY)*t}
              stroke={netColor} strokeWidth="0.8" opacity="0.25"/>
          ))}
        </g>

        {/* Ağ — yan (sol) */}
        <g transform={shakeOff}>
          {[0,0.33,0.67,1].map(t=>(
            <line key={t}
              x1={leftPostX+(leftPostGroundX-leftPostX)*t} y1={crossBarY+(groundY-crossBarY)*t}
              x2={bLeftX+(bGroundY-bTopY)*0.02} y2={bTopY+(bGroundY-bTopY)*t}
              stroke={netColor} strokeWidth="0.7" opacity="0.2"/>
          ))}
        </g>
        {/* Ağ — yan (sağ) */}
        <g transform={shakeOff}>
          {[0,0.33,0.67,1].map(t=>(
            <line key={t}
              x1={rightPostX+(rightPostGroundX-rightPostX)*t} y1={crossBarY+(groundY-crossBarY)*t}
              x2={bRightX} y2={bTopY+(bGroundY-bTopY)*t}
              stroke={netColor} strokeWidth="0.7" opacity="0.2"/>
          ))}
        </g>

        {/* Ağ — ön dikey çizgiler */}
        <g transform={shakeOff}>
          {[0,0.125,0.25,0.375,0.5,0.625,0.75,0.875,1].map(t=>(
            <line key={t}
              x1={leftPostX+(rightPostX-leftPostX)*t} y1={crossBarY}
              x2={leftPostGroundX+(rightPostGroundX-leftPostGroundX)*t} y2={groundY}
              stroke={netColor} strokeWidth={t===0||t===1?"0":"0.9"} opacity="0.35"/>
          ))}
          {[0,0.2,0.4,0.6,0.8,1].map(t=>(
            <line key={t}
              x1={leftPostX+(rightPostX-leftPostX)*0} y1={crossBarY+(groundY-crossBarY)*t}
              x2={rightPostX} y2={crossBarY+(groundY-crossBarY)*t}
              stroke={netColor} strokeWidth="0.9" opacity="0.3"/>
          ))}
        </g>

        {/* Direkler — arka */}
        <line x1={bLeftX} y1={bTopY} x2={bLeftX} y2={bGroundY} stroke="#c8c8c8" strokeWidth="3" strokeLinecap="round"/>
        <line x1={bRightX} y1={bTopY} x2={bRightX} y2={bGroundY} stroke="#c8c8c8" strokeWidth="3" strokeLinecap="round"/>
        <line x1={bLeftX} y1={bTopY} x2={bRightX} y2={bTopY} stroke="#c8c8c8" strokeWidth="2.5"/>

        {/* Direkler — ön (kalın) */}
        <line x1={leftPostX} y1={crossBarY} x2={leftPostGroundX} y2={groundY} stroke="#e8e8e8" strokeWidth="5" strokeLinecap="round"/>
        <line x1={rightPostX} y1={crossBarY} x2={rightPostGroundX} y2={groundY} stroke="#e8e8e8" strokeWidth="5" strokeLinecap="round"/>
        <line x1={leftPostX} y1={crossBarY} x2={rightPostX} y2={crossBarY} stroke="#e8e8e8" strokeWidth="5" strokeLinecap="round"/>

        {/* Direk gölgesi / derinlik */}
        <line x1={leftPostX+3} y1={crossBarY+2} x2={leftPostGroundX+3} y2={groundY} stroke="#00000033" strokeWidth="4" strokeLinecap="round"/>
        <line x1={rightPostX+3} y1={crossBarY+2} x2={rightPostGroundX+3} y2={groundY} stroke="#00000033" strokeWidth="4" strokeLinecap="round"/>

        {/* Top */}
        {sb && (
          <g style={{animation:"goalBallIn 0.5s cubic-bezier(.22,1,.36,1) forwards"}}>
            <circle cx={tbx} cy={tby} r="9" fill="#ffffff" stroke="#cccccc" strokeWidth="1"/>
            <circle cx={tbx-2} cy={tby-2} r="3" fill="#333" opacity="0.8"/>
            <circle cx={tbx+3} cy={tby+2} r="2.5" fill="#333" opacity="0.6"/>
            <circle cx={tbx-1} cy={tby+3} r="2" fill="#333" opacity="0.5"/>
            {/* Glow */}
            <circle cx={tbx} cy={tby} r="14" fill={C.green} opacity={shake?0.35:0.15} style={{transition:"opacity 0.3s"}}/>
          </g>
        )}

        {/* GOL yazısı */}
        {shake && (
          <text x="100" y="15" textAnchor="middle" fontSize="18" fontWeight="900"
            fontFamily="'Baloo 2',sans-serif" fill={C.green}
            style={{filter:`drop-shadow(0 0 8px ${C.green})`, animation:"none"}}>
            GOL!
          </text>
        )}
      </svg>
    );
  }

  return (
    <div style={{position:"fixed",inset:0,background:"#000000f0",zIndex:600,display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
      <style>{`
        @keyframes goalBallIn {
          from { transform: scale(0.3) translateY(-30px); opacity: 0.4; }
          to   { transform: scale(1) translateY(0);  opacity: 1; }
        }
        @keyframes goalPlayerRun {
          from { transform: translateX(-60px); opacity: 0; }
          to   { transform: translateX(0);     opacity: 1; }
        }
        @keyframes goalFlash {
          0%,100% { background: #000000f0; }
          15%      { background: #00ff4422; }
          30%      { background: #000000f0; }
        }
      `}</style>

      <div className="pop" style={{
        background:`linear-gradient(160deg,#0a1a0a,#111,#0d0d0d)`,
        borderRadius:20, width:"100%", maxWidth:360,
        border:`2px solid ${C.green}66`,
        boxShadow:`0 0 40px ${C.green}44, 0 0 80px #000000cc`,
        overflow:"hidden"
      }}>
        {/* Başlık bandı */}
        <div style={{background:`linear-gradient(90deg,${C.green}22,${C.accent}22)`,padding:"12px 18px",borderBottom:`1px solid ${C.green}33`,textAlign:"center"}}>
          <div style={{fontFamily:"'Baloo 2',sans-serif",fontSize:26,fontWeight:900,color:C.green,
            textShadow:`0 0 20px ${C.green}`,letterSpacing:1,lineHeight:1}}>
            ⚽ G O L !
          </div>
          <div style={{fontSize:11,color:C.muted,marginTop:3,fontFamily:"'Fredoka',sans-serif",fontWeight:700,letterSpacing:0.3}}>
            {playerName.toUpperCase()} · {goalType.label.toUpperCase()}
          </div>
        </div>

        {/* 3D Sahne */}
        <div style={{position:"relative",padding:"16px 12px 8px",background:"#0a1a0a",display:"flex",flexDirection:"column",alignItems:"center",gap:0}}>

          {/* Saha zemini */}
          <div style={{position:"absolute",bottom:0,left:0,right:0,height:70,
            background:"linear-gradient(180deg,#0a2a0a00,#0a2a0a)",zIndex:0}}/>

          {/* Stat çizgileri dekoratif */}
          <div style={{position:"absolute",inset:0,backgroundImage:`repeating-linear-gradient(90deg,#ffffff04 0px,#ffffff04 1px,transparent 1px,transparent 40px)`,pointerEvents:"none"}}/>

          {/* Kale */}
          <div style={{position:"relative",zIndex:2}}>
            <GoalNet3D shake={netShake} ballX={goalType.ballX} ballY={goalType.ballY} showBall={showBall}/>
          </div>

          {/* Oyuncu */}
          <div style={{
            marginTop:-10, position:"relative", zIndex:3,
            animation: playerAnim==="run" ? "goalPlayerRun 0.4s ease forwards" : "none",
            transition:"transform 0.25s ease"
          }}>
            <FootballerSVG anim={playerAnim} shirtColor={C.accent}/>
          </div>

          {/* Efekt partiküller */}
          {netShake && Array.from({length:8},(_,i)=>(
            <div key={i} style={{
              position:"absolute",
              top:`${20+Math.random()*50}%`,
              left:`${10+Math.random()*80}%`,
              width: 6+Math.random()*6,
              height: 6+Math.random()*6,
              borderRadius:"50%",
              background:[C.green,C.gold,C.accent,"#ffffff"][i%4],
              opacity:0.8,
              animation:`conf ${0.6+Math.random()*0.8}s ease forwards`,
              pointerEvents:"none",zIndex:10
            }}/>
          ))}
        </div>

        {/* Alt bilgi */}
        <div style={{padding:"10px 18px 16px",textAlign:"center",borderTop:`1px solid #ffffff0a`}}>
          <div style={{fontSize:12,color:C.muted,fontFamily:"'Fredoka',sans-serif",marginBottom:12}}>
            {showButton ? `🔥 ${goalType.shotAngle} vuruşla ağlar havalandı!` : "🏃 Pozisyon kuruluyor..."}
          </div>
          <div style={{display:"flex",gap:8,justifyContent:"center",marginBottom:10}}>
            <Bdg c={C.green}>Gol {goals}</Bdg>
            <Bdg c={C.muted}>{goalType.label}</Bdg>
          </div>
          {showButton && (
            <Btn onClick={onClose} style={{width:"100%",fontSize:13}}>
              Devam ⚡
            </Btn>
          )}
        </div>
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════
//  MAÇ AKIŞ MOTORU
//  simMatch skoru önce belirliyor, istatistikleri sonra skora uydurarak
//  üretiyor — yani "simülasyon" aslında bir sonuç çekilişiydi. Olaylar da
//  karıştırılmış bir dakika listesine dağıtılıyordu: radardaki oyuncular
//  rastgele geziyor, momentum ±7 zar atıyordu.
//
//  buildMatchFlow, simMatch'in kararını KORUYARAK maçı dakika dakika
//  oynatır: top kimde, hangi bölgede, şut nereden, hangi xG ile. Skor ve
//  istatistik toplamları simMatch ile bire bir aynı kalır (kariyer motoru
//  ve 600k değişmez testi bozulmaz), ama sahada gördüğün her şey artık
//  bu yürüyüşten çıkar.
// ══════════════════════════════════════════════════════════════════
const ZONES=["DEF","MID","ATT"];
function buildMatchFlow(res,opts={}){
  const st=res.stats||{};
  const possPct=Math.max(20,Math.min(80,st.poss??50));
  const MIN=90;
  // ── 1) Top kimde: yapışkan Markov yürüyüşü ──
  // p(bizde kalır) ve p(onlarda kalır) topla sahip olma yüzdesini verir.
  const keepUs=0.62+(possPct-50)*0.006;
  const keepThem=0.62-(possPct-50)*0.006;
  const minutes=[];
  let poss=Math.random()*100<possPct?"us":"them";
  let zone=1;                                   // 0 DEF 1 MID 2 ATT (sahibin bakışıyla)
  for(let m=1;m<=MIN;m++){
    const keep=poss==="us"?keepUs:keepThem;
    if(Math.random()>keep){ poss=poss==="us"?"them":"us"; zone=0; }
    else {
      // bölge yürüyüşü: ileri gitmek geri gitmekten biraz daha zor
      const r=Math.random();
      if(r<0.34) zone=Math.min(2,zone+1);
      else if(r<0.60) zone=Math.max(0,zone-1);
    }
    minutes.push({m,poss,zone:ZONES[zone]});
  }
  // Gerçek sahip olma yüzdesi hedeften saparsa düzelt (uçlarda önemli)
  const usMin=minutes.filter(x=>x.poss==="us").length;
  const want=Math.round(MIN*possPct/100);
  if(Math.abs(usMin-want)>4){
    const from=usMin>want?"us":"them", to=usMin>want?"them":"us";
    let need=Math.abs(usMin-want);
    for(const x of minutes){ if(need<=0)break; if(x.poss===from&&x.zone!=="ATT"){x.poss=to;need--;} }
  }

  // ── 2) Şutlar: yalnızca hücum bölgesindeki sahipliklerden doğar ──
  const mkShots=(team,count,onTgt,goals,totalXg,myGoals)=>{
    const pool=minutes.filter(x=>x.poss===team&&x.zone==="ATT");
    const fallback=minutes.filter(x=>x.poss===team);
    const src=(pool.length>=count?pool:fallback.length?fallback:minutes).slice();
    // dakikaları tekrarsız seç
    const picked=[];
    for(let i=0;i<count&&src.length;i++) picked.push(src.splice(Math.floor(Math.random()*src.length),1)[0]);
    picked.sort((a,b)=>a.m-b.m);
    const shots=picked.map(x=>{
      // kalite: kaleye yakınlık ve açı → ham xG
      const central=Math.pow(Math.random(),0.7);          // 1 = tam merkez
      const dist=0.12+Math.pow(Math.random(),1.6)*0.88;   // 0 = kale ağzı
      const raw=Math.max(0.02,(1-dist)*0.55*(0.35+central*0.65));
      // saha koordinatı (0-100 uzunluk, 0-64 genişlik; hep sağa hücum)
      const px=52+(1-dist)*44;
      const py=32+(1-central)*26*(Math.random()<0.5?-1:1);
      return {m:x.m,team,x:+px.toFixed(1),y:+py.toFixed(1),raw,
              onTarget:false,goal:false,mine:false};
    });
    // xG toplamını simMatch'in değerine ölçekle
    const rawSum=shots.reduce((a,s)=>a+s.raw,0)||1;
    const k=(totalXg||0)/rawSum;
    shots.forEach(s=>{ s.xg=Math.max(0.01,Math.round(s.raw*k*100)/100); delete s.raw; });
    // isabetli şutlar: xG'si yüksek olanlar
    [...shots].sort((a,b)=>b.xg-a.xg).slice(0,onTgt).forEach(s=>{s.onTarget=true;});
    // goller: isabetliler arasından xG ağırlıklı seçim
    const onT=shots.filter(s=>s.onTarget);
    for(let g=0;g<goals&&onT.length;g++){
      const cand=onT.filter(s=>!s.goal);
      if(!cand.length)break;
      const tot=cand.reduce((a,s)=>a+s.xg,0)||1;
      let r=Math.random()*tot, hit=cand[cand.length-1];
      for(const s of cand){ r-=s.xg; if(r<=0){hit=s;break;} }
      hit.goal=true;
    }
    // oyuncunun kendi golleri
    if(myGoals>0){
      const mine=shots.filter(s=>s.goal).slice(0,myGoals);
      mine.forEach(s=>{s.mine=true;});
    }
    return shots;
  };
  const usShots=mkShots("us",st.shots||0,st.onTarget||0,res.teamScore||0,st.xg||0,res.goals||0);
  const themShots=mkShots("them",st.shotsOpp||0,st.onTargetOpp||0,res.oppScore||0,st.xgOpp||0,0);
  const shots=[...usShots,...themShots].sort((a,b)=>a.m-b.m);

  // ── 3) Dakika başına birikimli xG (canlı yarış grafiği için) ──
  let cu=0,ct=0;
  const xgRace=minutes.map(x=>{
    shots.filter(s=>s.m===x.m).forEach(s=>{ if(s.team==="us")cu+=s.xg; else ct+=s.xg; });
    return {m:x.m,us:+cu.toFixed(2),them:+ct.toFixed(2)};
  });

  const at=(min)=>minutes[Math.max(0,Math.min(MIN-1,Math.round(min)-1))];
  // Son 10 dakikanın sahiplik dengesi → momentum (-100..100)
  const momentumAt=(min)=>{
    const hi=Math.max(1,Math.min(MIN,Math.round(min)));
    const lo=Math.max(0,hi-10);
    const w=minutes.slice(lo,hi);
    if(!w.length) return 0;
    const share=w.filter(x=>x.poss==="us").length/w.length;
    const attBias=w.filter(x=>x.poss==="us"&&x.zone==="ATT").length*4
                 -w.filter(x=>x.poss==="them"&&x.zone==="ATT").length*4;
    return Math.max(-100,Math.min(100,Math.round((share-0.5)*150+attBias)));
  };
  return {minutes,shots,xgRace,at,momentumAt,
          possUs:Math.round(minutes.filter(x=>x.poss==="us").length/MIN*100)};
}

// Şut haritası — hangi golün nereden geldiği artık belli
function ShotMap({flow,clubColor,oppColor,height=170}){
  if(!flow||!flow.shots?.length) return null;
  const W=100,H=64;
  return(<div style={{position:"relative",borderRadius:R.md,overflow:"hidden",
    border:`1px solid ${C.border}`,background:"#0f2a18"}}>
    <svg viewBox={`0 0 ${W} ${H}`} style={{width:"100%",height,display:"block"}}>
      <rect width={W} height={H} fill="#14532d"/>
      {[0,1,2,3,4,5,6,7].map(i=>(<rect key={i} x={i*12.5} width="6.25" height={H} fill="#ffffff" opacity=".035"/>))}
      <g stroke="#ffffff" strokeOpacity=".3" strokeWidth=".5" fill="none">
        <rect x="1" y="1" width={W-2} height={H-2}/>
        <line x1={W/2} y1="1" x2={W/2} y2={H-1}/>
        <circle cx={W/2} cy={H/2} r="8"/>
        <rect x={W-17} y={H/2-15} width="16" height="30"/>
        <rect x={W-7} y={H/2-7} width="6" height="14"/>
        <rect x="1" y={H/2-15} width="16" height="30"/>
        <rect x="1" y={H/2-7} width="6" height="14"/>
      </g>
      {flow.shots.map((s,i)=>{
        const x=s.team==="us"?s.x:W-s.x, y=s.team==="us"?s.y:H-s.y;
        const col=s.team==="us"?(s.mine?"#fbbf24":clubColor||"#a3e635"):(oppColor||"#f87171");
        const r=1.4+Math.sqrt(s.xg)*3.4;
        return(<g key={i}>
          <circle cx={x} cy={y} r={r} fill={s.goal?col:"none"} stroke={col}
            strokeWidth={s.goal?.5:.8} opacity={s.goal?1:(s.onTarget?.85:.45)}/>
          {s.goal&&<circle cx={x} cy={y} r={r+1.8} fill="none" stroke={col} strokeWidth=".5" opacity=".6"/>}
        </g>);
      })}
    </svg>
  </div>);
}

