// Saha minimap SVG
// ══════════════════════════════════════════════════════════════════
//  CANLI 2D MAÇ RADARI
//  Sahada iki takımın 11'er oyuncusu ve top. Konumlar maçın gidişatına
//  (bölge + momentum) göre kayar, oyuncunun kendi noktası vurgulanır.
// ══════════════════════════════════════════════════════════════════
// 4-3-3 dizilişi — yatay saha (x: 0 kendi kalen → 100 rakip kale)
const RADAR_FORM=[
  {pos:"GK", x: 6, y:31},
  {pos:"RB", x:21, y:11}, {pos:"CB", x:18, y:24}, {pos:"CB", x:18, y:38}, {pos:"LB", x:21, y:51},
  {pos:"CDM",x:34, y:31}, {pos:"CM", x:39, y:18}, {pos:"CM", x:39, y:44},
  {pos:"RW", x:60, y: 9}, {pos:"ST", x:64, y:31}, {pos:"LW", x:60, y:53},
];
// Oyuncunun mevkisi dizilişte yoksa en yakın slotu ona çevir (CAM → CM)
function radarSlots(playerPos){
  const slots=RADAR_FORM.map(s=>({...s}));
  let idx=slots.findIndex(s=>s.pos===playerPos);
  if(idx<0){
    const target=SLOT_SWAP[playerPos]||"CM";
    idx=slots.findIndex(s=>s.pos===target);
    if(idx>=0) slots[idx]={...slots[idx],pos:playerPos};
  }
  return {slots,meIdx:idx<0?9:idx};
}

function LiveRadar({playerPos,zone,ballZone,momentum,clubColor,oppColor,height=178,tick}){
  const {slots,meIdx}=useRef(radarSlots(playerPos)).current;
  // Bölgeye göre hat kayması: hücumdayken blok öne, defanstayken geriye
  const push=zone==="ATK"?11:zone==="DEF"?-11:0;
  const mom=Math.max(-100,Math.min(100,momentum||0))*0.06;   // momentum ek kayma
  const shift=push+mom;
  // Ufak canlılık: her tick'te küçük rastgele salınım
  const jitter=useMemo(()=>slots.map(()=>({dx:(Math.random()-0.5)*3.4,dy:(Math.random()-0.5)*3.4})),[tick]);// eslint-disable-line react-hooks/exhaustive-deps
  const ball=ballZone==="ATK"?{x:78,y:26+Math.random()*10}
            :ballZone==="DEF"?{x:22,y:26+Math.random()*10}
            :{x:50,y:26+Math.random()*10};

  const W=100,H=62;
  return(
    <div style={{width:"100%",height,borderRadius:R.sm,overflow:"hidden",
      border:`1px solid ${C.border}`,background:"linear-gradient(170deg,#12401a,#0a2a10)"}}>
      <svg viewBox={`0 0 ${W} ${H}`} style={{width:"100%",height:"100%",display:"block"}}>
        {/* Çim şeritleri */}
        {[...Array(7)].map((_,i)=>(
          <rect key={i} x={(W/7)*i} y="0" width={W/7} height={H}
            fill={i%2?"#ffffff06":"transparent"}/>
        ))}
        {/* Saha çizgileri */}
        <rect x="1.5" y="1.5" width={W-3} height={H-3} fill="none" stroke="#ffffff33" strokeWidth="0.5"/>
        <line x1={W/2} y1="1.5" x2={W/2} y2={H-1.5} stroke="#ffffff33" strokeWidth="0.5"/>
        <circle cx={W/2} cy={H/2} r="8" fill="none" stroke="#ffffff33" strokeWidth="0.5"/>
        <circle cx={W/2} cy={H/2} r="0.8" fill="#ffffff44"/>
        {/* Ceza sahaları */}
        <rect x="1.5" y={H/2-13} width="13" height="26" fill="none" stroke="#ffffff2a" strokeWidth="0.5"/>
        <rect x={W-14.5} y={H/2-13} width="13" height="26" fill="none" stroke="#ffffff2a" strokeWidth="0.5"/>
        <rect x="1.5" y={H/2-6} width="5" height="12" fill="none" stroke="#ffffff2a" strokeWidth="0.4"/>
        <rect x={W-6.5} y={H/2-6} width="5" height="12" fill="none" stroke="#ffffff2a" strokeWidth="0.4"/>
        {/* Kaleler */}
        <rect x="0" y={H/2-4} width="1.5" height="8" fill="#ffffff55"/>
        <rect x={W-1.5} y={H/2-4} width="1.5" height="8" fill="#ffffff55"/>

        {/* RAKİP TAKIM (aynalanmış, ters yönde kayar) */}
        {slots.map((s,i)=>{
          const x=W-(s.x+shift*-1)+jitter[i].dx*0.6;
          const y=s.y+jitter[i].dy*0.6;
          // Beyaz kontur: rakip forması çim rengine yakın olsa da noktalar okunur kalır
          return <circle key={`o${i}`} cx={Math.max(3,Math.min(W-3,x))} cy={Math.max(3,Math.min(H-3,y))}
            r="1.9" fill={oppColor||"#dddddd"} stroke="#ffffff" strokeWidth="0.5" opacity="0.9"
            style={{transition:"cx .9s ease, cy .9s ease"}}/>;
        })}

        {/* BİZİM TAKIM */}
        {slots.map((s,i)=>{
          const isMe=i===meIdx;
          const x=s.x+shift+jitter[i].dx;
          const y=s.y+jitter[i].dy;
          const cx=Math.max(3,Math.min(W-3,x)), cy=Math.max(3,Math.min(H-3,y));
          return(<g key={`h${i}`} style={{transition:"transform .9s ease"}}>
            {isMe&&<circle cx={cx} cy={cy} r="4.2" fill="none" stroke={C.gold} strokeWidth="0.7" opacity="0.9">
              <animate attributeName="r" values="3.4;5;3.4" dur="1.8s" repeatCount="indefinite"/>
              <animate attributeName="opacity" values="0.9;0.25;0.9" dur="1.8s" repeatCount="indefinite"/>
            </circle>}
            <circle cx={cx} cy={cy} r={isMe?2.6:1.9}
              fill={isMe?C.gold:(clubColor||C.accent)}
              stroke={isMe?"#000":"#00000066"} strokeWidth={0.5}
              style={{transition:"cx .9s ease, cy .9s ease"}}/>
          </g>);
        })}

        {/* TOP */}
        <circle cx={ball.x} cy={ball.y} r="1.5" fill="#ffffff"
          style={{transition:"cx .7s ease, cy .7s ease"}}>
          <animate attributeName="r" values="1.3;1.8;1.3" dur="1.1s" repeatCount="indefinite"/>
        </circle>
      </svg>
    </div>
  );
}

