// ══════════ CL MODAL ══════════
// ══════════════════════════════════════════════════════════════════
//  AVRUPA KUPALARI — tek ortak motor
//  Şampiyonlar Ligi / Avrupa Ligi / Konferans Ligi aynı bileşeni kullanır.
//  Akış: Kura → Grup (6 maç, ev+deplasman) → Grup tablosu → Eleme → Final → Kupa
//  Oyuncunun kulübü HER ZAMAN gruptadır (eski sürümde grup havuzunda yoktu).
// ══════════════════════════════════════════════════════════════════
const EURO_CUPS={
  cl:  {name:"Şampiyonlar Ligi", short:"ŞL",  icon:"🏆", color:"#facc15", minP:7, maxP:10, koStages:["Son 16","Çeyrek Final","Yarı Final","Final"], prize:120},
  el:  {name:"Avrupa Ligi",      short:"AL",  icon:"🥈", color:"#fb923c", minP:5, maxP:8,  koStages:["Son 16","Çeyrek Final","Yarı Final","Final"], prize:60},
  conf:{name:"Konferans Ligi",   short:"KL",  icon:"🥉", color:"#4ade80", minP:2, maxP:6,  koStages:["Çeyrek Final","Yarı Final","Final"],          prize:30},
};

// Oyuncunun kulübü + gücüne yakın 3 rakipten grup kur
function buildEuroGroup(cup,myClub){
  const pool=CLUBS.filter(c=>c.name!==myClub.name&&c.prestige>=cup.minP&&c.prestige<=cup.maxP);
  const picked=pool.sort(()=>Math.random()-.5).slice(0,3);
  // Havuz yetersizse prestij şartını gevşet
  while(picked.length<3){
    const extra=pick(CLUBS.filter(c=>c.name!==myClub.name&&!picked.some(x=>x.name===c.name)));
    if(!extra)break;
    picked.push(extra);
  }
  return [myClub,...picked];
}
// Grup fikstürü: her rakiple ev + deplasman = 6 maç
function buildEuroFixtures(group,myName){
  const rows=[];
  group.forEach(a=>group.forEach(b=>{ if(a.name!==b.name) rows.push({home:a.name,away:b.name}); }));
  // Oyuncunun maçları öne alınsın ki sırayla oynasın
  const mine=rows.filter(r=>r.home===myName||r.away===myName);
  const rest=rows.filter(r=>r.home!==myName&&r.away!==myName);
  return {mine,rest};
}
const emptyRow=n=>({name:n,p:0,w:0,d:0,l:0,gf:0,ga:0,gd:0,pts:0});

// Kupa maçları sezona YAYILIR. Eskiden grup + eleme + final tek oturumda
// bitiyordu; lig 8. haftadayken Şampiyonlar Ligi'ni kazanıyordun.
function euroSchedule(cup,seasonWeeks){
  const group=[0.09,0.17,0.25,0.32,0.40,0.47].map(p=>Math.max(2,Math.round(seasonWeeks*p)));
  const n=cup.koStages.length;
  const ko=[];
  for(let i=0;i<n;i++){
    const p=0.58+(0.94-0.58)*(n===1?0.5:i/(n-1));
    ko.push(Math.round(seasonWeeks*p));
  }
  return {group,ko};
}
// Kupa durumunu sıfırdan kurar (sezon başında bir kez)
function startEuroCup(cupId,myClub,seasonWeeks){
  const cup=EURO_CUPS[cupId];
  if(!cup)return null;
  const group=buildEuroGroup(cup,myClub);
  const fx=buildEuroFixtures(group,myClub.name);
  const pool=CLUBS.filter(c=>c.name!==myClub.name&&c.prestige>=cup.minP);
  return {
    cupId,
    groupNames:group.map(g=>g.name),
    fxMine:fx.mine, fxRest:fx.rest,
    table:group.map(g=>emptyRow(g.name)),
    stage:"group",            // group | ko | done
    gIdx:0, koIdx:0,
    koOpps:cup.koStages.map(()=>pick(pool)?.name||"Rakip"),
    log:[], totals:{goals:0,assists:0,matches:0},
    eliminated:false, won:false,
    sched:euroSchedule(cup,seasonWeeks),
  };
}
// Bu hafta kupa maçı var mı?
function euroMatchDue(ec,week){
  if(!ec||ec.stage==="done")return false;
  if(ec.stage==="group") return week>=(ec.sched.group[ec.gIdx]??999);
  if(ec.stage==="ko")    return week>=(ec.sched.ko[ec.koIdx]??999);
  return false;
}
const applyEuroRow=(rows,name,gf,ga)=>rows.map(r=>{
  if(r.name!==name)return r;
  const w=gf>ga,d=gf===ga;
  const nr={...r,p:r.p+1,w:r.w+(w?1:0),d:r.d+(d?1:0),l:r.l+(!w&&!d?1:0),
    pts:r.pts+(w?3:d?1:0),gf:r.gf+gf,ga:r.ga+ga};
  nr.gd=nr.gf-nr.ga; return nr;
});

