// AV_SKIN / AV_HAIR / AV_HAIR_STYLE / AV_EXPRESSION / AV_TATTOO tabloları
// oyunda tanımlıydı ama hiçbir yerde kullanılmıyordu — burada gerçek bir
// avatara dönüştürülüyor.
const DEFAULT_AVATAR={skin:1,hair:0,hairStyle:0,expr:1,tattoo:0,beard:0};
const AV_BEARD=[{id:0,name:"Yok"},{id:1,name:"Sakal"},{id:2,name:"Keçi"},{id:3,name:"Bıyık"}];

function PlayerAvatar({avatar,size=88,kit,ring}){
  const a={...DEFAULT_AVATAR,...(avatar||{})};
  const skin=AV_SKIN[a.skin]||AV_SKIN[1];
  const hair=AV_HAIR[a.hair]||AV_HAIR[0];
  const expr=AV_EXPRESSION[a.expr]||AV_EXPRESSION[1];
  const style=a.hairStyle??0;
  const tat=AV_TATTOO[a.tattoo]||AV_TATTOO[0];
  const shirt=kit||C.accent;
  return(
    <svg viewBox="0 0 100 112" width={size} height={size*1.12} style={{display:"block",flexShrink:0}}>
      <defs>
        <clipPath id={`hd${a.skin}${a.hair}${style}`}><ellipse cx="50" cy="60" rx="21" ry="25"/></clipPath>
      </defs>
      {ring&&<circle cx="50" cy="56" r="46" fill="none" stroke={ring} strokeWidth="2" opacity="0.5"/>}
      {/* omuz + forma */}
      <path d="M22,112 Q22,92 38,86 L62,86 Q78,92 78,112 Z" fill={shirt}/>
      <path d="M44,86 Q50,94 56,86 L56,86 Q50,90 44,86 Z" fill={skin.shadow}/>
      {/* boyun */}
      <rect x="44" y="76" width="12" height="14" rx="5" fill={skin.shadow}/>
      {/* kafa */}
      <ellipse cx="50" cy="60" rx="21" ry="25" fill={skin.color}/>
      {/* kulaklar */}
      <ellipse cx="28" cy="62" rx="4" ry="6" fill={skin.color}/>
      <ellipse cx="72" cy="62" rx="4" ry="6" fill={skin.color}/>
      {/* saç — stile göre */}
      <g clipPath={`url(#hd${a.skin}${a.hair}${style})`}>
        {style===3
          ? <ellipse cx="50" cy="44" rx="21" ry="14" fill={hair.color} opacity="0.55"/>
          : style===4
          ? <circle cx="50" cy="40" r="24" fill={hair.color}/>
          : style===2
          ? <path d="M29,58 Q28,34 50,34 Q72,34 71,58 L71,46 Q50,40 29,46 Z" fill={hair.color}/>
          : style===1
          ? <path d="M29,52 Q30,35 50,35 Q70,35 71,52 Q60,43 50,45 Q40,43 29,52 Z" fill={hair.color}/>
          : <path d="M30,50 Q32,36 50,36 Q68,36 70,50 Q58,44 50,46 Q42,44 30,50 Z" fill={hair.color}/>}
      </g>
      {style===2&&<><path d="M29,56 Q26,72 30,80 L34,78 Q31,68 32,58 Z" fill={hair.color}/>
        <path d="M71,56 Q74,72 70,80 L66,78 Q69,68 68,58 Z" fill={hair.color}/></>}
      {/* kaşlar */}
      <path d="M39,56 Q44,53 48,55" stroke={hair.color} strokeWidth="2" fill="none" strokeLinecap="round"/>
      <path d="M52,55 Q56,53 61,56" stroke={hair.color} strokeWidth="2" fill="none" strokeLinecap="round"/>
      {/* gözler + ağız (ifade tablosundan) */}
      <path d={expr.eyeL} stroke="#1a1a1a" strokeWidth="2.4" fill="none" strokeLinecap="round"/>
      <path d={expr.eyeR} stroke="#1a1a1a" strokeWidth="2.4" fill="none" strokeLinecap="round"/>
      <path d={expr.mouth} stroke="#7a3a30" strokeWidth="2.2" fill="none" strokeLinecap="round"/>
      {/* burun */}
      <path d="M50,63 L48,69 Q50,70 52,69" stroke={skin.shadow} strokeWidth="1.6" fill="none" strokeLinecap="round"/>
      {/* sakal */}
      {a.beard===1&&<path d="M32,66 Q34,86 50,88 Q66,86 68,66 Q60,80 50,80 Q40,80 32,66 Z" fill={hair.color} opacity="0.75"/>}
      {a.beard===2&&<ellipse cx="50" cy="78" rx="7" ry="6" fill={hair.color} opacity="0.8"/>}
      {a.beard===3&&<path d="M43,71 Q50,69 57,71 Q50,74 43,71 Z" fill={hair.color} opacity="0.85"/>}
      {/* dövme (boyunda) */}
      {a.tattoo>0&&<text x="68" y="92" fontSize="11" textAnchor="middle">{tat.icon}</text>}
    </svg>
  );
}

// Avatar düzenleyici — karakter oluşturmada kullanılır
function AvatarEditor({avatar,onChange,kit}){
  const a={...DEFAULT_AVATAR,...(avatar||{})};
  const set=(k,v)=>onChange({...a,[k]:v});
  const cycle=(k,len,dir)=>set(k,((a[k]+dir)%len+len)%len);
  const Row=({label,k,list,render})=>(
    <div style={{marginBottom:9}}>
      <div style={{display:"flex",alignItems:"center",gap:8}}>
        <span style={{fontSize:9,color:C.muted,letterSpacing:0.3,width:58,fontFamily:"'Fredoka',sans-serif",fontWeight:700,textTransform:"uppercase"}}>{label}</span>
        <button onClick={()=>cycle(k,list.length,-1)} style={{width:26,height:26,borderRadius:7,border:`1px solid ${C.border}`,background:C.card2,color:C.text,cursor:"pointer",fontSize:13}}>‹</button>
        <div style={{flex:1,display:"flex",gap:4,justifyContent:"center",flexWrap:"wrap"}}>
          {list.map((it,i)=>(
            <button key={i} onClick={()=>set(k,i)} title={it.name}
              style={{width:22,height:22,borderRadius:6,cursor:"pointer",
                border:`2px solid ${a[k]===i?C.accent:C.border}`,
                background:render?render(it):C.card2,
                color:C.text,fontSize:9,padding:0,display:"flex",alignItems:"center",justifyContent:"center"}}>
              {render?"":i+1}
            </button>))}
        </div>
        <button onClick={()=>cycle(k,list.length,1)} style={{width:26,height:26,borderRadius:7,border:`1px solid ${C.border}`,background:C.card2,color:C.text,cursor:"pointer",fontSize:13}}>›</button>
      </div>
    </div>
  );
  return(
    <div style={{background:C.card,borderRadius:14,padding:14,border:`1px solid ${C.border}`}}>
      <div style={{display:"flex",gap:14,alignItems:"center",marginBottom:12}}>
        <div style={{background:C.bg,borderRadius:12,padding:6}}>
          <PlayerAvatar avatar={a} size={78} kit={kit}/>
        </div>
        <div style={{flex:1,fontSize:10,color:C.muted,lineHeight:1.7}}>
          <div style={{fontSize:10,color:C.accent,letterSpacing:0.3,fontWeight:700,marginBottom:4,fontFamily:"'Fredoka',sans-serif"}}>GÖRÜNÜŞÜN</div>
          {AV_SKIN[a.skin]?.name} ten · {AV_HAIR[a.hair]?.name} saç<br/>
          {AV_HAIR_STYLE[a.hairStyle]?.name} · {AV_EXPRESSION[a.expr]?.name}<br/>
          {AV_BEARD[a.beard]?.name} · {AV_TATTOO[a.tattoo]?.name} dövme
        </div>
      </div>
      <Row label="Ten"    k="skin"      list={AV_SKIN}       render={it=>it.color}/>
      <Row label="Saç"    k="hair"      list={AV_HAIR}       render={it=>it.color}/>
      <Row label="Kesim"  k="hairStyle" list={AV_HAIR_STYLE}/>
      <Row label="İfade"  k="expr"      list={AV_EXPRESSION}/>
      <Row label="Sakal"  k="beard"     list={AV_BEARD}/>
      <Row label="Dövme"  k="tattoo"    list={AV_TATTOO}/>
      <button onClick={()=>onChange({
        skin:rand(0,AV_SKIN.length-1),hair:rand(0,AV_HAIR.length-1),
        hairStyle:rand(0,AV_HAIR_STYLE.length-1),expr:rand(0,AV_EXPRESSION.length-1),
        beard:rand(0,AV_BEARD.length-1),tattoo:rand(0,AV_TATTOO.length-1)})}
        style={{width:"100%",marginTop:6,padding:"8px",borderRadius:8,border:`1px solid ${C.border}`,
          background:C.card2,color:C.muted,cursor:"pointer",fontSize:11,fontFamily:"'Fredoka',sans-serif",fontWeight:700}}>
        🎲 Rastgele
      </button>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════
//  GAZETE MANŞETİ — maç sonrası performansa göre ön sayfa
// ══════════════════════════════════════════════════════════════════
const PAPERS=["SPOR GÜNDEM","GOL DERGİSİ","SAHA HABER","FUTBOL POSTASI","90 DAKİKA"];
function mkHeadline(r,player,club){
  const n=(player.name||"").toUpperCase();
  const surname=(player.name||"").split(" ").slice(-1)[0].toUpperCase();
  const sc=`${r.teamScore}-${r.oppScore}`;
  const opp=r.oppName||"rakip";
  // En iyi eşleşen manşeti seç
  if(r.goals>=3) return {tone:"epic",
    head:`${surname} YIKTI GEÇTİ: HAT-TRICK!`,
    sub:`${club.name} ${sc} ${opp} · ${n} tek başına maçı kopardı.`};
  if(r.goals===2&&r.won) return {tone:"good",
    head:`${surname}'DAN ÇİFTE DARBE`,
    sub:`${club.name} ${sc} kazandı. İki gol de ondan geldi.`};
  if(r.motm) return {tone:"good",
    head:`MAÇIN ADAMI: ${surname}`,
    sub:`${sc} biten maçta ${r.rating} reytingle sahanın en iyisiydi.`};
  if(r.goals>=1&&r.won) return {tone:"good",
    head:`${surname} FARKI`,
    sub:`${club.name} ${sc} kazandı, golü ${n} attı.`};
  if(r.assists>=2) return {tone:"good",
    head:`${surname} DAĞITTI`,
    sub:`${r.assists} asistle takımını taşıdı. Skor ${sc}.`};
  if(r.red) return {tone:"bad",
    head:`KIRMIZI KART FELAKETİ`,
    sub:`${n} oyundan atıldı. ${club.name} ${sc}.`};
  if(r.rating<5.5&&!r.won) return {tone:"bad",
    head:`${surname} KAYBOLDU`,
    sub:`${r.rating} reyting. Taraftar tepkili, skor ${sc}.`};
  if(!r.won&&!r.draw&&r.oppScore-r.teamScore>=3) return {tone:"bad",
    head:`AĞIR FATURA: ${sc}`,
    sub:`${club.name} ${opp} deplasmanında dağıldı.`};
  if(r.cleanSheet&&DEF_POS.includes(player.pos)) return {tone:"good",
    head:`KALE KAPANDI`,
    sub:`${club.name} gol yemedi. ${n} savunmanın direği oldu.`};
  if(r.draw) return {tone:"neutral",
    head:`PUANLAR PAYLAŞILDI`,
    sub:`${club.name} ${sc} ${opp}. ${n} ${r.rating} aldı.`};
  if(r.won) return {tone:"good",
    head:`ÜÇ PUAN CEPTE`,
    sub:`${club.name} ${sc} kazandı. ${n} ${r.rating} reyting.`};
  return {tone:"bad",
    head:`${club.name.toUpperCase()} YİNE KAYBETTİ`,
    sub:`${sc} · ${n} ${r.rating} reytingle yetersiz kaldı.`};
}
// ── GAZETE GÖVDESİ: gerçek maç raporu üretir ──
// Eskiden manşetin altında sadece dekoratif gri çizgiler vardı.
function mkPaperBody(r,player,club,extra={}){
  const n=player.name, opp=r.oppName||"rakip", sc=`${r.teamScore}-${r.oppScore}`;
  const venue=r.isHome===false?"deplasmanda":"kendi sahasında";
  const res=r.won?"kazandı":r.draw?"berabere kaldı":"kaybetti";
  const paras=[];
  paras.push(`${club.name}, ${venue} ${opp} ile karşılaştığı mücadeleyi ${sc} ${res}. `+
    `${n}, ${r.minutes??90} dakika sahada kaldı ve ${r.rating} reyting aldı.`);
  if(r.goals>0) paras.push(
    r.goals>=3?`${n} hat-trick yaptı. ${r.goals} golle maçın tek konusu oldu ve tribünler ayakta alkışladı.`
    :r.goals===2?`${n} iki gol kaydetti. Özellikle ikinci golündeki soğukkanlılığı dikkat çekti.`
    :`${n} skoru bulan isimlerden biri oldu.`);
  if(r.assists>0) paras.push(`${r.assists} asistiyle de takımın hücum üretiminde başrolü üstlendi.`);
  if(r.goals===0&&r.assists===0&&r.rating<6.2) paras.push(
    `${n} adına verimsiz bir akşamdı. Kaptığı topları koruyamadı, ceza sahasında etkisiz kaldı.`);
  if(r.red) paras.push(`${n} gördüğü kırmızı kartla takımını 10 kişi bıraktı. Disiplin kurulu süreci başlıyor.`);
  else if(r.yellow) paras.push(`${n} sarı kart gördü; kart cezası sınırına yaklaşıyor.`);
  if(r.cleanSheet&&DEF_POS.includes(player.pos)) paras.push(
    `Savunma hattı gol yemedi. ${n}'in pozisyon alışı maçın sessiz kahramanıydı.`);
  if(r.stats) paras.push(`Topla oynama ${r.stats.poss}%-${r.stats.possOpp}%, `+
    `şut ${r.stats.shots}-${r.stats.shotsOpp}, beklenen gol ${r.stats.xg}-${r.stats.xgOpp}.`);
  if(extra.leaguePos) paras.push(`${club.name} bu sonuçla ligde ${extra.leaguePos}. sırada yer alıyor.`);
  const quotes=r.won
    ? [`"Oyuncularımın karakterine güvendim."`,`"Bu galibiyeti taraftarımıza armağan ediyoruz."`,`"${n} bugün farkı yarattı."`]
    : r.draw
    ? [`"Bir puan aldık ama daha iyisini yapabilirdik."`,`"Eksiklerimizi biliyoruz, çalışacağız."`]
    : [`"Sorumluluk bende."`,`"Bu skor bizi yansıtmıyor."`,`"Toparlanmak için zamanımız var."`];
  return {paras:paras.slice(0,5),quote:pick(quotes),
    facts:[["Skor",sc],["Reyting",String(r.rating)],["Gol",String(r.goals)],
           ["Asist",String(r.assists)],["Dakika",String(r.minutes??90)]]};
}
