const CARD_TIERS=[
  {id:"bronze", min:0,  name:"BRONZ",  bg:["#c9773a","#7a3f14"], edge:"#ffb067", text:"#fff4e6", glow:"#ffb06755"},
  {id:"silver", min:65, name:"GÜMÜŞ",  bg:["#9fb4c9","#4b6076"], edge:"#e6f1ff", text:"#ffffff", glow:"#e6f1ff55"},
  {id:"gold",   min:75, name:"ALTIN",  bg:["#ffcf49","#b3790a"], edge:"#fff0a8", text:"#3a2a00", glow:"#ffd23f66"},
  {id:"elite",  min:85, name:"ELİT",   bg:["#3aa0ff","#12407e"], edge:"#9fdcff", text:"#ffffff", glow:"#37c6ff66"},
  {id:"icon",   min:92, name:"EFSANE", bg:["#c56cff","#5c1e96"], edge:"#f0c8ff", text:"#ffffff", glow:"#b06cff77"},
];
const cardTier=ovr=>[...CARD_TIERS].reverse().find(t=>ovr>=t.min)||CARD_TIERS[0];

