// ── RADAR / POLİGON YETENEK GRAFİĞİ ──
function StatRadar({player,size=210,color=C.accent}){
  const axes=[
    {k:"pace",      l:"HIZ"},
    {k:"shooting",  l:"ŞUT"},
    {k:"passing",   l:"PAS"},
    {k:"dribbling", l:"DRP"},
    {k:"defending", l:"DEF"},
    {k:"physical",  l:"FİZ"},
  ];
  const cx=size/2, cy=size/2, R=size*0.34;
  const pt=(i,r)=>{
    const a=(Math.PI*2*i)/axes.length - Math.PI/2;
    return [cx+Math.cos(a)*r, cy+Math.sin(a)*r];
  };
  const poly=axes.map((ax,i)=>pt(i,(player[ax.k]/99)*R).join(",")).join(" ");
  const rings=[0.25,0.5,0.75,1];
  return(
    <svg viewBox={`0 0 ${size} ${size}`} width="100%" style={{display:"block",maxWidth:size}}>
      {/* Halkalar */}
      {rings.map(f=>(
        <polygon key={f} points={axes.map((_,i)=>pt(i,R*f).join(",")).join(" ")}
          fill="none" stroke={C.border} strokeWidth="1" opacity={f===1?0.85:0.4}/>
      ))}
      {/* Eksenler */}
      {axes.map((_,i)=>{
        const [x,y]=pt(i,R);
        return <line key={i} x1={cx} y1={cy} x2={x} y2={y} stroke={C.border} strokeWidth="1" opacity="0.5"/>;
      })}
      {/* Değer alanı */}
      <polygon points={poly} fill={`${color}33`} stroke={color} strokeWidth="2" strokeLinejoin="round"/>
      {/* Noktalar */}
      {axes.map((ax,i)=>{
        const [x,y]=pt(i,(player[ax.k]/99)*R);
        return <circle key={ax.k} cx={x} cy={y} r="3" fill={color}/>;
      })}
      {/* Etiketler */}
      {axes.map((ax,i)=>{
        const [x,y]=pt(i,R*1.30);
        return(<g key={ax.l}>
          <text x={x} y={y-3} textAnchor="middle" fontSize={size*0.05} fill={C.muted}
            fontFamily="'Fredoka',sans-serif" fontWeight="700" letterSpacing="1">{ax.l}</text>
          <text x={x} y={y+size*0.055} textAnchor="middle" fontSize={size*0.058} fill={tone(player[ax.k])}
            fontFamily="'Baloo 2',sans-serif" fontWeight="900">{player[ax.k]}</text>
        </g>);
      })}
    </svg>
  );
}

// ── MAÇ ISI HARİTASI ──
// Oyuncunun mevkisine ve maçtaki olaylarına göre sahada nerede top ile
// buluştuğunu gösterir.
const ZONE_BIAS={
  GK: [0.00,0.06,0.92], CB:[0.05,0.20,0.75], LB:[0.10,0.30,0.60], RB:[0.10,0.30,0.60],
  CDM:[0.12,0.55,0.33], CM:[0.25,0.55,0.20], CAM:[0.50,0.42,0.08],
  LW:[0.60,0.34,0.06],  RW:[0.60,0.34,0.06], ST:[0.72,0.24,0.04],
};
function buildHeat(pos,events){
  const bias=ZONE_BIAS[pos]||ZONE_BIAS.CM;      // [ATK, MID, DEF]
  const cols=5, rows=7;                          // 35 hücre (dikey saha)
  const grid=Array.from({length:rows},()=>Array(cols).fill(0));
  const total=260;
  for(let i=0;i<total;i++){
    const r=Math.random();
    const band=r<bias[0]?0:r<bias[0]+bias[1]?1:2;   // 0=hücum 1=orta 2=defans
    const rowRange=band===0?[0,2]:band===1?[2,5]:[4,6];
    const row=rand(rowRange[0],rowRange[1]);
    // Kanat oyuncuları kenarlara, stoperler ortaya yığılır
    let col;
    if(pos==="LW"||pos==="LB") col=Math.random()<0.68?rand(0,1):rand(2,4);
    else if(pos==="RW"||pos==="RB") col=Math.random()<0.68?rand(3,4):rand(0,2);
    else col=Math.random()<0.62?rand(1,3):rand(0,4);
    grid[row][col]++;
  }
  // Maç olayları sıcak noktaları güçlendirir
  (events||[]).forEach(e=>{
    if(e.type==="goal"){grid[rand(0,1)][rand(1,3)]+=26;}
    else if(e.type==="assist"){grid[rand(1,2)][rand(0,4)]+=16;}
    else if(e.type==="save"||e.type==="opp_goal"){grid[rand(5,6)][rand(1,3)]+=18;}
  });
  const max=Math.max(...grid.flat(),1);
  return grid.map(r=>r.map(v=>v/max));
}
function Heatmap({pos,events,height=170}){
  const grid=useRef(buildHeat(pos,events)).current;
  return(
    <div style={{position:"relative",width:"100%",height,borderRadius:R.sm,overflow:"hidden",
      background:"linear-gradient(180deg,#0d2a12,#08200d)",border:`1px solid ${C.border}`}}>
      {/* Saha çizgileri */}
      <div style={{position:"absolute",inset:0,pointerEvents:"none",zIndex:2}}>
        <div style={{position:"absolute",top:"50%",left:"4%",right:"4%",height:1,background:"#ffffff22"}}/>
        <div style={{position:"absolute",top:"38%",bottom:"38%",left:"33%",right:"33%",
          border:"1px solid #ffffff1a",borderRadius:"50%"}}/>
        <div style={{position:"absolute",top:0,left:"22%",right:"22%",height:"14%",borderBottom:"1px solid #ffffff1a",
          borderLeft:"1px solid #ffffff1a",borderRight:"1px solid #ffffff1a"}}/>
        <div style={{position:"absolute",bottom:0,left:"22%",right:"22%",height:"14%",borderTop:"1px solid #ffffff1a",
          borderLeft:"1px solid #ffffff1a",borderRight:"1px solid #ffffff1a"}}/>
      </div>
      {/* Isı hücreleri */}
      <div style={{position:"absolute",inset:0,display:"grid",
        gridTemplateRows:`repeat(${grid.length},1fr)`,gridTemplateColumns:`repeat(${grid[0].length},1fr)`}}>
        {grid.flatMap((row,ri)=>row.map((v,ci)=>{
          const a=Math.pow(v,0.75);
          const col=a<0.28?`rgba(56,189,248,${a*0.5})`
                   :a<0.55?`rgba(74,222,128,${a*0.6})`
                   :a<0.78?`rgba(250,204,21,${a*0.7})`
                          :`rgba(248,113,113,${a*0.85})`;
          return <div key={`${ri}-${ci}`} style={{background:col,filter:"blur(7px)"}}/>;
        }))}
      </div>
      <div style={{position:"absolute",top:5,left:8,fontSize:8,color:"#ffffff66",
        letterSpacing:0.3,fontFamily:F.cond,fontWeight:700,zIndex:3}}>HÜCUM ↑</div>
      <div style={{position:"absolute",bottom:5,left:8,fontSize:8,color:"#ffffff66",
        letterSpacing:0.3,fontFamily:F.cond,fontWeight:700,zIndex:3}}>DEFANS ↓</div>
    </div>
  );
}

