function getTaxRate(salary){
  // Türkiye vergi dilimleri (k/haftalık maaşa göre basitleştirilmiş)
  if(salary<20)return 0.15;
  if(salary<50)return 0.25;
  if(salary<100)return 0.35;
  return 0.45;
}

