const NAT_TO_COUNTRY={
  "Türk":"Türkiye","Brezilyalı":"Brezilya","Arjantinli":"Arjantin","Fransız":"Fransa","Alman":"Almanya",
  "İspanyol":"İspanya","Portekizli":"Portekiz","Hollandalı":"Hollanda","İtalyan":"İtalya","Belçikalı":"Belçika",
  "İngiliz":"İngiltere","İskoç":"İskoçya","İrlandalı":"İrlanda","Hırvat":"Hırvatistan","İsveçli":"İsveç",
  "Danimarkalı":"Danimarka","Norveçli":"Norveç","Polonyalı":"Polonya","Çek":"Çekya","Sırp":"Sırbistan",
  "Ukraynalı":"Ukrayna","Rus":"Rusya","Faslı":"Fas","Senegalli":"Senegal","Fildişili":"Fildişi Sahili",
  "Ganalı":"Gana","Nijeryalı":"Nijerya","Kamerunlu":"Kamerun","Amerikalı":"ABD","Meksikalı":"Meksika",
  "Şilili":"Şili","Kolombiyalı":"Kolombiya","Uruguaylı":"Uruguay","Japon":"Japonya","Güney Koreli":"Kore Cumhuriyeti",
  "Avustralyalı":"Avustralya","Yunan":"Yunanistan","Avusturyalı":"Avusturya","İsviçreli":"İsviçre","Romen":"Romanya",
  "Bulgar":"Bulgaristan","İzlandalı":"İzlanda","Arnavut":"Arnavutluk","Boşnak":"Bosna-Hersek","İranlı":"İran",
  "Suudi":"Suudi Arabistan","Ekvadorlu":"Ekvador","Perulu":"Peru","Venezuelalı":"Venezuela","Malili":"Mali",
};
// "🇹🇷 Türk" → "Türkiye"
const natCountry=nat=>{
  const word=String(nat||"").split(" ").slice(1).join(" ").trim();
  return NAT_TO_COUNTRY[word]||word||"Türkiye";
};

