// ── PANEL (mockup'lardaki başlıklı kutu) ──
function Panel({title,right,children,style={},bodyStyle={},glow,gc}){
  const g=gc||C.accent;
  return(<div style={{position:"relative",display:"flex",flexDirection:"column",minHeight:0,
    background:`linear-gradient(168deg, ${C.card2}ee 0%, ${C.card}ea 42%, ${C.card}f2 100%)`,
    backdropFilter:"blur(10px)",
    border:`1px solid ${glow?g+"88":C.border}`,borderRadius:R.lg,
    boxShadow:glow
      ? `inset 0 1px 0 #ffffff14, 0 2px 4px #00000030, 0 18px 44px #00000075, 0 0 26px ${g}26`
      : "inset 0 1px 0 #ffffff10, 0 2px 4px #00000030, 0 16px 38px #00000070",
    overflow:"hidden",...style}}>
    {/* film greni — düz kutu hissini kıran doku */}
    <span aria-hidden style={{position:"absolute",inset:0,pointerEvents:"none",zIndex:0,
      backgroundImage:`url("${GRAIN}")`,backgroundSize:"140px 140px",
      opacity:.05,mixBlendMode:"overlay"}}/>
    {title&&<div style={{position:"relative",zIndex:1,display:"flex",alignItems:"center",gap:9,
      padding:"11px 14px",borderBottom:`1px solid ${C.border}`,flexShrink:0,
      background:`linear-gradient(180deg, ${C.bg}88, ${C.bg}40)`}}>
      <span aria-hidden style={{width:3,height:15,borderRadius:2,flexShrink:0,
        background:`linear-gradient(180deg,${g},${g}44)`,boxShadow:`0 0 10px ${g}66`}}/>
      <span style={{fontFamily:F.disp,fontStyle:"italic",fontWeight:700,fontSize:15,
        letterSpacing:.6,textTransform:"uppercase"}}>{title}</span>
      {right&&<div style={{marginLeft:"auto",display:"flex",alignItems:"center",gap:7}}>{right}</div>}
    </div>}
    <div style={{position:"relative",zIndex:1,padding:"13px 14px",overflowY:"auto",
      minHeight:0,flex:1,...bodyStyle}}>{children}</div>
  </div>);
}

