  function checkAch(p,cl){
    const news=ACHIEVEMENTS.filter(a=>!p.achievements.includes(a.id)&&a.check(p,cl));
    if(news.length){setPendingAch(n=>[...n,...news]);return{...p,achievements:[...p.achievements,...news.map(a=>a.id)]};}
    return p;
  }

  function rollWeeklyEvent(p){
    const roll=Math.random();
    let cum=0;
    for(const ev of WEEKLY_EVENTS){
      cum+=ev.prob;
      if(roll<cum){setWeeklyEvent(ev);return;}
    }
    // viral event chance 7%
    if(Math.random()<.07){setViralEvent(pick(VIRAL_EVENTS));return;}
    // personal event chance 8%
    if(Math.random()<.08&&!p._hasFamily){setPersonalEvent(pick(PERSONAL_EVENTS));return;}
    // extra life events 6%
    if(Math.random()<.06){setPersonalEvent(pick(PERSONAL_EVENTS.slice(3)));return;}
    // coach dialogue 15% (every ~7 weeks)
    if(Math.random()<.15){
      const avgR=p.formHistory?.length?(p.formHistory.slice(-3).reduce((a,b)=>a+b,0)/Math.min(3,p.formHistory.length)):6;
      const eligible=COACH_DIALOGUES.filter(d=>avgR>=d.minRating||d.minRating===0);
      const dialogue=pick(eligible);
      setCoachDialogue(dialogue);return;
    }
    // rival weekly simulation — her hafta rakip de "oynuyor"
    setRival(r=>{
      if(!r)return r;
      // injury check
      if(r.injured){
        const iw=Math.max(0,r.injuredWeeks-1);
        return{...r,injuredWeeks:iw,injured:iw>0};
      }
      // new injury chance 6%
      if(Math.random()<.06){
        const iw=rand(1,3);
        return{...r,injured:true,injuredWeeks:iw};
      }
      // simulate rival match
      const rWon=Math.random()>.42,rDraw=!rWon&&Math.random()>.45;
      const rGoals=rWon?rand(0,3):rDraw?rand(0,1):0;
      const newSG=(r.seasonGoals||0)+rGoals;
      const newStreak=rWon?(r.streak||0)+1:rDraw?r.streak:0;
      const newForm=[...(r.form||[]),rGoals].slice(-5);
      const newHistory=[...(r.history||[]),{week,goals:rGoals,won:rWon,draw:rDraw}].slice(-10);
      // mood logic
      const avg5=newForm.length?newForm.reduce((a,b)=>a+b,0)/newForm.length:0;
      const mood=newStreak>=3?"confident":avg5>=1.5?"hot":avg5<0.5?"cold":"neutral";
      return{...r,seasonGoals:newSG,goals:newSG,
        wins:r.wins+(rWon?1:0),draws:r.draws+(rDraw?1:0),losses:r.losses+(!rWon&&!rDraw?1:0),
        streak:newStreak,form:newForm,history:newHistory,mood,weeklyResult:{goals:rGoals,won:rWon,draw:rDraw},
      };
    });
    // rival news 12%
    if(Math.random()<.12){
      const fn=pick(RIVAL_NEWS_POOL);
      const rg=rand(1,3);
      setRivalNews({msg:fn(rival?.name||"Rakip",rg)});return;
    }
    // rival taunt 8% — rakip önde ise kışkırtıyor
    if(Math.random()<.08&&(rival?.seasonGoals||0)>(p.sg||0)){
      setRivalChallenge({type:"taunt",msg:pick(RIVAL_TAUNTS)(rival?.name||"Rakip")});return;
    }
    // rival praise 5% — sen önde isen saygı gösteriyor
    if(Math.random()<.05&&p.sg>(rival?.seasonGoals||0)){
      setRivalChallenge({type:"praise",msg:pick(RIVAL_PRAISE)(rival?.name||"Rakip")});return;
    }
    // Her hafta 1-3 dinamik lig haberi üret
    const newsCount=rand(1,3);
    for(let i=0;i<newsCount;i++){
      addNews(generateNewsItem({clubs:CLUBS,player:p,rival,standings,club,week,season,leagueScorers,fixtures}));
    }
  }

  function applyWeeklyEvent(ev,p){
    let up={...p};
    if(ev.morale)up.morale=Math.min(100,Math.max(5,p.morale+ev.morale));
    if(ev.fame)up.fame=Math.min(100,Math.max(0,p.fame+ev.fame));
    if(ev.fitness)up.fitness=Math.min(100,Math.max(5,p.fitness+ev.fitness));
    if(ev.bank)up.bank=p.bank+ev.bank;
    return up;
  }

  function afterMatch(result,pressOpt){
    const morΔ=(result.won?rand(3,8):result.draw?0:rand(-10,-4))+(pressOpt?.m||0);
    const rawFameΔ=result.rating>=8.5?rand(4,8):result.won?rand(1,3):rand(-2,1)+(pressOpt?.f||0);
    const mediaBonus=player.items.includes("media_team")?2:1;
    const fameΔ=rawFameΔ>0?rawFameΔ*mediaBonus:Math.ceil(rawFameΔ*(player.items.includes("media_team")?0.5:1));
    const hasNutr=player.items.includes("nutrition");const hasCryo=player.items.includes("cryo_therapy");const hasRecPod=player.items.includes("recovery_pod");
    let fitBase=hasRecPod?rand(1,3):hasCryo?rand(2,5):hasNutr?rand(3,6):rand(7,14);
    if(hasPerk(player,"engine")) fitBase=Math.round(fitBase*0.7);   // "Motor" rozeti
    const fitLoss=fitBase+(weather.fitExtra||0);
    const hasPhysio=player.items.includes("physio")||player.items.includes("recovery_pod");
    let injW=0,injType="";
    // Sakatlık ihtimali iyileştirildi: Fitness düşükken daha yüksek risk + physio etkisi güçlendirildi
    // Fitness bu eşiğin altına düşerse sakatlık riski doğar.
    // injuryChance = sakatlanma OLASILIĞI; fizyoterapist bunu düşürür (eskiden yanlışlıkla artırıyordu).
    // Eski model: fitness eşiğin altına düştüğü ANDA %45 zar. Fitness 8'de
    // takılınca her maç bu zar atılıyor, oyuncu sezonu revirde geçiriyordu.
    // Yeni model: risk kondisyonla SÜREKLİ artar, sıçrama yok.
    const fitAfter = player.fitness - fitLoss;
    let injuryChance = 0.035 + (fitAfter < 55 ? ((55 - Math.max(0,fitAfter)) / 55) * 0.30 : 0);
    // Yatkınlık çarpanı: 0-20 → ~0.45..1.75 (karekök eğrisi, doğrusal değil)
    const pron=player.injuryProneness??10;
    injuryChance *= Math.max(0.45,Math.min(1.75,0.45+Math.sqrt(pron/10)*0.72));
    if (hasPhysio) injuryChance *= 0.55;
    if (hasPerk(player,"ironman")) injuryChance *= 0.6;
    if ((player.mental ?? 100) < 30) injuryChance *= 1.25;      // tükenmiş oyuncu daha çok sakatlanır
    injuryChance = Math.min(0.42, injuryChance);
    if (Math.random() < injuryChance * diff.injMod) {
      const roll = Math.random();
      let cum = 0;
      for (const it of INJURY_TYPES) {
        cum += it.prob;
        if (roll < cum) {
          const baseWeeks = rand(...it.weeks);
          injW = hasPhysio ? Math.max(1, Math.floor(baseWeeks * 0.6)) : baseWeeks;
          injType = it.name;
          break;
        }
      }
      if (injW > 0) {
        notify(`🚑 ${injType}! ${injW} hafta.`, C.red);
        addSocial(`😢 ${player.name} sakatlandı — ${injType}.`);
      }
    }
    const gr=ageGrow(player.age,diff);
    // Tavana ne kadar uzaksan o kadar hızlı gelişirsin (gerçek kariyer eğrisi)
    const room=Math.max(0,(player.potential||player.overall)-player.overall);
    const roomMul=room<=0?0:room>=18?1.5:room>=10?1.2:room>=5?0.9:0.55;
    let grow=0;
    if(result.rating>=8.5&&Math.random()<gr*roomMul)grow=rand(1,2);
    else if(result.rating>=7.5&&Math.random()<gr*.65*roomMul)grow=1;
    else if(result.rating>=6.5&&Math.random()<gr*.30*roomMul)grow=1;
    // aging decline 30+
    if(player.age>=30&&player.physical>60&&Math.random()<.15)grow=-1;

    // Tek zar: sezon toplamı kariyer toplamıyla tutarlı ilerlesin
    // (eskiden ayrı ayrı zar atılıyor, ikisi birbirini tutmuyordu)
    setRival(r=>{
      const g=rand(0,2);
      return {...r,seasonGoals:(r.seasonGoals||0)+g,
        overall:Math.min(99,r.overall+(Math.random()<.2?1:0))};
    });

    setPlayer(prev=>{
      // XP: maç ekranında gösterilen dökümle BİREBİR aynı (matchXp tek kaynak)
      const earnedXp = result.xpGained ?? matchXp({
        goals:result.goals,assists:result.assists,won:result.won,draw:result.draw,
        rating:result.rating,motm:result.motm}).total;
      const newXp=(prev.xp||0)+earnedXp;
      const newLv=levelFromXp(newXp);
      if(newLv>prev.level){playSfx("levelup");notify(`🎖️ Lv.${newLv}!`,C.gold);setTimeout(()=>setGameBurst({kind:"level"}),260);}
      // Gelişim artık altı özelliğin TAMAMINA dağılır; mevkinin önemsediği özellikler daha olasıdır.
      // (Eskiden yalnızca pace ve shooting gelişiyordu: orta saha ve defans maçla asla gelişemiyordu.)
      const ns={pace:prev.pace,shooting:prev.shooting,passing:prev.passing,dribbling:prev.dribbling,defending:prev.defending,physical:prev.physical};
      if(grow>0){
        const wt=POS_GROWTH[prev.pos]||POS_GROWTH.CM;
        const totW=wt.reduce((a,x)=>a+x[1],0);
        for(let g=0;g<grow;g++){
          let roll=Math.random()*totW;
          for(const[attr,wv]of wt){
            roll-=wv;
            if(roll<=0){ ns[attr]=Math.min(99,ns[attr]+1); break; }
          }
        }
      }else if(grow<0){
        // Yaş kaynaklı düşüş: fiziksel özelliklerden birini törpüler
        const dec=pick(["pace","physical"]);
        ns[dec]=Math.max(30,prev[dec]-1);
      }
      const ovr=Math.min(prev.potential,posWeight(prev.pos,{...prev,...ns}));
      const morCeil=100+(prev.items.includes("mansion")?20:prev.items.includes("villa")?10:0);

      // === Takım Formu ve Moral Sistemi ===
      const tfGain=hasPerk(prev,"leader")?6:4;
      const newTeamForm   = Math.max(40, Math.min(99, (prev.teamForm   || 70) + (result.won ? tfGain : result.draw ? 1 : -3)));
      const newTeamMorale = Math.max(40, Math.min(99, (prev.teamMorale || 70) + (result.won ? 5 : result.draw ? 2 : -4)));
      // Takımın formu oyuncunun moraline de yansır (bu bonus önceden hesaplanıp kullanılmıyordu)
      const teamBonus = Math.floor((newTeamForm - 70) / 10);
      const mentalB=prev.items.includes("mental_coach")?5:0;
      // Pasif gelirler artık YALNIZCA applyWeeklyFinances'ta, haftada bir kez ödenir.
      const fh=[...(prev.formHistory||[]),result.rating].slice(-10);
      const leaderMul=hasPerk(prev,"leader")?1.5:1;
      const newTrust=Math.min(100,Math.max(10,prev.managerTrust+(result.won?3*leaderMul:result.draw?0:-4)));
      const newFan=Math.min(100,Math.max(5,prev.fanLove+(result.won?4:result.draw?1:-3)));
      // ── KART BİRİKİMİ VE CEZA ──
      const newSYellow=(prev.sYellow||0)+(result.yellow||0);
      const newSRed=(prev.sRed||0)+(result.red||0);
      let ban=0,banReason="";
      if(result.red){ ban=rand(2,3); banReason="Kırmızı kart"; }
      else if(newSYellow>0&&newSYellow%4===0&&result.yellow){ ban=1; banReason=`${newSYellow}. sarı kart`; }
      if(ban){
        notify(`🟥 ${banReason} — ${ban} maç ceza!`,C.red);
        addSocial(`🟥 ${player.name} ${banReason.toLowerCase()} nedeniyle ${ban} maç cezalı.`);
      }else if(result.yellow){
        addLog(`🟨 Sarı kart (sezon: ${newSYellow})`);
      }

      let up={...prev,...ns,goals:prev.goals+result.goals,assists:prev.assists+result.assists,matches:prev.matches+1,
        sg:prev.sg+result.goals,sa:prev.sa+result.assists,sm:prev.sm+1,
        // Kart istatistikleri
        yellowCards:(prev.yellowCards||0)+(result.yellow||0),
        redCards:(prev.redCards||0)+(result.red||0),
        sYellow:newSYellow,sRed:newSRed,
        banWeeks:Math.max(prev.banWeeks||0,ban),banReason:ban?banReason:(prev.banWeeks>0?prev.banReason:""),
        // Kaleci / savunma istatistikleri
        saves:(prev.saves||0)+(result.saves||0),
        sSaves:(prev.sSaves||0)+(result.saves||0),
        conceded:(prev.conceded||0)+(result.conceded||0),
        sConceded:(prev.sConceded||0)+(result.conceded||0),
        cleanSheets:(prev.cleanSheets||0)+(result.cleanSheet?1:0),
        sCleanSheets:(prev.sCleanSheets||0)+(result.cleanSheet?1:0),
        motmCount:(prev.motmCount||0)+(result.motm?1:0),
        morale:Math.min(morCeil,Math.max(8,prev.morale+morΔ+mentalB+teamBonus)),
        fitness:Math.min(hasRecPod?110:100,Math.max(8,prev.fitness-fitLoss+(prev.items.includes("energy_drink")?3:0))),fame:Math.min(100,Math.max(0,prev.fame+fameΔ)),
        xp:newXp,level:newLv,overall:ovr,injuryWeeks:injW,injuryType:injType,formHistory:fh,
        _mg:result.goals,_mr:result.rating,pressCount:(prev.pressCount||0)+1,
        _streak:result.won?(prev._streak||0)+1:result.draw?prev._streak:0,
        _rivalBeaten:(prev._rivalBeaten||(prev.sg+result.goals)>(rival?.seasonGoals||0)),

        managerTrust:newTrust,fanLove:newFan,
        value:parseFloat((ovr*.09*(1+prev.sg*.04)).toFixed(1)),
        teamForm: newTeamForm,
        teamMorale: newTeamMorale,
        // ── FAZ 3: zihinsel enerji maçta erir ──
        mental: Math.max(0, Math.min(100, (prev.mental ?? 100) - (result.mentalCost ?? 8))),
        // Kariyer Hedefleri İlerleme (basit bildirim)
      };
      // ── FAZ 3: SÖZLEŞME PRİMLERİ ──
      // Maddeler artık gerçekten ödeniyor; maç başı, gol, asist ve MOTM primi.
      const cl = contract.clauses;
      if (cl) {
        const paid = (cl.appearance || 0)
          + (cl.goalBonus || 0) * result.goals
          + (cl.assistBonus || 0) * result.assists
          + (result.motm ? (cl.motmBonus || 0) : 0);
        if (paid > 0) {
          up.bank = up.bank + paid;
          up.bonusEarned = (prev.bonusEarned || 0) + paid;
          up._lastBonus = paid;
        }
      }
      // Sakatlık geçmişi — kupa odası/sağlık sayfası için kayıt
      if (injW > 0) up.injuryHistory = [...(prev.injuryHistory || []), {name: injType, weeks: injW, season}].slice(-20);
      // Hedef kontrolü
      if (result.goals > 0) {
        const sg = up.sg || 0;
        if (sg >= (prev.seasonGoalTarget || 15) && (prev.sg || 0) < (prev.seasonGoalTarget || 15)) {
          notify(`🎯 Sezon gol hedefine ulaştın! (${sg}/${prev.seasonGoalTarget})`, C.gold);
        }
      }
      return checkAch(up,club);
    });

    // Prim bildirimi (maddeler gerçekten ödendi)
    if(contract.clauses){
      const paid=(contract.clauses.appearance||0)
        +(contract.clauses.goalBonus||0)*result.goals
        +(contract.clauses.assistBonus||0)*result.assists
        +(result.motm?(contract.clauses.motmBonus||0):0);
      if(paid>0){ notify(`💶 Sözleşme primi +€${paid.toLocaleString("tr")}`,C.green); addLog(`💶 Maç primleri +€${paid.toLocaleString("tr")}`); }
    }
    // ── FAZ 3: CİDDİ SAKATLIK KARARI ──
    // 4 haftadan uzun sakatlıkta tedavi yolunu sen seçiyorsun.
    if(injW>=4){ setTimeout(()=>setSeriousInjury({name:injType,weeks:injW}),900); }
    // Standings güncelle — haftanın tamamı tek bir yerden oynatılır
    setStandings(s=>playLeagueWeek(s,fixtures,week,club.name,result).table);

    if(result.goals>=2)addSocial(`🔥 "${player.name} bu gece ${result.goals} golle yıktı!"`);
    if(result.rating>=9.2)addSocial(`⭐ "${player.name} = Sezonun en iyi performansı!"`);
    if(result.rating<5)addSocial(`😬 "${player.name} bu gece kayboldu..."`);

    // Menajerin moral etkisi (ücreti haftalık finans bloğunda kesilir)
    if(manager){
      const mgr=MANAGERS.find(m=>m.id===manager);
      if(mgr&&mgr.moraleMod) setPlayer(p=>({...p,morale:Math.max(8,Math.min(100,p.morale+mgr.moraleMod))}));
    }

    // Takipçi artışı (şöhretle büyür) — PR menajeri burada işe yarar
    const mgrF=MANAGERS.find(m=>m.id===manager);
    const followerGain=Math.floor(result.rating*player.fame*15*(result.won?2:1)*(mgrF?.fameBonus||1)*(hasPerk(player,"magnet")?1.25:1));
    setFollowers(f=>f+followerGain);


    // Kariyer rekoru kontrolü — yan etkiler updater İÇİNDE olmamalı
    // (StrictMode updater'ı iki kez çalıştırır, bildirimler çift gelirdi).
    {
      const g=player.goals+result.goals, a=player.assists+result.assists;
      const rec={...careerRecords}; const hit=[];
      if(g>=250&&!rec.lig_topscorer){rec.lig_topscorer=true;hit.push("🏆 Lig Gol Rekoru kırıldı! 250 gol!");}
      if(a>=150&&!rec.assists_record){rec.assists_record=true;hit.push("🎯 Asist Rekoru! 150 asist!");}
      if((player.caps||0)>=100&&!rec.caps_record){rec.caps_record=true;hit.push("🌍 Milli Maç Rekoru! 100 cap!");}
      if(player.titles>=10&&!rec.titles_record){rec.titles_record=true;hit.push("🏆 Kupa Rekoru! 10 şampiyonluk!");}
      if(player.overall>=95&&!rec.ovr_record){rec.ovr_record=true;hit.push("👑 OVR 95! Tarihin en iyisi!");}
      if(hit.length){ setCareerRecords(rec); hit.forEach((m,i)=>setTimeout(()=>notify(m,C.gold),400+i*900)); }
    }
    // Gazete manşeti — dikkat çeken maçlarda
    if(result.goals>=2||result.motm||result.red||result.rating<5.5||
       Math.abs(result.teamScore-result.oppScore)>=3||Math.random()<0.30){
      const h=mkHeadline(result,player,club);
      setNewspaper({...h,paper:pick(PAPERS),season,week,
        body:mkPaperBody(result,player,club,{leaguePos:myLeaguePos})});
      addSocial(`📰 ${h.head}`);
    }

    // Isı haritası için maç olaylarını sakla
    setLastHeat({id:Date.now(),opp:result.oppName||"Rakip",
      events:[...Array(result.goals).fill({type:"goal"}),
              ...Array(result.assists).fill({type:"assist"}),
              ...Array(Math.min(3,result.saves||0)).fill({type:"save"}),
              ...Array(Math.min(2,result.oppScore||0)).fill({type:"opp_goal"})]});

    // ── MAÇ HEDEFLERİ KONTROLÜ ──
    if(matchObjectives&&matchObjectives.length){
      const done=matchObjectives.filter(o=>o.check(result));
      if(done.length){
        const xpGain=done.reduce((a,o)=>a+o.xp,0);
        const trustGain=done.reduce((a,o)=>a+o.trust,0);
        setPlayer(p=>({...p,xp:(p.xp||0)+xpGain,
          managerTrust:Math.min(100,(p.managerTrust??70)+trustGain)}));
        addLog(`🎯 ${done.length}/${matchObjectives.length} maç hedefi tamamlandı (+${xpGain} XP)`);
      }
      setObjResult({list:matchObjectives.map(o=>({...o,ok:o.check(result)})),
        xp:done.reduce((a,o)=>a+o.xp,0)});
      setMatchObjectives(mkMatchObjectives(player));
    }

    // Gol krallığı: rakip golcüler oyuncunun performansına göre de tepki verir
    if(result.goals>0){
      addLog(`👟 Gol krallığı: ${player.sg+result.goals} gol`);
    }
    // Maç sonrası dinamik haberler (1-2 adet)
    const matchNewsCount=rand(1,2);
    for(let i=0;i<matchNewsCount;i++){
      const ni=generateNewsItem({clubs:CLUBS,player,rival,standings,club,week,season,leagueScorers,fixtures,
        lastResult:{teamScore:result.teamScore,oppScore:result.oppScore,won:result.won,draw:result.draw,
          goals:result.goals,assists:result.assists,oppName:result.oppName||"rakip"}});
      addNews(ni);
    }
    addLog(`${result.won?"✅":result.draw?"🔲":"❌"} ${club.name} ${result.teamScore}–${result.oppScore} | ${result.goals}G ${result.assists}A | ⭐${result.rating}`);

    const agMul=player.items.includes("private_jet")?4.5:player.items.includes("agent_pro")?3.5:player.items.includes("agent_basic")?2:1;
    const mgr=MANAGERS.find(m=>m.id===manager);
    // Transfer artık yalnızca transfer döneminde gelir (kış arası veya sezon sonu yaklaşırken)
    if(isTransferWindow(week,SEASON_WEEKS)&&!transferBan&&result.rating>=8.0&&Math.random()<.16*agMul*(mgr?.transferBonus||1)){
      // Bir maç birden fazla kulübü harekete geçirebilir — masaya 1-3 teklif gelir.
      // (Serbest kalma bedelini ödeyen kulüp varsa o listenin başına alınır.)
      const bidders=CLUBS.filter(c=>c.prestige>=club.prestige&&c.name!==club.name)
        .sort(()=>Math.random()-.5).slice(0,result.rating>=9?rand(2,3):rand(1,2));
      if(bidders.length){
        const offers=bidders.map(mkOffer);
        offers.sort((a,b)=>(b.release?1:0)-(a.release?1:0)||b.salary-a.salary);
        setTransfers(offers);
        setTransferNegotiation(offers[0]);
        const bo=offers.find(o=>o.release);
        setTimeout(()=>{
          if(bo){
            notify(`🔓 ${bo.from.name} serbest kalma bedelini ödedi!`,C.gold);
            addSocial(`🔓 ${bo.from.name}, ${player.name}'in €${bo.fee}M'luk serbest kalma bedelini ödedi.`);
          }else{
            notify(`📨 ${offers.length===1?offers[0].from.name+" teklif etti":offers.length+" kulüp teklif etti"}!`,C.purple);
          }
        },700);
      }
    }

    if(player.fame>40&&player.caps===0&&Math.random()>.72)setNationalCall(true);
    if(season%4===0&&week===20&&player.caps>0&&!wcCall&&!showWC)setWcCall(true);
    // Sözleşme yenileme: son yılda ısrarla, aksi halde sezon ortasında
    const renewWeek=Math.round(SEASON_WEEKS*0.53);
    if(!freeAgent&&(week===renewWeek||(contract.years<=1&&week%6===0))&&Math.random()>.45){
      const formMul=result.rating>=8?1.18:result.rating>=7?1.0:0.88;
      const ns=Math.max(3,Math.round(contract.salary*rand(112,148)/100*formMul*(mgr?.salBonus||1)));
      setContract(c=>({...c,offer:{years:rand(2,4),salary:ns}}));setShowContract(true);
    }
    // Emeklilik teklifi sezonda bir kez sorulur (eskiden 35 yaştan sonra HER maç açılıyordu)
    if(player.age>=35&&!player.retired&&!retirePrompted.current){retirePrompted.current=true;setRetireModal(true);}
    // Turkey Cup: sezon ortası (hafta 17) Türkiye ligi ise
    if(week===17&&club.leagueId==="superlig"&&Math.random()>.3&&!showTurkeyCup)setShowTurkeyCup(true);
    // Europa League: hafta 10, prestige 5-7 arası kulüpler
    // Conference League: hafta 8, prestige 3-5 arası kulüpler
    // Starter risk: kötü oynayınca yedek riski
    if(result.rating<5.5&&Math.random()<.4)setStarterRisk(true);
    // Weekly recap every 5 weeks
    if(week%5===0){
      const last5=player.formHistory?.slice(-5)||[];
      const avg=last5.length?(last5.reduce((a,b)=>a+b,0)/last5.length).toFixed(1):"–";
      setWeeklyRecap({goals:result.goals,assists:result.assists,rating:result.rating,avg5:avg,week});
    }

    rollWeeklyEvent(player);
    setWeather(pick(WEATHER));
    setTrained(0);
    setWeek(w=>w+1);
    advanceWeekHooks(week+1);
  }

  // ── AVRUPA KUPASI: haftanın maçını oyna ──
  function playEuroMatch(){
    if(!euroCup||euroCup.stage==="done")return;
    const cup=EURO_CUPS[euroCup.cupId];
    const squadOvr=teammates.length?teammates.reduce((a,t)=>a+(t.ovr||65),0)/teammates.length:null;

    if(euroCup.stage==="group"){
      const m=euroCup.fxMine[euroCup.gIdx];
      if(!m)return;
      const isHome=m.home===club.name;
      const oppName=isHome?m.away:m.home;
      const r=simMatch(player,tactic,weather,diff.matchMod,
        {club,opponent:getClub(oppName),isHome,oppName,squadOvr});
      let t=applyEuroRow(euroCup.table,club.name,r.teamScore,r.oppScore);
      t=applyEuroRow(t,oppName,r.oppScore,r.teamScore);
      const others=euroCup.fxRest[euroCup.gIdx];
      if(others){
        const nr=simNPCMatch(others.home,others.away);
        t=applyEuroRow(t,others.home,nr.homeGoals,nr.awayGoals);
        t=applyEuroRow(t,others.away,nr.awayGoals,nr.homeGoals);
      }
      const gIdx=euroCup.gIdx+1;
      const log=[...euroCup.log,{opp:oppName,ts:r.teamScore,os:r.oppScore,won:r.won,draw:r.draw,
        goals:r.goals,assists:r.assists,rating:r.rating,stage:`Grup ${euroCup.gIdx+1}`}];
      const totals={goals:euroCup.totals.goals+r.goals,assists:euroCup.totals.assists+r.assists,
        matches:euroCup.totals.matches+1};
      // Kupa golleri kariyer istatistiğine de işlenir
      setPlayer(p=>checkAch({...p,goals:p.goals+r.goals,assists:p.assists+r.assists,
        matches:p.matches+1,fame:Math.min(100,p.fame+(r.goals>0?2:0))},club));
      addLog(`${cup.icon} ${cup.short} ${euroCup.gIdx+1}. maç: ${club.name} ${r.teamScore}-${r.oppScore} ${oppName} (${r.goals}G ${r.assists}A)`);

      if(gIdx>=euroCup.fxMine.length){
        const srt=sortTable(t.map(x=>({...x,isMe:x.name===club.name})));
        const pos=srt.findIndex(x=>x.name===club.name)+1;
        if(pos<=2){
          setEuroCup({...euroCup,table:t,gIdx,log,totals,stage:"ko"});
          notify(`${cup.icon} Gruptan ${pos}. sırada çıktın!`,cup.color);
          addSocial(`${cup.icon} ${club.name} ${cup.name} grubundan ${pos}. sırada çıktı!`);
        }else{
          setEuroCup({...euroCup,table:t,gIdx,log,totals,stage:"done",eliminated:true});
          notify(`❌ ${cup.name} grubunda elendin (${pos}. sıra)`,C.red);
        }
      }else{
        setEuroCup({...euroCup,table:t,gIdx,log,totals});
        notify(`${cup.icon} ${r.won?"Galibiyet":r.draw?"Beraberlik":"Mağlubiyet"} ${r.teamScore}-${r.oppScore}`,
          r.won?C.green:r.draw?C.gold:C.red);
      }
      return;
    }

    // ── ELEME ──
    const stageName=cup.koStages[euroCup.koIdx];
    const oppName=euroCup.koOpps[euroCup.koIdx]||"Rakip";
    const oppClub=getClub(oppName);
    const r=simMatch(player,tactic,weather,diff.matchMod,
      {club,opponent:oppClub,oppPrestige:oppClub?undefined:Math.min(10,7+euroCup.koIdx),
       oppName,isHome:euroCup.koIdx%2===0,squadOvr});
    let ts=r.teamScore,os=r.oppScore,pens=null;
    if(ts===os){
      const myPen=rand(3,5),opPen=rand(3,5);
      pens={me:myPen,opp:opPen,meWin:myPen!==opPen?myPen>opPen:Math.random()<0.5};
    }
    const advanced=pens?pens.meWin:ts>os;
    const log=[...euroCup.log,{opp:oppName,ts,os,won:advanced,draw:false,goals:r.goals,
      assists:r.assists,rating:r.rating,stage:stageName,pens}];
    const totals={goals:euroCup.totals.goals+r.goals,assists:euroCup.totals.assists+r.assists,
      matches:euroCup.totals.matches+1};
    setPlayer(p=>checkAch({...p,goals:p.goals+r.goals,assists:p.assists+r.assists,
      matches:p.matches+1,fame:Math.min(100,p.fame+(r.goals>0?3:1))},club));
    addLog(`${cup.icon} ${stageName}: ${club.name} ${ts}-${os} ${oppName}${pens?` (pen ${pens.me}-${pens.opp})`:""}`);

    if(!advanced){
      setEuroCup({...euroCup,log,totals,stage:"done",eliminated:true});
      notify(`❌ ${stageName}'de elendin`,C.red);
      addSocial(`❌ ${club.name} ${cup.name}'de ${stageName} turunda elendi.`);
      return;
    }
    if(euroCup.koIdx>=cup.koStages.length-1){
      setEuroCup({...euroCup,log,totals,stage:"done",won:true});
      setPlayer(p=>checkAch({...p,clTitles:(p.clTitles||0)+1,bank:p.bank+cup.prize*1000,
        morale:Math.min(100,p.morale+18),fame:Math.min(100,p.fame+20)},club));
      setTitlesWonThisSeason(t=>[...t,euroCup.cupId]);
      setConfetti(true);setTimeout(()=>setConfetti(false),3000);
      notify(`${cup.icon} ${cup.name.toUpperCase()} ŞAMPİYONU!`,cup.color);
      addSocial(`${cup.icon} ${player.name} ${cup.name} kupasını kaldırdı!`);
      addLog(`${cup.icon} ${cup.name.toUpperCase()} ŞAMPİYONU!`);
      return;
    }
    setEuroCup({...euroCup,log,totals,koIdx:euroCup.koIdx+1});
    notify(`✅ ${stageName} geçildi!`,C.green);
  }

  // Borsa her hafta hareket eder (rastgele yürüyüş + hafif yukarı eğilim)
  function tickMarket(){
    setMarket(ms=>ms.map(m=>{
      const a=MARKET_ASSETS.find(x=>x.id===m.id);
      if(!a)return m;
      const shock=gauss(1)*a.vol;                 // normal dağılımlı oynaklık
      const next=Math.max(Math.round(a.base*0.12),Math.round(m.price*(1+a.drift+shock)));
      return {...m,prev:m.price,price:next,history:[...m.history,next].slice(-24)};
    }));
    // Marka anlaşması teklifi
    setPlayer(p=>{
      const has=(p.brandDeals||[]).map(d=>d.id);
      const elig=BRAND_DEALS.filter(d=>!has.includes(d.id)&&p.fame>=d.minFame&&p.overall>=d.reqOvr);
      if(elig.length&&Math.random()<0.10) setBrandOffer(pick(elig));
      return p;
    });
  }

  // Haftalık maaş, vergi ve giderler — haftada BİR kez, tek yerden
  function applyWeeklyFinances(){
    const gross=Math.round(contract.salary*WAGE_UNIT);
    const taxRate=getTaxRate(contract.salary);
    const tax=Math.round(gross*taxRate);
    const mgr=MANAGERS.find(m=>m.id===manager);
    const mgrFee=mgr?.weeklyFee?mgr.weeklyFee*100:0;
    setPlayer(p=>{
      let upkeep=0;
      for(const it of (p.items||[])) upkeep+=UPKEEP[it]||0;
      let sponsor=0;
      for(const it of (p.items||[])){
        const si=SHOP_ITEMS.find(x=>x.id===it);
        if(!si) continue;
        const t=si.effect?.type;
        if(t==="sponsor"||t==="sponsor_fitness") sponsor+=(si.effect.val||0)*30;
        if(t==="academy")  sponsor+=1000;      // eskiden sadece maç oynanan hafta geliyordu
        if(t==="supercar") sponsor+=300;
      }
      // Marka anlaşmaları
      let brand=0;
      for(const d of (p.brandDeals||[])) brand+=d.weekly||0;
      if(hasPerk(p,"magnet")) brand=Math.round(brand*1.25);
      const net=gross-tax-upkeep-mgrFee+sponsor+brand;
      // Borç gerçek: bakiye eksiye düşebilir. Eskiden Math.max(0,…) ile
      // kırpıldığı için malikâne+yat+jet bakımı fiilen bedavaydı.
      let bank=p.bank+net;
      let sold=null;
      if(bank<0){
        // Eksideysen kulüp/menajer devreye girer: en pahalı bakımlı varlık satılır
        const owned=(p.items||[]).filter(it=>UPKEEP[it]);
        if(owned.length){
          const worst=owned.sort((a,b)=>(UPKEEP[b]||0)-(UPKEEP[a]||0))[0];
          const si=SHOP_ITEMS.find(x=>x.id===worst);
          const refund=Math.round((si?.price||0)*0.55);   // zararına satış
          bank+=refund;
          sold={id:worst,name:si?.name||worst,refund};
          p={...p,items:(p.items||[]).filter(it=>it!==worst)};
        }
      }
      return {...p,bank:Math.round(bank),weeklyIncome:net,_forcedSale:sold,
        _lastPay:{gross,tax,upkeep,mgrFee,sponsor,brand,net}};
    });
    if(tax>0) addLog(`💸 Maaş €${gross.toLocaleString()} · vergi −€${tax.toLocaleString()} (%${Math.round(taxRate*100)})`);
    // Zorunlu satış olduysa bildir
    setPlayer(p=>{
      if(p._forcedSale){
        const {name,refund}=p._forcedSale;
        setTimeout(()=>{
          notify(`🏦 Borç! ${name} zararına satıldı (+€${refund.toLocaleString("tr")})`,C.red);
          addSocial(`💸 ${p.name} mali sıkıntı nedeniyle ${name} satmak zorunda kaldı.`);
        },400);
        addLog(`🏦 Borç nedeniyle ${name} satıldı (+€${refund.toLocaleString("tr")})`);
        const np={...p}; delete np._forcedSale; return np;
      }
      return p;
    });
  }

  // Hafta ilerlediğinde çalışan ortak kancalar (maç oynasan da dinlensen de aynı)
  function advanceWeekHooks(nextWeek){
    // Avrupa kupası maçı bu hafta mı?
    if(euroCup&&euroCup.stage!=="done"&&euroMatchDue(euroCup,nextWeek)){
      const cup=EURO_CUPS[euroCup.cupId];
      setTimeout(()=>{
        notify(`${cup.icon} ${cup.name} maçın var!`,cup.color);
        setShowEuroCup(true);
      },500);
    }
    applyWeeklyFinances();
    tickMarket();
    setTalkedToCoach(false);
    // Seçimli hayat olayı — haftaların yaklaşık yarısında
    if(Math.random()<0.45&&!player.retired){
      const ev=pickLifeEvent();
      const mate=pick((teammates||[]).filter(t=>!t.isMyPos))?.name||"Takım kaptanı";
      setLifeEvent({ev,ctx:{mate,rivalName:rival?.name||"Rakibin"}});
    }
    setPlayer(p=>p.extraTraining?{...p,extraTraining:false}:p);
    // ── HAFTALIK TOPARLANMA (kondisyon) ──
    // Bir futbolcu maçlar arasında dinlenir. Bu olmadığı için kariyer
    // 4. haftada sakatlık sarmalına giriyordu.
    setPlayer(p=>{
      if(p.retired) return p;
      const cap=p.items?.includes("recovery_pod")?110:100;
      return {...p,fitness:Math.min(cap,Math.round((p.fitness??100)+weeklyRecovery(p)))};
    });
    // ── FAZ 3: haftalık zihinsel toparlanma ──
    // Kafa kendiliğinden biraz dinlenir; yoğun takvim ve düşük moral bunu yavaşlatır.
    setPlayer(p=>{
      const base=6+(p.items?.includes("mental_coach")?4:0)+(p.mentalResist||0);
      const drag=(p.morale<40?-3:0)+((p.injuryWeeks||0)>0?-2:0)+(euroCup&&euroCup.stage!=="done"?-2:0);
      return {...p,mental:Math.max(0,Math.min(100,(p.mental??100)+base+drag))};
    });
    // Tükenmişlik uyarısı — bir kez, sonra tedavi alınca sıfırlanır
    if((player.mental??100)<28&&!burnoutWarned.current&&!player.retired){
      burnoutWarned.current=true;
      setTimeout(()=>{ notify("💀 Tükenmişlik sınırındasın!",C.red); setShowBurnout(true); },1100);
    }
    // Basın toplantısı: haftaların yaklaşık üçte birinde kapını çalar
    if(!player.academy&&!player.retired&&Math.random()<0.32){
      setTimeout(()=>openPress(Math.random()<0.5?"pre":"post"),1500);
    }
    if(nextWeek>SEASON_WEEKS){ setTimeout(()=>setShowSeasonEnd(true),700); return; }
    // Lig gol krallığı yarışını ilerlet
    setLeagueScorers(ls=>ls.map(s2=>({...s2,goals:s2.goals+(Math.random()<s2.rate?1:0)+(Math.random()<s2.rate*0.35?1:0)})));
  }

  function doTraining(type){
    const maxTrain=player.items.includes("vr_training")?2:1;
    if(trained>=(maxTrain)){notify("Bu hafta antrenman hakkın doldu!",C.orange);return;}
    if(player.fitness<28){notify("Fitness çok düşük!",C.red);return;}
    if(player.injuryWeeks>0){notify("Sakatlısın!",C.red);return;}
    const hasCoach=player.items.includes(`coach_${type}`);const hasSci=player.items.includes("sport_science");
    // Tavana yaklaştıkça gelişim yavaşlar — potansiyeline ulaşmış oyuncu antrenmanla zıplayamaz
    const room=Math.max(0,(player.potential||player.overall)-player.overall);
    if(room<=0){notify("Potansiyelinin tavanındasın — gelişim çok yavaş.",C.orange);}
    const roomMul=room<=0?0.25:room>=15?1:room>=8?0.8:0.5;
    const raw=(hasCoach?rand(2,3):1)+(hasSci?1:0);
    const g=Math.max(1,Math.round(raw*roomMul));
    setPlayer(p=>{
      const up={...p,[type]:Math.min(99,p[type]+g),fitness:Math.max(8,p.fitness-11)};
      // OVR antrenmandan HEMEN sonra güncellenmeli (eskiden maç oynanana kadar değişmiyordu)
      up.overall=Math.min(up.potential||99,posWeight(up.pos,up));
      up.value=parseFloat((up.overall*.09*(1+up.sg*.04)).toFixed(1));
      return checkAch(up,club);
    });
    setTrained(t=>t+1);
    notify(`💪 ${type} +${g}${hasCoach?" ⭐":""}`,C.green);
    addLog(`🏋️ ${type} +${g}`);
  }


  // ═══════════ FAZ 3 — OYUN İÇİ AKIŞLAR ═══════════

  // Haftalık antrenman planı: planı bir kez uygular, kazanç/bedel raporu döner.
  const trainPlan = player.trainPlan || defaultPlan(player.pos);
  function setPlanDay(idx,drillId){
    setPlayer(p=>{
      const plan={...(p.trainPlan||defaultPlan(p.pos))};
      const days=[...(plan.days||[])]; days[idx]=drillId;
      return {...p,trainPlan:{...plan,days}};
    });
    playSfx("click");
  }
  function setPlanIntensity(id){
    setPlayer(p=>({...p,trainPlan:{...(p.trainPlan||defaultPlan(p.pos)),intensity:id}}));
    playSfx("tab");
  }
  function runWeeklyPlan(){
    if(trained>0){notify("Bu haftanın planını zaten çalıştın.",C.orange);return;}
    if(player.injuryWeeks>0){notify("Sakatsın — bu hafta antrenman yok.",C.red);return;}
    if(player.retired){return;}
    const res=runTrainPlan(player,trainPlan,diff.growMod);
    setPlayer(p=>{
      const merged={...p,...res.player};
      return checkAch(merged,club);
    });
    setTrained(t=>t+1);
    setPlanResult(res);
    playSfx(res.injury?"error":"levelup");
    if(res.injury){
      notify(`🚑 Antrenmanda sakatlandın: ${res.injury.name} (${res.injury.weeks} hafta)`,C.red);
      addSocial(`😖 ${player.name} antrenmanda sakatlandı — ${res.injury.name}.`);
      addLog(`🚑 Antrenman sakatlığı: ${res.injury.name}`);
      if(res.injury.weeks>=4) setTimeout(()=>setSeriousInjury({name:res.injury.name,weeks:res.injury.weeks}),800);
    }else{
      addLog(`🗓️ Haftalık plan tamamlandı${res.applied.length?` · ${res.applied.join(", ")}`:""}`);
    }
  }

  // Zihinsel toparlanma — tükenmişliğin gerçek bir çaresi var
  function buyBurnoutHelp(id){
    const h=BURNOUT_HELP.find(x=>x.id===id); if(!h)return;
    if(player.bank<h.cost){notify("Paran yetmiyor.",C.red);return;}
    setPlayer(p=>({...p,
      bank:p.bank-h.cost,
      mental:Math.min(100,(p.mental??100)+h.mental),
      fitness:id==="holiday"?Math.min(100,p.fitness+15):p.fitness,
      fame:Math.min(100,(p.fame||5)+(h.fame||0)),
      mentalResist:id==="meditate"?Math.min(12,(p.mentalResist||0)+2):(p.mentalResist||0),
    }));
    playSfx("coin");
    notify(`${h.icon} ${h.name} · Zihin +${h.mental}`,C.green);
    addLog(`${h.icon} ${h.name} (€${h.cost.toLocaleString("tr")})`);
    burnoutWarned.current=false;
    setShowBurnout(false);
  }

  // Ciddi sakatlıkta tedavi kararı
  function decideInjury(optId){
    const opt=SURGERY_OPTIONS.find(o=>o.id===optId); if(!opt||!seriousInjury)return;
    const cost=Math.round(seriousInjuryCost(seriousInjury.weeks)*opt.costMul);
    if(cost>player.bank){notify("Bu tedaviyi karşılayamıyorsun.",C.red);return;}
    const newWeeks=Math.max(1,Math.round(seriousInjury.weeks*opt.weeksMul));
    const backfire=Math.random()<opt.risk;
    setPlayer(p=>{
      let np={...p,bank:p.bank-cost,injuryWeeks:newWeeks,injuryType:seriousInjury.name};
      if(backfire){
        // Nüks: süre uzar ve fizik kalıcı olarak düşer
        np.injuryWeeks=newWeeks+rand(2,5);
        np.physical=Math.max(30,np.physical-rand(1,3));
        np.pace=Math.max(30,np.pace-(optId==="play"?rand(1,3):0));
        np.morale=Math.max(8,np.morale-10);
        np.overall=Math.min(np.potential||99,posWeight(np.pos,np));
      }else if(optId==="top"){
        np.morale=Math.min(100,np.morale+6);
      }
      np.injuryHistory=[...(p.injuryHistory||[]),{name:seriousInjury.name,weeks:np.injuryWeeks,season,surgery:optId}].slice(-20);
      return np;
    });
    if(backfire){
      notify("😖 Tedavi beklendiği gibi gitmedi — nüks!",C.red);
      addSocial(`🚑 ${player.name}'in sakatlığı beklenenden uzun sürecek.`);
    }else{
      notify(`${opt.icon} ${opt.name} · ${newWeeks} hafta`,C.green);
    }
    addLog(`${opt.icon} ${seriousInjury.name} tedavisi: ${opt.name}${cost?` (€${cost.toLocaleString("tr")})`:""}`);
    setSeriousInjury(null);
  }

  // Basın toplantısı — cevapların hoca, taraftar ve takım üzerinde gerçek etkisi var
  function openPress(kind="pre"){
    const topics=pickPressTopics(player,rival,kind==="post"?3:2);
    setPressAnswers({});
    setPressConf({kind,topics});
    playSfx("tab");
  }
  function submitPress(){
    if(!pressConf)return;
    const picks=pressConf.topics.map((t,i)=>t.answers[pressAnswers[i]??0]);
    let trust=0,fame=0,fan=0,mor=0,tm=0,tags=[];
    picks.forEach(a=>{
      const f=a.fx||{};
      trust+=f.trust||0; fame+=f.fame||0; fan+=f.fanLove||0; mor+=f.morale||0; tm+=f.teamMorale||0;
      tags.push(a.tag);
    });
    // Medya eğitimi aldıysan olumsuz etkiler yumuşar, olumlular büyür
    const skill=(player.mediaSkill||30)/100;
    const soften=v=>v<0?Math.round(v*(1-skill*0.55)):Math.round(v*(1+skill*0.45));
    setPlayer(p=>({...p,
      managerTrust:Math.max(5,Math.min(100,(p.managerTrust??70)+soften(trust))),
      fame:Math.max(0,Math.min(100,(p.fame||5)+soften(fame))),
      fanLove:Math.max(0,Math.min(100,(p.fanLove||60)+soften(fan))),
      morale:Math.max(8,Math.min(100,p.morale+soften(mor))),
      teamMorale:Math.max(40,Math.min(99,(p.teamMorale||70)+soften(tm))),
      mental:Math.max(0,Math.min(100,(p.mental??100)-3)),
      mediaSkill:Math.min(100,(p.mediaSkill||30)+2),
      pressCount:(p.pressCount||0)+1,
    }));
    addSocial(`🎤 Basın toplantısı: ${player.name} "${picks[0].t}"`);
    addLog(`🎤 Basın toplantısı · ${tags.join(" · ")}`);
    notify(`🎤 Basın toplantısı tamam · ${tags[0]}`,C.accent);
    playSfx("click");
    setPressConf(null);
  }

  // Forma numarası
  const takenNos=takenNumbers(teammates);
  function pickNumber(n){
    if(takenNos.has(n)){notify("Bu numara takımda dolu.",C.red);return;}
    const req=NUMBER_REQ[n]??0;
    if(player.overall<req){notify(`${n} numara için en az ${req} OVR gerekiyor.`,C.orange);return;}
    setPlayer(p=>({...p,shirtNo:n,fame:Math.min(100,(p.fame||5)+(ICONIC_NUMBERS[n]?2:0))}));
    playSfx("levelup");
    notify(`👕 Artık ${n} numarasın!`,C.gold);
    addSocial(`👕 ${player.name} bu sezon ${n} numaralı formayı giyecek.`);
    setShowNumberPick(false);
  }

  // Kupa odasına ödül ekle (tek kaynak — her kupa buradan geçer)
  const awardTrophy=useCallback((id,detail)=>{
    setPlayer(p=>({...p,trophyCabinet:[...(p.trophyCabinet||[]),
      {id,season,club:club.name,detail:detail||""}]}));
  },[season,club]);

  // ── YEDEK TAKIM MAÇI ──
  // Kadro dışı kalan oyuncunun hocayı ikna edebileceği tek yol. Olmadan
  // managerTrust tek yönlü düşüyor ve kariyer geri dönülmez şekilde tıkanıyordu.
  function playReserveMatch(){
    if(player.injuryWeeks>0){notify("Sakatsın.",C.red);return;}
    if(player.banWeeks>0){notify("Cezalısın — yedek takımda da oynayamazsın.",C.red);return;}
    const r=simU19Match(player);              // aynı motor: zayıf rakip, düşük tempo
    const great=r.rating>=7.5, ok=r.rating>=6.5;
    const trustGain=great?rand(5,8):ok?rand(2,4):-1;
    setPlayer(p=>{
      const fh=[...(p.formHistory||[]),r.rating].slice(-10);
      return {...p,
        formHistory:fh,
        managerTrust:Math.max(5,Math.min(100,(p.managerTrust??70)+trustGain)),
        morale:Math.max(8,Math.min(100,p.morale+(great?7:ok?3:-3))),
        fitness:Math.max(10,p.fitness-9),
        mental:Math.max(0,(p.mental??100)-4),
        xp:(p.xp||0)+Math.round(12+r.goals*9+r.assists*6),
        reserveMatches:(p.reserveMatches||0)+1,
      };
    });
    setU19Result({...r,reserve:true,trustGain});
    playSfx(great?"win":"whistle");
    addLog(`🅿️ Yedek takım ${r.teamScore}-${r.oppScore} · ${r.goals}G ${r.assists}A · ⭐${r.rating} · Hoca ${trustGain>0?"+":""}${trustGain}`);
    if(great) addSocial(`👀 ${player.name} yedek takımda ${r.rating} reytingle oynadı — teknik heyet not aldı.`);
    // Hafta ilerler: A takım kendi maçını oynar
    const wk=playLeagueWeek(standings,fixtures,week,club.name,null);
    setStandings(wk.table);
    if(wk.myMatch){
      setPlayer(p=>({...p,
        teamForm:Math.max(40,Math.min(99,(p.teamForm||70)+(wk.myMatch.won?2:wk.myMatch.draw?1:-2))),
        teamMorale:Math.max(40,Math.min(99,(p.teamMorale||70)+(wk.myMatch.won?2:wk.myMatch.draw?1:-2)))}));
    }
    setTrained(0);setWeather(pick(WEATHER));
    setWeek(w=>w+1);
    advanceWeekHooks(week+1);
  }

  // ── ALTYAPI (U19) ──
  function playU19(){
    if(player.injuryWeeks>0){notify("Sakatsın.",C.red);return;}
    const r=simU19Match(player);
    const pts=Math.min(ACADEMY_TARGET,(player.academyPts||0)+r.scoutPts);
    setPlayer(p=>{
      const fh=[...(p.formHistory||[]),r.rating].slice(-10);
      const grow=r.rating>=7.5&&Math.random()<0.55?1:r.rating>=6.5&&Math.random()<0.25?1:0;
      const ns={...p};
      if(grow){
        const wt=POS_GROWTH[p.pos]||POS_GROWTH.CM;
        let roll=Math.random()*wt.reduce((a,x)=>a+x[1],0);
        for(const[attr,wv]of wt){ roll-=wv; if(roll<=0){ns[attr]=Math.min(99,ns[attr]+1);break;} }
      }
      ns.academyPts=pts;
      ns.u19Matches=(p.u19Matches||0)+1;
      ns.u19Goals=(p.u19Goals||0)+r.goals;
      ns.u19Assists=(p.u19Assists||0)+r.assists;
      ns.formHistory=fh;
      ns.xp=(p.xp||0)+Math.round(18+r.goals*12+r.assists*7);
      ns.level=levelFromXp(ns.xp);
      ns.fitness=Math.max(10,p.fitness-16);
      ns.mental=Math.max(0,(p.mental??100)-5);
      ns.morale=Math.max(8,Math.min(100,p.morale+(r.won?5:r.draw?1:-4)));
      ns.managerTrust=Math.max(5,Math.min(100,(p.managerTrust??45)+(r.rating>=7.5?3:r.rating>=6.5?1:-2)));
      ns.overall=Math.min(ns.potential||99,posWeight(ns.pos,ns));
      ns.value=parseFloat((ns.overall*.05).toFixed(1));
      return ns;
    });
    setU19Result(r);
    playSfx(r.won?"win":"whistle");
    addLog(`🎓 U19 ${r.teamScore}-${r.oppScore} ${r.oppName} · ${r.goals}G ${r.assists}A · ${r.rating}`);
    // A takım kendi lig maçını sensiz oynar — takvim ilerlemeli
    const wk=playLeagueWeek(standings,fixtures,week,club.name,null);
    setStandings(wk.table);
    if(wk.myMatch){
      setPlayer(p=>({...p,
        teamForm:Math.max(40,Math.min(99,(p.teamForm||70)+(wk.myMatch.won?2:wk.myMatch.draw?1:-2))),
        teamMorale:Math.max(40,Math.min(99,(p.teamMorale||70)+(wk.myMatch.won?2:wk.myMatch.draw?1:-2))),
      }));
    }
    setTrained(0); setWeather(pick(WEATHER));
    setWeek(w=>w+1);
    advanceWeekHooks(week+1);
    if(pts>=ACADEMY_TARGET&&(player.academyPts||0)<ACADEMY_TARGET){
      setTimeout(()=>setAcademyPromo(true),1200);
    }
  }
  function promoteToFirstTeam(){
    setPlayer(p=>({...p,academy:false,managerTrust:Math.max(55,p.managerTrust??45),
      fame:Math.min(100,(p.fame||1)+6),morale:100,
      trophyCabinet:[...(p.trophyCabinet||[]),{id:"promo",season,club:club.name,detail:"A takıma yükseldi"}]}));
    const sal=Math.max(4,Math.round(wageFor(club.prestige,player.overall)*0.55));
    setContract(c=>({...c,salary:sal,years:Math.max(3,c.years),
      clauses:mkClauses(club.prestige,player.overall,sal,player.age)}));
    setAcademyPromo(false);
    playSfx("win");
    setConfetti(true); setTimeout(()=>setConfetti(false),3500);
    setGameBurst({kind:"trophy",text:"A TAKIM!"});
    notify("🎉 A TAKIMA YÜKSELDİN!",C.gold);
    addSocial(`🌟 ${club.name} altyapısından ${player.name} A takıma yükseldi!`);
    addLog("🎓 Altyapıdan A takıma yükseldin.");
  }

  // Oyuncu oynayamadığında (sakat / cezalı / kulüpsüz) haftayı geçirir.
  // İsteğe bağlı "dinlenme" kaldırıldı — formda bir oyuncu maçı atlayamaz.
  function skipWeek(){
    setPlayer(p=>{
      const bw=Math.max(0,(p.banWeeks||0)-1);
      if((p.banWeeks||0)>0&&bw===0) setTimeout(()=>notify("✅ Cezan bitti, yeniden oynayabilirsin!",C.green),300);
      return {...p,fitness:Math.min(100,p.fitness+26),
        morale:Math.max(8,p.morale-(p.injuryWeeks>0||p.banWeeks>0?2:6)), // oynayamamak moral kırar
        mental:Math.max(0,Math.min(100,(p.mental??100)+10)),             // oynamayan kafa dinlenir
        // Ceza YALNIZCA burada azalır — maç oynanan haftada azalmamalı
        banWeeks:bw,banReason:bw>0?p.banReason:"",
        injuryWeeks:Math.max(0,p.injuryWeeks-1)};
    });
    // Hafta bir kez oynatılır; tabloya yazılan skor ile ekranda gösterilen skor AYNIDIR.
    const wk=playLeagueWeek(standings,fixtures,week,club.name,null);
    setStandings(wk.table);
    const mm=wk.myMatch;
    if(mm){
      setPlayer(p=>({...p,
        teamForm:Math.max(40,Math.min(99,(p.teamForm||70)+(mm.won?3:mm.draw?1:-3))),
        teamMorale:Math.max(40,Math.min(99,(p.teamMorale||70)+(mm.won?3:mm.draw?1:-4))),
        // Sakatlık/ceza/kulüpsüzlük oyuncunun suçu değil — güven düşürmez.
        // Sadece formda olup kadroya girememek hocayı soğutur.
        managerTrust:Math.max(10,Math.min(100,(p.managerTrust??70)
          +((p.injuryWeeks>0||p.banWeeks>0)?0:-1))),
      }));
    }
    setTrained(0);setWeather(pick(WEATHER));
    rollWeeklyEvent(player);

    const matchResult = mm
      ? `${mm.won?"Kazandı":mm.draw?"Berabere":"Kaybetti"} ${mm.teamScore}-${mm.oppScore} (${mm.oppName})`
      : "maç yok";
    notify(`⏭️ Hafta geçildi • Takım ${matchResult}`, C.muted);
    addLog(`⏭️ Oynamadın • Takım ${matchResult}`);

    setWeek(w=>w+1);
    advanceWeekHooks(week+1);
  }
  // ── TEKLİF ÜRETİMİ ──
  // Tek kulüp yerine 1-3 kulüp aynı hafta masaya oturur; liste `transfers`te,
  // seçili olan `transferNegotiation`da durur (portre ekran onu kullanıyor).
  function mkOffer(from){
    const mgr=MANAGERS.find(m=>m.id===manager);
    const lawyerBonus=player.items.includes("lawyer")?1.3:1;
    const fair=wageFor(from.prestige,player.overall);
    const sal=Math.max((contract.salary||0)+3,
      Math.round(fair*rand(95,125)/100*lawyerBonus*(mgr?.salBonus||1)));
    const rel=contract.clauses?.release;
    const buyout=rel!=null&&from.budget>=rel;
    return {from,salary:sal,
      fee:buyout?rel:parseFloat(Math.max(1,(player.value||8)*1.35).toFixed(1)),
      release:buyout,counterSalary:null};
  }
  function pushOffers(clubs){
    const offers=clubs.filter(Boolean).map(mkOffer);
    if(!offers.length) return null;
    setTransfers(offers);
    setTransferNegotiation(offers[0]);
    return offers;
  }
  function scanMarket(){
    if(transferBan){notify("Bu sezon zaten kulüp değiştirdin.",C.orange);return;}
    if(week<=5){notify("Sezon başında piyasa henüz hareketsiz.",C.muted);return;}
    if(!isTransferWindow(week,SEASON_WEEKS)){
      notify(`🔒 Transfer penceresi kapalı — ${transferWindowLabel(week,SEASON_WEEKS)}`,C.orange);return;}
    const pool=CLUBS.filter(c=>c.prestige>=Math.max(3,club.prestige-2)&&c.name!==club.name)
      .sort(()=>Math.random()-.5).slice(0,rand(2,3));
    const offers=pushOffers(pool);
    if(!offers){notify("Uygun kulüp bulunamadı.",C.muted);return;}
    notify(`📨 ${offers.length} kulüp transfer listene girdi!`,C.purple);
  }

  function acceptTransfer(offer,negotiatedSalary){
    if(transferBan){notify("Bu sezon zaten kulüp değiştirdin!",C.red);return;}
    const abroad=offer.from?.country!==club.country,big=(offer.from||offer).prestige>=8;
    const finalClub=offer.from||offer;
    setClub(finalClub);
    (()=>{const sal=negotiatedSalary||offer.salary;
      const cls=mkClauses(finalClub.prestige,player.overall,sal,player.age);
      setContract({years:3,salary:sal,offer:null,clauses:cls,signedSeason:season});
      if(cls.signBonus){
        setPlayer(p=>({...p,bank:p.bank+cls.signBonus,bonusEarned:(p.bonusEarned||0)+cls.signBonus,shirtNo:null,seasonsAtClub:0,captaincy:"none"}));
        setTimeout(()=>notify(`✍️ İmza bonusu +€${cls.signBonus.toLocaleString("tr")}`,C.gold),600);
      }
      setTimeout(()=>setShowNumberPick(true),1400);
    })();
    setTransfers([]);setTransferNegotiation(null);
    const sameLeague=finalClub.leagueId===club.leagueId;
    if(sameLeague){
      // Aynı ligde kalıyorsan sezon tablosu SIFIRLANMAZ, sadece "ben" işareti taşınır
      setStandings(st=>st.map(t=>({...t,isMe:t.name===finalClub.name})));
    }else{
      setStandings(mkStandings(finalClub));
      setFixtures(mkFixtures(finalClub));
      setLeagueScorers(mkLeagueScorers(finalClub.leagueId,finalClub.name));
    }
    setTeammates(mkTeammates(player.pos,finalClub.prestige));
    setPlayer(p=>checkAch({...p,_abroad:abroad||p._abroad,_bigClub:big||p._bigClub,
      salary:negotiatedSalary||offer.salary,
      _countries:[...new Set([...(p._countries||[p.natCountry||club.country]),finalClub.country])]},finalClub));
    setTransferBan(true); // aynı sezon ikinci transfer yok — sezon başında sıfırlanır
    // Sezon içi transferde Avrupa bileti DEĞİŞMEZ — bilet kulübün değil, sezonun sonucudur.
    notify(`✈️ ${finalClub.name} transfer!`,C.gold);
    addSocial(`✈️ TRANSFER! ${player.name} → ${finalClub.name}`);
    addLog(`✈️ Transfer: ${finalClub.name}`);
  }

  // ── RP Handler Fonksiyonları ──
  function handleGirlAction(type,data){
    if(type==="start"){
      setGirlfriend({name:data.name,loyalty:data.loyalty,mood:data.mood,suspicious:false});
      setPlayer(p=>({...p,morale:Math.min(100,p.morale+10),_hasFamily:true}));
      setRpLog(l=>[...l,{season,week,msg:`❤️ ${data.name} ile birlikte olmaya başladın.`}]);
      notify(`💑 ${data.name} ile beraber oldun!`,C.purple);
    } else if(type==="date"){
      setPlayer(p=>({...p,morale:Math.min(100,p.morale+10)}));
      setRpLog(l=>[...l,{season,week,msg:`💑 ${data.name} ile güzel bir akşam geçirdin.`}]);
      notify(`💑 Moral +10`,C.purple);
    }
  }
  function handleNightclub(ev){
    setPlayer(p=>({
      ...p,
      morale:Math.min(100,Math.max(5,p.morale+(ev.morale||0))),
      fame:Math.min(100,Math.max(0,p.fame+(ev.fame||0))),
      fitness:Math.min(100,Math.max(5,p.fitness+(ev.fitness||0))),
    }));
    setRpLog(l=>[...l,{season,week,msg:`🎉 Gece kulübü: ${ev.text.slice(0,60)}...`}]);
    if(ev.risk==="medya")setGirlfriend(g=>g?{...g,suspicious:true}:g);
  }
  function handleCheat(sc,accepted,caught){
    if(!accepted){
      setRpLog(l=>[...l,{season,week,msg:`✋ ${sc.partner} teklifini reddettim.`}]);
      return;
    }
    if(caught){
      setGirlfriend(null);
      setPlayer(p=>({...p,morale:Math.max(5,p.morale-20),fame:Math.min(100,p.fame+5)}));
      setRpLog(l=>[...l,{season,week,msg:`💥 YAKALANDIN! Aldatma skandalı.`}]);
      addSocial(`💥 ${player.name} aldatma skandalı! İlişkisi sona erdi.`);
      notify("💥 Yakalandın! Sevgilini kaybettin.",C.red);
    } else {
      setPlayer(p=>({...p,morale:Math.min(100,p.morale+8)}));
      setRpLog(l=>[...l,{season,week,msg:`🤫 ${sc.partner} ile gizli akşam. Kimse bilmiyor.`}]);
    }
  }
  function handleBreakup(){
    const name=girlfriend?.name||"Sevgilin";
    setGirlfriend(null);
    setPlayer(p=>({...p,morale:Math.max(5,p.morale-15)}));
    setRpLog(l=>[...l,{season,week,msg:`💔 ${name} ile ayrıldın. Moral -15.`}]);
    notify(`💔 ${name} ile ayrıldın.`,C.red);
  }

  function buyItem(item){
    if(item.price>0&&player.bank<item.price){notify("Yetersiz bakiye!",C.red);return;}
    if(item.reqFame&&player.fame<item.reqFame){notify(`Şöhret ${item.reqFame}+ gerekli!`,C.orange);return;}
    let up={bank:player.bank-item.price,items:[...player.items,item.id]};
    const ef=item.effect;
    // Stat bonuses
    if(ef.type==="perm"){
      const stats=ef.stats||[ef.stat];
      stats.forEach(s=>{up[s]=Math.min(99,(player[s]||0)+(ef.val||2));});
    }
    if(ef.type==="instant_fame"||ef.type==="fame_boost")up.fame=Math.min(100,player.fame+(ef.val||0));
    if(ef.type==="sponsor"||ef.type==="sponsor_fitness")up._sponsor=true;
    if(ef.type==="mansion"){up.fame=Math.min(100,player.fame+10);up._moraleCeilBonus=(player._moraleCeilBonus||0)+20;}
    if(ef.type==="supercar"){up.fame=Math.min(100,player.fame+30);}
    if(ef.type==="yacht"){up.fame=Math.min(100,player.fame+25);up.morale=Math.min(100,player.morale+15);}
    if(ef.type==="private_jet"){up.fame=Math.min(100,player.fame+20);}
    if(ef.type==="academy"){up.fame=Math.min(100,player.fame+5);}
    if(ef.type==="recovery_pod"){up.fitness=Math.min(110,player.fitness+10);}
    setPlayer(p=>checkAch({...p,...up},club));
    notify(`🛍️ ${item.name} alındı!`,C.gold);
    addLog(`🛍️ ${item.name}`);
  }

  function nextSeason(wasChamp){
    const avgR=player.formHistory?.length?(player.formHistory.reduce((a,b)=>a+b,0)/player.formHistory.length).toFixed(1):0;
    const finalTable=sortTable(standings);
    const myPos=finalTable.findIndex(t=>t.isMe)+1||finalTable.length;

    // ── AVRUPA BİLETİ: lig sırasına göre, prestij kapısına göre değil ──
    const spot=euroSpotFor(club.leagueId,myPos);
    setEuropeanSpot(spot);

    // ── KÜME DÜŞME / ÇIKMA ──
    const relCount=RELEGATION_COUNT[club.leagueId]??0;
    const relegated=relCount>0&&myPos>finalTable.length-relCount;
    const promoted=!!(LEAGUE_PYRAMID[club.leagueId]?.up)&&myPos<=2;
    let nextClub=club;
    const moves=[];
    if(relegated){
      const downId=LEAGUE_PYRAMID[club.leagueId]?.down;
      if(downId){
        // Alt lige düşen kulübün kendisi taşınmaz; oyuncu alt ligden bir kulüpte devam eder
        const target=pick(CLUBS.filter(c=>c.leagueId===downId))||club;
        nextClub=target;
        moves.push(`📉 ${club.name} küme düştü — ${target.name} ile ${getLg(downId).name}'de devam ediyorsun.`);
      }else{
        moves.push(`📉 ${club.name} küme düştü!`);
      }
    }else if(promoted){
      const upId=LEAGUE_PYRAMID[club.leagueId].up;
      const target=pick(CLUBS.filter(c=>c.leagueId===upId&&c.prestige<=5))||pick(CLUBS.filter(c=>c.leagueId===upId));
      if(target){
        nextClub=target;
        moves.push(`📈 ${club.name} ${getLg(upId).name}'e yükseldi — ${target.name} formasını giyiyorsun!`);
      }
    }
    if(spot) moves.push(`${EURO_LABEL[spot]} biletini aldın! (${myPos}. sıra)`);

    // ── SEZON HEDEFLERİ DEĞERLENDİRMESİ ──
    let objDone=0,objTotal=0,objBank=0,objTrust=0,objFame=0;
    (seasonObjectives||[]).forEach(o=>{
      objTotal++;
      const pr=objectiveProgress(o,player,myPos);
      if(pr.ok){objDone++;objBank+=o.reward.bank||0;objTrust+=o.reward.trust||0;objFame+=o.reward.fame||0;}
    });
    if(objTotal){
      if(objDone===objTotal){
        moves.push(`✅ Yönetimin TÜM hedeflerini tuttturdun! Prim €${objBank.toLocaleString()}`);
      }else if(objDone>=Math.ceil(objTotal/2)){
        moves.push(`🟡 ${objDone}/${objTotal} hedef tutturuldu. Prim €${objBank.toLocaleString()}`);
      }else{
        moves.push(`❌ ${objDone}/${objTotal} hedef — yönetim memnun değil.`);
        objTrust-=15;
      }
    }

    // ── GOL KRALLIĞI ──
    const scorers=[...leagueScorers,{name:player.name,club:club.name,goals:player.sg,isMe:true}]
      .sort((a,b)=>b.goals-a.goals);
    const golKralı=scorers[0];
    if(golKralı?.isMe){
      moves.push(`👟 ${player.sg} golle GOL KRALI oldun!`);
      setCareerRecords(r=>({...r,golden_boot:true}));
    }

    setSeasonSummary({season,myPos,spot,relegated,promoted,moves,
      topScorer:golKralı?{name:golKralı.name,goals:golKralı.goals,isMe:!!golKralı.isMe}:null,
      champion:finalTable[0]?.name});
    setSeasonHistory(h=>[...h,{season,goals:player.sg,assists:player.sa,matches:player.sm,avgRating:avgR,
      club:club.name,champ:wasChamp,overall:player.overall,pos:myPos,league:club.leagueId,
      spot,relegated,promoted,goldenBoot:!!golKralı?.isMe}]);

    setShowSeasonEnd(false);setSeason(s=>s+1);setWeek(1);
    if(wasChamp){setConfetti(true);setTimeout(()=>setConfetti(false),3000);}

    setPlayer(p=>{
      const ageDecline=p.age>=30;
      const np={...p,age:p.age+1,sg:0,sa:0,sm:0,fitness:95,morale:80,formHistory:[],
        sYellow:0,sRed:0,sSaves:0,sConceded:0,sCleanSheets:0,banWeeks:0,banReason:"",
        // Yaz arası: uzun sakatlıklar tamamen silinmez ama ara boyunca iyileşir
        injuryWeeks:Math.max(0,(p.injuryWeeks||0)-5),
        injuryType:(p.injuryWeeks||0)>5?p.injuryType:"",
        titles:wasChamp?p.titles+1:p.titles,
        physical:ageDecline?Math.max(55,p.physical-rand(0,2)):p.physical,
        pace:ageDecline?Math.max(50,p.pace-rand(0,1)):p.pace,
      };
      // Sezon arası gelişim: genç oyuncular tatilde de ilerler (maç sayısı ve forma göre)
      const room=Math.max(0,(np.potential||np.overall)-np.overall);
      if(room>0&&np.age<=26){
        const avgR=p.formHistory?.length?p.formHistory.reduce((a,b)=>a+b,0)/p.formHistory.length:6;
        const pts=Math.round(ageGrow(p.age,diff)*(avgR>=7.5?5:avgR>=6.5?3:2)*(p.sm>=15?1:0.5));
        const wt=POS_GROWTH[np.pos]||POS_GROWTH.CM;
        const totW=wt.reduce((a,x)=>a+x[1],0);
        for(let g=0;g<pts;g++){
          let roll=Math.random()*totW;
          for(const[attr,wv]of wt){roll-=wv;if(roll<=0){np[attr]=Math.min(99,np[attr]+1);break;}}
        }
        if(pts>0)addLog(`📈 Sezon arası gelişim: +${pts} özellik puanı`);
      }
      np.overall=Math.min(np.potential,posWeight(np.pos,np));
      // ── FAZ 3: sezon sonu zihin ve kıdem ──
      np.mental=Math.min(100,(p.mental??100)+35);            // yaz tatili kafayı toparlar
      np.seasonsAtClub=(nextClub!==club)?0:(p.seasonsAtClub||0)+1;
      if(nextClub!==club) np.shirtNo=null;                   // yeni kulüpte numara yeniden seçilir
      // ── KUPA ODASI: bu sezon kazanılanlar rafa konur ──
      const cab=[...(p.trophyCabinet||[])];
      if(wasChamp) cab.push({id:"league",season,club:club.name,detail:getLg(club.leagueId).name});
      if(golKralı?.isMe) cab.push({id:"golden",season,club:club.name,detail:`${p.sg} gol`});
      if(promoted) cab.push({id:"promo",season,club:club.name,detail:`${getLg(club.leagueId).name} şampiyonu`});
      // titlesWonThisSeason kupa kimliklerini (cl/el/conf/tr_cup/wc) tutar
      (titlesWonThisSeason||[]).forEach(t=>{
        const id=["cl","el","conf","wc"].includes(t)?t:"cup";
        const detail=EURO_CUPS[t]?.name||(t==="tr_cup"?"Türkiye Kupası":t==="wc"?"Dünya Kupası":String(t));
        cab.push({id,season,club:club.name,detail});
      });
      np.trophyCabinet=cab;
      // ── KAPTANLIK: hoca sezon başında pazubandı dağıtır ──
      const capScore=captaincyScore(np,teammates,np.seasonsAtClub);
      const newCap=captaincyFor(capScore);
      if(newCap!==(p.captaincy||"none")){
        np.captaincy=newCap;
        const meta=CAPTAINCY.find(c=>c.id===newCap);
        setTimeout(()=>{
          if(newCap==="cap"){ notify("©️ KAPTAN SEÇİLDİN!",C.gold); addSocial(`©️ ${p.name} ${nextClub.name}'in yeni kaptanı!`); }
          else if(newCap==="vice"){ notify("🎗️ Vice-kaptan oldun.",C.accent); }
          else { notify("Pazubandı kaybettin.",C.muted); }
        },1400);
        if(meta){ np.morale=Math.min(100,np.morale+meta.moraleMod); np.managerTrust=Math.min(100,(np.managerTrust??70)+meta.trustMod); }
      }
      return checkAch(np,nextClub);
    });

    // Hedef ödülleri
    if(objTotal){
      setPlayer(p=>({...p,bank:Math.max(0,p.bank+objBank),
        managerTrust:Math.max(0,Math.min(100,(p.managerTrust??70)+objTrust)),
        fame:Math.max(0,Math.min(100,p.fame+objFame))}));
    }

    // Kulüp değiştiyse fikstür, tablo ve kadro yeni lige göre kurulur
    if(nextClub!==club){
      setClub(nextClub);
      setTeammates(mkTeammates(player.pos,nextClub.prestige));
    }
    setFixtures(mkFixtures(nextClub));
    setStandings(mkStandings(nextClub));
    setLeagueScorers(mkLeagueScorers(nextClub.leagueId,nextClub.name));
    // Avrupa kupası sezon başında kurulur, maçları sezona yayılır
    // Bilet YALNIZCA lig sırasıyla kazanılır. Prestij fallback'i kaldırıldı:
    // 14. bitirip büyük kulübe transfer olmak seni ŞL'ye sokmamalı.
    const nextSpot=euroSpotFor(nextClub.leagueId,myPos);
    setEuroCup(nextSpot?startEuroCup(nextSpot,nextClub,mkFixtures(nextClub).length):null);
    // Yeni sezonun hedefleri
    const nextFx=mkFixtures(nextClub);
    setSeasonObjectives(mkSeasonObjectives(nextClub,{...player,pos:player.pos},
      CLUBS.filter(c=>c.leagueId===nextClub.leagueId).length,nextFx.length));
    setMatchObjectives(mkMatchObjectives(player));
    setTitlesWonThisSeason([]);
    setTransferBan(false);
    retirePrompted.current=false;

    // ── SÖZLEŞME ──
    const yearsLeft=Math.max(0,contract.years-1);
    setContract(c=>({...c,years:yearsLeft,offer:null}));
    // Sadakat bonusu: sözleşmeyi sonuna kadar aynı kulüpte götürdüysen ödenir
    if(yearsLeft<=0&&contract.clauses?.loyalty&&nextClub===club){
      const loy=contract.clauses.loyalty;
      setPlayer(p=>({...p,bank:p.bank+loy,bonusEarned:(p.bonusEarned||0)+loy}));
      moves.push(`🤝 Sadakat bonusu ödendi: €${loy.toLocaleString("tr")}`);
    }
    // Şampiyonluk primi
    if(wasChamp&&contract.clauses?.titleBonus){
      const tb=contract.clauses.titleBonus;
      setPlayer(p=>({...p,bank:p.bank+tb,bonusEarned:(p.bonusEarned||0)+tb}));
      moves.push(`🏆 Şampiyonluk primi: €${tb.toLocaleString("tr")}`);
    }
    if(yearsLeft<=0){
      // Sözleşme bitti: oyuncu bonservissiz kaldı
      setFreeAgent(true);
      setFreeAgentOffers(buildFreeAgentOffers(player,nextClub));
      setShowFreeAgency(true);
      notify("📝 Sözleşmen bitti — bonservissiz kaldın!",C.orange);
      addLog("📝 Sözleşme sona erdi — serbest oyuncusun");
    }else if(yearsLeft===1){
      notify("📝 Sözleşmenin son yılı! Yenilemezsen serbest kalacaksın.",C.orange);
    }

    // `goals` KARİYER toplamıdır, sezon sonunda sıfırlanmaz; sıfırlanan seasonGoals'dur.
    // Ayrıca rakip sonsuza dek aynı kişi olmamalı: yaşlanınca ya da zaman
    // zaman yerini yeni bir yıldıza bırakır.
    setRival(r=>{
      const aged=(r.age||23)+1;
      const retire=aged>=36||(aged>=33&&Math.random()<0.4)||Math.random()<0.12;
      if(retire){
        const fresh=mkRival({...player,age:Math.max(19,player.age-rand(0,3))},[r.name]);
        setTimeout(()=>{
          notify(`🆕 Yeni rakibin: ${fresh.name} (${fresh.club})`,C.purple);
          addSocial(`📢 ${aged>=34?`${r.name} kariyerinin sonuna yaklaşıyor.`:`${r.name} artık aynı seviyede değil.`} Basın yeni rakibini ${fresh.name} olarak gösteriyor.`);
        },1600);
        return {...fresh,since:season+1};
      }
      return {...r,overall:Math.min(99,r.overall+rand(0,2)),
        age:aged,
        goals:(r.goals||0)+(r.seasonGoals||0),   // sezonu kariyere ekle
        seasonGoals:0,wins:0,losses:0,draws:0,streak:0,form:[],history:[],
        injured:false,injuredWeeks:0,mood:"neutral"};
    });
    // Takım arkadaşları da yaşlanır ve gelişir
    // Takım arkadaşları yaşlanır ve gelişir/geriler (alan adı `ovr`)
    setTeammates(ts=>ts.map(t=>{
      const age=(t.age||24)+1;
      const grow=age<=23?rand(0,3):age<=28?rand(-1,1):-rand(0,2);
      const retiring=age>=37;
      if(retiring){
        // Emekli olan yerine akademiden genç gelir
        return{...t,age:rand(18,21),ovr:Math.max(50,(t.ovr||65)-rand(6,14)),
          name:`${pick(TEAMMATE_FIRST_NAMES)} ${pick(TEAMMATE_LAST_NAMES)}`,
          goals:0,assists:0,chemistry:rand(55,80)};
      }
      return{...t,age,ovr:Math.max(45,Math.min(99,(t.ovr||65)+grow)),goals:0,assists:0};
    }));
    // Yeni sezon: forma numaranı seçme fırsatı
    setTimeout(()=>setShowNumberPick(true),1800);
    setTrained(0);
    notify(`🏆 Sezon ${season+1}!`,C.gold);
    addLog(`🔄 Sezon ${season+1} — ${player.age+1} yaş · Lig ${myPos}. sıra`);
    moves.forEach(m=>addLog(m));
  }

  // Bonservissiz kalan oyuncuya gelen teklifler
  function buildFreeAgentOffers(p,curClub){
    const ovr=p.overall||60;
    const maxPrestige=ovr>=88?10:ovr>=82?9:ovr>=76?8:ovr>=70?6:ovr>=64?5:4;
    const pool=CLUBS.filter(c=>c.prestige<=maxPrestige&&c.prestige>=Math.max(1,maxPrestige-4)&&c.name!==curClub?.name);
    const mgr=MANAGERS.find(m=>m.id===manager);
    const salMul=mgr?.salBonus||1;
    return pool.sort(()=>Math.random()-.5).slice(0,4).map(c=>({
      from:c,
      years:rand(2,4),
      salary:Math.max(4,Math.round(wageFor(c.prestige,ovr)*salMul)),
    }));
  }

  const sorted=sortTable(standings);
  const myLeaguePos=sorted.findIndex(t=>t.isMe)+1;
  const phase=getPhase(player.overall);
  const NAV=[
    {id:"Ana",  icon:"⚡", label:"Ana"},
    {id:"Maç",  icon:"⚽", label:"Saha"},
    {id:"Kulüp",icon:"🏟️", label:"Kulüp"},
    {id:"Dünya",icon:"🌍", label:"Dünya"},
  ];
  // ══════════ YATAY EKRANLAR ══════════
  const landscape=useLandscape();
  // Hakem adı sezon+haftadan türetilir: aynı maçta ekran her yenilendiğinde değişmez.
  const refereeFor=(sn,wk)=>{const h=(sn*131+wk*17)>>>0;
    return `${TEAMMATE_FIRST_NAMES[h%TEAMMATE_FIRST_NAMES.length]} ${TEAMMATE_LAST_NAMES[(h*7+3)%TEAMMATE_LAST_NAMES.length]}`;};
  const levelPct=(()=>{
    const cur=xpForLevel(player.level||1), next=xpForLevel((player.level||1)+1);
    return next>cur?((player.xp-cur)/(next-cur))*100:0;
  })();
  const lsHud=(extra)=>(<HudBar club={club} player={player} level={player.level||1} levelPct={levelPct}
    gp={player.bank} gold={Math.round((player.fame||0)*10+(player.wheelSpinsLeft||0)*50)}
    onSettings={()=>setShowGameSettings(true)} onMenu={()=>setShowDrawer(true)} right={extra}/>);

