          {coachDialogue.morale!=null&&<Bdg c={coachDialogue.morale>0?C.green:C.red}>Moral {coachDialogue.morale>0?"+":""}{coachDialogue.morale}</Bdg>}
          {coachDialogue.trust!=null&&<Bdg c={coachDialogue.trust>0?C.accent:C.red}>Güven {coachDialogue.trust>0?"+":""}{coachDialogue.trust}</Bdg>}
